struct 结构_根特征必要条件定义_线程侧 {
    枚举_自我根特征类型_线程侧 根特征类型 = 枚举_自我根特征类型_线程侧::安全;
    std::string 条件键{};
    std::string 检查宿主语义{};
    const 语素入口节点类* 检查特征类型 = nullptr;
    std::string 目标状态文本{};
    I64 目标值 = 1;
    std::string 缺口需求名称文本{};
    const 语素入口节点类* 缺口需求名称 = nullptr;
    const 语素入口节点类* 缺口目标特征类型 = nullptr;
    抽象特征节点类* 条件定义节点 = nullptr;

    // 功能：按函数名执行对应处理。
    bool 有效() const noexcept
    {
        return !条件键.empty()
            && !检查宿主语义.empty()
            && 检查特征类型
            && 缺口目标特征类型
            && 目标值 != I64_MAX;
    }
};

