// 功能：服务所在模块的内部辅助流程。
std::string 私有_I64区间文本_线程侧(const I64区间& 区间)
{
    return "[" + std::to_string(区间.低值) + "," + std::to_string(区间.高值) + "]";
}

// 功能：从指定来源读取数据或状态。
bool 私有_读取抽象特征I64区间_线程侧(
    const 抽象特征主信息类* 主信息,
    I64区间& 输出) noexcept
{
    if (!主信息) {
        return false;
    }
    if (主信息->区间.has_value() && 主信息->区间->有效()) {
        输出 = *主信息->区间;
        return true;
    }
    if (!主信息->值域.has_value()) {
        return false;
    }
    const auto* I64域 = std::get_if<I64值域>(&主信息->值域.value());
    if (!I64域) {
        return false;
    }

    bool 已命中 = false;
    I64 低值 = 0;
    I64 高值 = 0;
    for (const auto& 项 : I64域->项集) {
        I64区间 当前区间{ 0, -1 };
        if (const auto* 区间 = std::get_if<I64区间>(&项)) {
            当前区间 = *区间;
        }
        else if (const auto* 点 = std::get_if<I64>(&项)) {
            当前区间 = I64区间::点(*点);
        }
        if (!当前区间.有效()) {
            continue;
        }
        if (!已命中) {
            低值 = 当前区间.低值;
            高值 = 当前区间.高值;
            已命中 = true;
        }
        else {
            低值 = (std::min<I64>)(低值, 当前区间.低值);
            高值 = (std::max<I64>)(高值, 当前区间.高值);
        }
    }
    if (!已命中) {
        return false;
    }
    输出 = I64区间{ 低值, 高值 };
    return 输出.有效();
}

// 功能：按条件查找目标对象、方法或事实。
抽象特征节点类* 私有_查找子抽象特征_按语素入口_线程侧(
    const 基础信息节点类* 父抽象特征,
    const 语素入口节点类* 目标入口) noexcept
{
    if (!父抽象特征 || !目标入口) {
        return nullptr;
    }
    for (auto* 节点 : 私有_直接基础信息子节点_按类型_线程侧<抽象特征主信息类>(世界树.基础信息(), 父抽象特征)) {
        auto* 抽象节点 = static_cast<抽象特征节点类*>(节点);
        const auto* 主信息 = 世界树.特征().取抽象特征主信息(抽象节点);
        if (!主信息) {
            continue;
        }
        if (私有_语素入口主键相等_线程侧(主信息->类型, 目标入口)
            || 私有_语素入口主键相等_线程侧(主信息->名称, 目标入口)) {
            return 抽象节点;
        }
    }
    return nullptr;
}

// 功能：从指定来源读取数据或状态。
结构_抽象根特征定义_线程侧 私有_读取抽象根特征定义_线程侧(
    const 枚举_自我根特征类型_线程侧 根特征类型) noexcept
{
    结构_抽象根特征定义_线程侧 定义{};
    定义.根特征类型 = 根特征类型;
    定义.自我特征类型 = 私有_自我根特征类型词_线程侧(根特征类型);
    if (!定义.自我特征类型) {
        定义.读取状态 = 枚举_抽象根特征定义读取状态_线程侧::自我特征类型缺失;
        return 定义;
    }

    auto* 抽象根 = 世界树.抽象特征根;
    if (!抽象根) {
        定义.读取状态 = 枚举_抽象根特征定义读取状态_线程侧::抽象特征根缺失;
        return 定义;
    }

    定义.抽象定义节点 = 世界树.特征().查找子抽象特征_按类型(
        抽象根,
        定义.自我特征类型);
    if (!定义.抽象定义节点) {
        定义.读取状态 = 枚举_抽象根特征定义读取状态_线程侧::根定义节点缺失;
        return 定义;
    }

    const auto* 根主信息 = 世界树.特征().取抽象特征主信息(定义.抽象定义节点);
    if (!根主信息) {
        定义.读取状态 = 枚举_抽象根特征定义读取状态_线程侧::根定义主信息缺失;
        return 定义;
    }

    定义.目标状态节点 = 私有_查找子抽象特征_按语素入口_线程侧(
        定义.抽象定义节点,
        私有_特征模板词_线程侧("最大值"));
    if (!定义.目标状态节点) {
        定义.目标状态节点 = 私有_查找子抽象特征_按语素入口_线程侧(
            定义.抽象定义节点,
            私有_特征模板词_线程侧("高位"));
    }
    if (定义.目标状态节点) {
        const auto* 主信息 = 世界树.特征().取抽象特征主信息(定义.目标状态节点);
        定义.目标区间有效 = 私有_读取抽象特征I64区间_线程侧(
            主信息,
            定义.目标区间);
    }

    定义.最低阈值状态节点 = 私有_查找子抽象特征_按语素入口_线程侧(
        定义.抽象定义节点,
        私有_特征模板词_线程侧("基础稳定带"));
    if (定义.最低阈值状态节点) {
        const auto* 主信息 = 世界树.特征().取抽象特征主信息(定义.最低阈值状态节点);
        定义.最低阈值区间有效 = 私有_读取抽象特征I64区间_线程侧(
            主信息,
            定义.最低阈值区间);
    }

    if (!定义.目标状态节点 || !定义.目标区间有效) {
        定义.读取状态 = 枚举_抽象根特征定义读取状态_线程侧::目标状态缺失;
        return 定义;
    }

    定义.读取状态 = 枚举_抽象根特征定义读取状态_线程侧::已读取;
    return 定义;
}

// 功能：服务所在模块的内部辅助流程。
std::string 私有_抽象根特征定义摘要_线程侧(const 结构_抽象根特征定义_线程侧& 定义)
{
    std::ostringstream 输出;
    输出 << "自我线程/抽象根特征定义读取"
        << " | 根特征=" << 私有_根特征类型文本_线程侧(定义.根特征类型)
        << " | 状态=" << 私有_抽象根特征定义读取状态文本_线程侧(定义.读取状态)
        << " | 自我特征=" << 私有_需求类型标题(定义.自我特征类型)
        << " | 定义节点=" << (定义.抽象定义节点 ? 定义.抽象定义节点->获取主键() : std::string("空"))
        << " | 目标状态=" << (定义.目标状态节点 ? 定义.目标状态节点->获取主键() : std::string("空"))
        << " | 目标区间=" << (定义.目标区间有效 ? 私有_I64区间文本_线程侧(定义.目标区间) : std::string("无"))
        << " | 最低阈值状态=" << (定义.最低阈值状态节点 ? 定义.最低阈值状态节点->获取主键() : std::string("空"))
        << " | 最低阈值区间=" << (定义.最低阈值区间有效 ? 私有_I64区间文本_线程侧(定义.最低阈值区间) : std::string("无"));
    return 输出.str();
}

// 功能：从指定来源读取数据或状态。
void 私有_记录抽象根特征定义读取_线程侧(const 结构_抽象根特征定义_线程侧& 定义) noexcept
{
    const auto 摘要 = 私有_抽象根特征定义摘要_线程侧(定义);
    static std::mutex 记录锁;
    static std::unordered_set<std::string> 已记录摘要;
    {
        std::lock_guard<std::mutex> lk{ 记录锁 };
        if (!已记录摘要.insert(摘要).second) {
            return;
        }
    }
    if (定义.成功()) {
        项目运行日志(摘要);
    }
    else {
        项目运行警告日志(摘要);
    }
}

