// 功能：服务所在模块的内部辅助流程。
I64 私有_计数转I64(const std::uint64_t 值) noexcept
{
    const auto 上限 = static_cast<std::uint64_t>(std::numeric_limits<I64>::max());
    if (值 > 上限) {
        return std::numeric_limits<I64>::max();
    }
    return static_cast<I64>(值);
}

// 功能：服务所在模块的内部辅助流程。
I64 私有_夹紧非负上限_线程侧(I64 值, I64 上限) noexcept
{
    if (值 <= 0 || 上限 <= 0) {
        return 0;
    }
    return (std::min<I64>)(值, 上限);
}

// 功能：计算权重、状态、差值或派生结果。
I64 私有_计算风险安全第二层投影候选_线程侧(I64 风险安全层候选) noexcept
{
    const I64 满刻度 = (std::numeric_limits<I64>::max)();
    const I64 层值 = 私有_夹紧非负上限_线程侧(风险安全层候选, 满刻度);
    const I64 商 = 层值 / 100;
    const I64 余 = 层值 % 100;
    return 私有_夹紧非负上限_线程侧(商 * 9 + (余 * 9) / 100, 满刻度);
}

// 功能：服务所在模块的内部辅助流程。
I64 私有_安全乘除_I64_线程侧(I64 左, I64 右, I64 分母) noexcept
{
    if (左 <= 0 || 右 <= 0 || 分母 <= 0) {
        return 0;
    }
    const auto 上限 = static_cast<std::uint64_t>((std::numeric_limits<I64>::max)());
    const auto a = static_cast<std::uint64_t>(左);
    const auto b = static_cast<std::uint64_t>(右);
    const auto d = static_cast<std::uint64_t>(分母);

#if defined(_MSC_VER) && defined(_M_X64)
    unsigned __int64 高位 = 0;
    const auto 低位 = _umul128(
        static_cast<unsigned __int64>(a),
        static_cast<unsigned __int64>(b),
        &高位);
    if (高位 >= static_cast<unsigned __int64>(d)) {
        return std::numeric_limits<I64>::max();
    }
    unsigned __int64 余数 = 0;
    const auto 商 = _udiv128(
        高位,
        低位,
        static_cast<unsigned __int64>(d),
        &余数);
    return 商 > 上限
        ? (std::numeric_limits<I64>::max)()
        : static_cast<I64>(商);
#elif defined(__SIZEOF_INT128__)
    const auto 乘积 =
        static_cast<unsigned __int128>(a) * static_cast<unsigned __int128>(b);
    const auto 商 = 乘积 / d;
    return 商 > 上限
        ? (std::numeric_limits<I64>::max)()
        : static_cast<I64>(商);
#else
    std::uint64_t 商 = 0;
    std::uint64_t 余数 = 0;
    std::uint64_t 项商 = a / d;
    std::uint64_t 项余 = a % d;

    const auto 饱和加 = [上限](std::uint64_t 左值, std::uint64_t 右值) noexcept {
        return 左值 > 上限 - 右值 ? 上限 : 左值 + 右值;
    };

    for (std::uint32_t 位 = 0; 位 < 63 && 位 < sizeof(b) * 8; ++位) {
        if ((b & (std::uint64_t{1} << 位)) != 0) {
            商 = 饱和加(商, 项商);
            余数 += 项余;
            if (余数 >= d || 余数 < 项余) {
                余数 -= d;
                商 = 饱和加(商, 1);
            }
        }

        if (位 + 1 >= 63 || 位 + 1 >= sizeof(b) * 8) {
            break;
        }
        const bool 项商溢出 = 项商 > 上限 / 2;
        项商 = 项商溢出 ? 上限 : 项商 * 2;
        项余 *= 2;
        if (项余 >= d) {
            项余 -= d;
            项商 = 饱和加(项商, 1);
        }
    }

    return 商 >= 上限 ? (std::numeric_limits<I64>::max)() : static_cast<I64>(商);
#endif
}

// 功能：计算权重、状态、差值或派生结果。
I64 私有_按百万分比计算目标值_线程侧(I64 权重上限, I64 比例_百万分比) noexcept
{
    const I64 比例 = std::clamp<I64>(比例_百万分比, 0, 1'000'000);
    return (std::min<I64>)(
        (std::max<I64>)(0, 权重上限),
        私有_安全乘除_I64_线程侧(权重上限, 比例, 1'000'000));
}

// 功能：计算权重、状态、差值或派生结果。
I64 私有_计算反馈增量_线程侧(
    I64 权重上限,
    I64 已折算值,
    I64 本次满足量,
    I64 累计比例_百万分比) noexcept
{
    const I64 剩余额度 = (std::max<I64>)(0, 权重上限 - (std::max<I64>)(0, 已折算值));
    if (剩余额度 <= 0) {
        return 0;
    }
    if (累计比例_百万分比 >= 0) {
        const I64 目标值 = 私有_按百万分比计算目标值_线程侧(权重上限, 累计比例_百万分比);
        return (std::min<I64>)(剩余额度, (std::max<I64>)(0, 目标值 - 已折算值));
    }
    return 私有_夹紧非负上限_线程侧(本次满足量, 剩余额度);
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_是增量反馈_线程侧(const 结构_线程任务价值反馈段& 反馈) noexcept
{
    return (反馈.本次安全满足量 > 0 && 反馈.安全累计比例_百万分比 < 0)
        || (反馈.本次服务满足量 > 0 && 反馈.服务累计比例_百万分比 < 0);
}

// 功能：登记方法、模板、对象或运行入口。
bool 私有_登记增量反馈事件_线程侧(
    const std::string& 任务主键,
    const std::string& 反馈事件主键,
    结构_线程价值结算结果& 结果) noexcept
{
    if (反馈事件主键.empty()) {
        结果.摘要 = "任务价值反馈结算失败 | 原因=增量反馈缺少反馈事件主键";
        return false;
    }
    std::scoped_lock 锁(g_线程价值反馈事件锁);
    auto& 已处理集 = g_任务已处理反馈事件_线程侧[任务主键];
    if (已处理集.contains(反馈事件主键)) {
        结果.成功 = true;
        结果.已处理 = true;
        结果.已去重 = true;
        结果.摘要 = "任务价值反馈结算 | 增量反馈事件已处理，跳过去重";
        return false;
    }
    已处理集.insert(反馈事件主键);
    return true;
}

// 功能：结算任务、需求、价值或结果贡献。
std::string 私有_正式结算结果目标键_线程侧(
    const 任务节点* 任务头,
    const 需求节点* 来源需求,
    const 结构_叶子任务正式结算证据& 证据)
{
    if (!任务头
        || !来源需求
        || !证据.目标宿主
        || !证据.目标特征类型
        || (!证据.D0_业务动作动态 && !证据.actual状态)) {
        return {};
    }
    const std::string 结果证据键 = 证据.D0_业务动作动态
        ? ("D0:" + 证据.D0_业务动作动态->获取主键())
        : ("actual:" + 证据.actual状态->获取主键());

    return 任务头->获取主键()
        + "|"
        + 来源需求->获取主键()
        + "|"
        + 结果证据键
        + "|"
        + 证据.目标宿主->获取主键()
        + "|"
        + 证据.目标特征类型->获取主键();
}

// 功能：结算任务、需求、价值或结果贡献。
bool 私有_正式结算结果目标已处理_线程侧(const std::string& 去重键) noexcept
{
    if (去重键.empty()) {
        return false;
    }

    std::scoped_lock 锁(g_线程价值反馈事件锁);
    return g_正式结算结果目标键_线程侧.contains(去重键);
}

// 功能：登记方法、模板、对象或运行入口。
void 私有_登记正式结算结果目标_线程侧(const std::string& 去重键) noexcept
{
    if (去重键.empty()) {
        return;
    }

    std::scoped_lock 锁(g_线程价值反馈事件锁);
    g_正式结算结果目标键_线程侧.insert(去重键);
}

std::string 私有_拼接结算投影缺失证据_线程侧(
    const std::vector<std::string>& 缺失证据,
    std::size_t 上限);

// 功能：服务所在模块的内部辅助流程。
bool 私有_特征值非空_线程侧(const 特征值& 值) noexcept
{
    return !std::holds_alternative<std::monostate>(值);
}

// 功能：服务所在模块的内部辅助流程。
I64 私有_服务G0百万分比转评分_线程侧(I64 百万分比) noexcept
{
    百万分比 = std::clamp<I64>(百万分比, 0, 1'000'000);
    return std::clamp<I64>((百万分比 + 50) / 100, 0, 服务模块::服务评分_满分);
}

// 功能：服务所在模块的内部辅助流程。
I64 私有_服务G0有效性评分_线程侧(
    const 结构_线程服务价值结算证据摘要* 服务证据摘要,
    const 结构_叶子任务正式结算证据& 正式结算证据) noexcept
{
    if (!服务证据摘要 || !服务证据摘要->有服务对象外在特征状态改善证据) {
        return 0;
    }
    if (正式结算证据.actual满足目标 && 服务证据摘要->可结算服务值()) {
        return 服务模块::服务评分_满分;
    }
    if (服务证据摘要->可结算服务值()) {
        return static_cast<I64>(服务模块::枚举_服务有效性档位::主要解决需求);
    }
    if (正式结算证据.actual有推进) {
        return static_cast<I64>(服务模块::枚举_服务有效性档位::部分解决需求);
    }
    return static_cast<I64>(服务模块::枚举_服务有效性档位::假定有交付);
}

// 功能：服务所在模块的内部辅助流程。
I64 私有_服务G0证据强度评分_线程侧(
    const 结构_线程服务价值结算证据摘要* 服务证据摘要,
    const 结构_叶子任务正式结算证据& 正式结算证据,
    动态节点类* D1任务状态动作动态) noexcept
{
    if (正式结算证据.D0_业务动作动态
        && D1任务状态动作动态
        && 服务证据摘要
        && 服务证据摘要->可结算服务值()) {
        return static_cast<I64>(服务模块::枚举_服务证据强度档位::完整证据链);
    }
    if ((正式结算证据.D0_业务动作动态 || 正式结算证据.任务完成动作动态)
        && D1任务状态动作动态
        && 服务证据摘要
        && 服务证据摘要->服务结果可验证) {
        return static_cast<I64>(服务模块::枚举_服务证据强度档位::前后对比且可验证);
    }
    if (正式结算证据.actual状态 || D1任务状态动作动态) {
        return static_cast<I64>(服务模块::枚举_服务证据强度档位::单侧状态或接受);
    }
    if (正式结算证据.D0_业务动作动态 || 正式结算证据.任务完成动作动态) {
        return static_cast<I64>(服务模块::枚举_服务证据强度档位::只有自我输出);
    }
    return static_cast<I64>(服务模块::枚举_服务证据强度档位::无证据);
}

// 功能：确认候选事实、存在、状态或运行结果。
服务模块::枚举_服务硬门槛状态 私有_服务G0门槛_待确认或成立_线程侧(bool 成立) noexcept
{
    return 成立
        ? 服务模块::枚举_服务硬门槛状态::成立
        : 服务模块::枚举_服务硬门槛状态::待确认;
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_服务对象外在特征状态变化项有改善证据_线程侧(
    const 结构_任务管理状态变化项& 变化项) noexcept
{
    if (!私有_特征值非空_线程侧(变化项.变化前值)
        || !私有_特征值非空_线程侧(变化项.变化后值)) {
        return false;
    }

    const auto* 前数值 = std::get_if<I64>(&变化项.变化前值);
    const auto* 后数值 = std::get_if<I64>(&变化项.变化后值);
    if (前数值 && 后数值) {
        return *后数值 > *前数值;
    }
    return !(变化项.变化前值 == 变化项.变化后值);
}

// 功能：结算任务、需求、价值或结果贡献。
void 私有_追加服务价值结算缺失证据_线程侧(
    结构_线程服务价值结算证据摘要& 摘要,
    std::string 缺失项)
{
    if (!缺失项.empty()
        && std::find(摘要.缺失证据.begin(), 摘要.缺失证据.end(), 缺失项)
            == 摘要.缺失证据.end()) {
        摘要.缺失证据.push_back(std::move(缺失项));
    }
}

// 功能：评估状态、风险、质量、权重或完成度。
结构_线程服务价值结算证据摘要 私有_评估服务价值结算证据_线程侧(
    const std::vector<结构_任务管理状态变化项>* 服务对象状态变化集,
    const 结构_叶子任务正式结算证据& 正式结算证据)
{
    结构_线程服务价值结算证据摘要 结果{};
    const bool 有自我动作来源 =
        正式结算证据.D0_业务动作动态 != nullptr
        || 正式结算证据.任务完成动作动态 != nullptr;

    if (服务对象状态变化集) {
        结果.服务对象外在特征状态变化数 = 服务对象状态变化集->size();
        for (const auto& 变化项 : *服务对象状态变化集) {
            const bool 有改善证据 =
                私有_服务对象外在特征状态变化项有改善证据_线程侧(变化项);
            结果.有服务对象外在特征状态改善证据 =
                结果.有服务对象外在特征状态改善证据 || 有改善证据;
            结果.服务结果可验证 =
                结果.服务结果可验证 || (有改善证据 && 变化项.已确认生效);
            结果.服务结果可归因于自我动作 =
                结果.服务结果可归因于自我动作
                || (有改善证据
                    && 有自我动作来源
                    && !变化项.变化原因键.empty());
        }
    }

    if (结果.服务对象外在特征状态变化数 == 0) {
        私有_追加服务价值结算缺失证据_线程侧(结果, "缺服务对象外在特征状态变化集");
    }
    if (!结果.有服务对象外在特征状态改善证据) {
        私有_追加服务价值结算缺失证据_线程侧(结果, "缺服务对象外在特征状态改善证据");
    }
    if (!结果.服务结果可验证) {
        私有_追加服务价值结算缺失证据_线程侧(结果, "缺服务对象外在反馈验证证据");
    }
    if (!结果.服务结果可归因于自我动作) {
        私有_追加服务价值结算缺失证据_线程侧(结果, "缺服务结果归因证据");
    }

    std::ostringstream 输出;
    输出 << "服务价值结算证据"
        << " | 服务对象外在特征状态变化数=" << 结果.服务对象外在特征状态变化数
        << " | 外在改善证据=" << (结果.有服务对象外在特征状态改善证据 ? "有" : "缺")
        << " | 外在反馈可验证=" << (结果.服务结果可验证 ? "是" : "否")
        << " | 可归因=" << (结果.服务结果可归因于自我动作 ? "是" : "否");
    if (!结果.缺失证据.empty()) {
        输出 << " | 缺失证据="
            << 私有_拼接结算投影缺失证据_线程侧(结果.缺失证据, 5);
    }
    结果.摘要 = 输出.str();
    return 结果;
}

// 功能：把处理结果写入指定对象、场景或日志。
bool 私有_写入G0线程侧证据材料(
    存在节点类* G0治理视图,
    const 结构_叶子任务正式结算证据& 正式结算证据,
    const 结构_线程服务价值结算证据摘要* 服务证据摘要,
    时间戳 now) noexcept
{
    auto* 宿主 = G0治理视图 ? reinterpret_cast<基础信息节点类*>(G0治理视图) : nullptr;
    if (!宿主) {
        return false;
    }
    bool ok = true;
    if (正式结算证据.actual状态) {
        ok = 世界树.写入特征_指针(
            宿主,
            私有_需求动作动态特征词("实际结果状态"),
            正式结算证据.actual状态,
            now) && ok;
    }
    if (正式结算证据.输出结果场景) {
        ok = 世界树.写入特征_指针(
            宿主,
            私有_需求动作动态特征词("输出结果场景"),
            正式结算证据.输出结果场景,
            now) && ok;
    }
    if (服务证据摘要) {
        const auto 状态变化数 =
            (std::min<std::size_t>)(服务证据摘要->服务对象外在特征状态变化数,
                static_cast<std::size_t>((std::numeric_limits<I64>::max)()));
        ok = 世界树.写入特征_I64(
            宿主,
            私有_需求动作动态特征词("服务对象外在特征状态变化数"),
            static_cast<I64>(状态变化数),
            now) && ok;
        ok = 世界树.写入特征_I64(
            宿主,
            私有_需求动作动态特征词("服务对象外在特征状态改善证据"),
            服务证据摘要->有服务对象外在特征状态改善证据 ? 1 : 0,
            now) && ok;
        ok = 世界树.写入特征_I64(
            宿主,
            私有_需求动作动态特征词("服务结果可验证"),
            服务证据摘要->服务结果可验证 ? 1 : 0,
            now) && ok;
        ok = 世界树.写入特征_I64(
            宿主,
            私有_需求动作动态特征词("服务结果可归因于自我动作"),
            服务证据摘要->服务结果可归因于自我动作 ? 1 : 0,
            now) && ok;
    }
    return ok;
}

// 功能：根据当前输入生成目标数据、场景、动态或回执。
结构_线程成功服务G0候选结果 私有_生成成功服务G0候选_线程侧(
    任务节点* 任务头,
    需求节点* 来源需求,
    const 结构_叶子任务正式结算证据& 正式结算证据,
    const 结构_线程服务价值结算证据摘要* 服务证据摘要,
    I64 服务完成度百万分比,
    I64 标准服务单位,
    动态节点类* D1任务状态动作动态,
    const std::string& 非重复去重键,
    时间戳 now) noexcept
{
    结构_线程成功服务G0候选结果 结果{};
    结果.已尝试 = true;
    if (!任务头 || !来源需求) {
        结果.摘要 = "成功服务G0候选生成失败 | 原因=任务或来源需求为空";
        return 结果;
    }

    服务模块::服务G0候选组装输入 输入{};
    输入.任务节点 = 任务头;
    输入.D0 = 正式结算证据.D0_业务动作动态;
    输入.D1 = D1任务状态动作动态;
    输入.写入评分 = true;
    输入.评分.完成度 = 私有_服务G0百万分比转评分_线程侧(服务完成度百万分比);
    输入.评分.有效性 = 私有_服务G0有效性评分_线程侧(服务证据摘要, 正式结算证据);
    输入.评分.证据强度 =
        私有_服务G0证据强度评分_线程侧(服务证据摘要, 正式结算证据, D1任务状态动作动态);
    输入.安全通过 = 服务模块::枚举_服务硬门槛状态::待确认;
    输入.改善结果可验证 = 私有_服务G0门槛_待确认或成立_线程侧(
        服务证据摘要 && 服务证据摘要->服务结果可验证);
    输入.改善可归因于自我动作 = 私有_服务G0门槛_待确认或成立_线程侧(
        服务证据摘要 && 服务证据摘要->服务结果可归因于自我动作);
    输入.非重复服务 = 私有_服务G0门槛_待确认或成立_线程侧(!非重复去重键.empty());
    输入.闭环回写成立 = 私有_服务G0门槛_待确认或成立_线程侧(D1任务状态动作动态 != nullptr);

    const auto 组装结果 = 服务模块::组装G0成功服务候选(输入, now);
    结果.G0治理视图 = 组装结果.G0治理视图;
    结果.候选状态 = static_cast<I64>(组装结果.候选状态);
    结果.服务层级 = static_cast<I64>(组装结果.层级);
    if (!组装结果.成功 || !组装结果.G0治理视图) {
        std::ostringstream 摘要;
        摘要 << "成功服务G0候选生成失败"
            << " | 任务=" << 任务头->获取主键()
            << " | 需求=" << 来源需求->获取主键()
            << " | 原因=G0组装失败";
        结果.摘要 = 摘要.str();
        return 结果;
    }

    const bool 证据材料已写 =
        私有_写入G0线程侧证据材料(
            组装结果.G0治理视图,
            正式结算证据,
            服务证据摘要,
            now);
    if (!证据材料已写) {
        项目运行警告日志(
            "成功服务G0候选证据材料写入失败"
            " | 任务=" + 任务头->获取主键()
            + " | 需求=" + 来源需求->获取主键());
    }
    (void)世界树.写入特征_I64(
        reinterpret_cast<基础信息节点类*>(组装结果.G0治理视图),
        服务模块::特征_标准服务单位(),
        (std::max<I64>)(0, 标准服务单位),
        now);

    if (组装结果.候选状态 == 服务模块::枚举_成功服务候选状态::待确认
        || 组装结果.候选状态 == 服务模块::枚举_成功服务候选状态::可接受候选) {
        const auto 候选记录结果 =
            服务模块::登记成功服务候选记录(
                任务头,
                组装结果.G0治理视图,
                0,
                0,
                nullptr,
                now);
        if (候选记录结果.成功) {
            结果.候选记录 = 候选记录结果.候选记录;
            (void)世界树.写入特征_I64(
                reinterpret_cast<基础信息节点类*>(结果.候选记录),
                服务模块::特征_标准服务单位(),
                (std::max<I64>)(0, 标准服务单位),
                now);
        }
    }

    结果.成功 = true;
    std::ostringstream 摘要;
    摘要 << "成功服务G0候选生成"
        << " | 任务=" << 任务头->获取主键()
        << " | 需求=" << 来源需求->获取主键()
        << " | G0=" << (结果.G0治理视图 ? 结果.G0治理视图->获取主键() : std::string("缺"))
        << " | 候选状态=" << 结果.候选状态
        << " | 服务层级=" << 结果.服务层级
        << " | 候选记录=" << (结果.候选记录 ? 结果.候选记录->获取主键() : std::string("缺"))
        << " | D0=" << (正式结算证据.D0_业务动作动态
            ? 正式结算证据.D0_业务动作动态->获取主键()
            : std::string("缺"))
        << " | D1=" << (D1任务状态动作动态 ? D1任务状态动作动态->获取主键() : std::string("缺"))
        << " | 安全通过=待确认"
        << " | 不写服务值=1";
    结果.摘要 = 摘要.str();
    项目运行日志(结果.摘要);
    return 结果;
}

// 功能：服务所在模块的内部辅助流程。
结构_线程G0服务值饱和入账结果 私有_尝试G0服务值饱和入账_线程侧(
    自我类& 自我对象,
    任务节点* 任务头,
    需求节点* 来源需求,
    const 结构_线程成功服务G0候选结果& G0候选结果,
    I64 标准服务单位,
    动态节点类* D0,
    动态节点类* D1,
    时间戳 now) noexcept
{
    结构_线程G0服务值饱和入账结果 结果{};
    结果.已尝试 = true;
    结果.旧服务值 = 自我对象.获取服务值();
    结果.新服务值 = 结果.旧服务值;

    if (标准服务单位 <= 0) {
        结果.摘要 = "成功服务G0饱和入账跳过 | 原因=标准服务单位为0";
        return 结果;
    }
    if (!任务头 || !来源需求 || !G0候选结果.G0治理视图 || !G0候选结果.候选记录) {
        std::ostringstream 摘要;
        摘要 << "成功服务G0饱和入账暂不执行"
            << " | 任务=" << (任务头 ? 任务头->获取主键() : std::string("空"))
            << " | 需求=" << (来源需求 ? 来源需求->获取主键() : std::string("空"))
            << " | 原因=G0或候选记录缺失"
            << " | 不写服务值=1";
        结果.摘要 = 摘要.str();
        项目运行日志(结果.摘要);
        return 结果;
    }

    const auto 复核结果 =
        服务模块::复核成功服务候选记录(G0候选结果.候选记录, now);
    if (!复核结果.成功 || !复核结果.可结算) {
        std::ostringstream 摘要;
        摘要 << "成功服务G0饱和入账暂不执行"
            << " | 任务=" << 任务头->获取主键()
            << " | 需求=" << 来源需求->获取主键()
            << " | G0=" << G0候选结果.G0治理视图->获取主键()
            << " | 候选记录=" << G0候选结果.候选记录->获取主键()
            << " | 候选状态=" << static_cast<I64>(复核结果.候选状态)
            << " | 复核成功=" << (复核结果.成功 ? "是" : "否")
            << " | 可结算=" << (复核结果.可结算 ? "是" : "否")
            << " | 不写服务值=1";
        结果.摘要 = 摘要.str();
        项目运行日志(结果.摘要);
        return 结果;
    }

    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 自我内部世界 = 自我对象.确保自我内部世界();
    if (!自我存在 || !自我内部世界) {
        结果.摘要 = "成功服务G0饱和入账失败 | 原因=自我存在或内部世界缺失";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    服务模块::服务值结算计算输入 输入{};
    输入.G0治理视图 = 复核结果.G0治理视图
        ? 复核结果.G0治理视图
        : G0候选结果.G0治理视图;
    输入.候选记录 = 复核结果.候选记录
        ? 复核结果.候选记录
        : G0候选结果.候选记录;
    输入.当前服务值 = 自我对象.获取服务值();
    输入.服务值上限 = 自我对象.根目标服务值();
    输入.标准服务单位 = 标准服务单位;
    输入.非重复系数 = 服务模块::服务评分_满分;
    输入.安全调节 = 服务模块::服务评分_满分;
    输入.单次lambda上限 = 服务模块::服务评分_满分;

    const auto 计算结果 = 服务模块::计算成功服务值饱和入账(输入);
    (void)服务模块::写入服务值结算候选结果(
        reinterpret_cast<基础信息节点类*>(输入.G0治理视图),
        输入,
        计算结果,
        now);
    (void)服务模块::写入服务值结算候选结果(
        reinterpret_cast<基础信息节点类*>(输入.候选记录),
        输入,
        计算结果,
        now);
    if (!计算结果.可结算) {
        std::ostringstream 摘要;
        摘要 << "成功服务G0饱和入账暂不执行"
            << " | 任务=" << 任务头->获取主键()
            << " | 需求=" << 来源需求->获取主键()
            << " | G0=" << 输入.G0治理视图->获取主键()
            << " | 候选记录=" << 输入.候选记录->获取主键()
            << " | 当前服务值=" << 输入.当前服务值
            << " | 服务值上限=" << 输入.服务值上限
            << " | lambda候选=" << 计算结果.lambda候选
            << " | lambda使用=" << 计算结果.lambda使用
            << " | 不写服务值=1";
        结果.摘要 = 摘要.str();
        项目运行日志(结果.摘要);
        return 结果;
    }

    auto* 方法首节点 = 本能方法类::查找或创建本能方法首节点(
        自我存在,
        枚举_本能方法ID::自我_结算叶子任务价值,
        now);
    auto* 服务值特征 = 世界树.取或创建子特征_按类型(
        reinterpret_cast<基础信息节点类*>(自我存在),
        私有_自我根特征类型词_线程侧(枚举_自我根特征类型_线程侧::服务));
    const auto* 输入场景名 = 语素集.添加信息入口词(
        "G0成功服务值饱和入账_输入_" + std::to_string(now),
        枚举_信息入口类型::场景实例入口);
    const auto* 输出场景名 = 语素集.添加信息入口词(
        "G0成功服务值饱和入账_输出_" + std::to_string(now),
        枚举_信息入口类型::场景实例入口);
    auto* 输入场景 = 世界树.场景().创建场景_按名称(
        reinterpret_cast<基础信息节点类*>(自我内部世界),
        输入场景名,
        枚举_世界类型::内部世界);
    auto* 输出场景 = 世界树.场景().创建场景_按名称(
        reinterpret_cast<基础信息节点类*>(自我内部世界),
        输出场景名,
        枚举_世界类型::内部世界);
    if (!方法首节点 || !服务值特征 || !输入场景 || !输出场景) {
        结果.摘要 = "成功服务G0饱和入账失败 | 原因=结算方法/服务值特征/场景缺失";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    if (!自我对象.写入自我I64特征当前值(
        私有_自我根特征类型词_线程侧(枚举_自我根特征类型_线程侧::服务),
        计算结果.结算后服务值,
        now)) {
        结果.摘要 = "成功服务G0饱和入账失败 | 原因=写入自我服务值失败";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    结果.D2_服务值结算动作动态 =
        服务模块::创建服务值结算D2动作动态(
            reinterpret_cast<方法节点类*>(方法首节点),
            自我内部世界,
            reinterpret_cast<基础信息节点类*>(自我存在),
            服务值特征,
            计算结果.结算前服务值,
            计算结果.结算后服务值,
            输入.G0治理视图,
            D0,
            D1,
            输入场景,
            输出场景,
            now);
    if (结果.D2_服务值结算动作动态) {
        auto* G0宿主 = reinterpret_cast<基础信息节点类*>(输入.G0治理视图);
        auto* 记录宿主 = reinterpret_cast<基础信息节点类*>(输入.候选记录);
        (void)世界树.写入特征_指针(
            G0宿主,
            服务模块::特征_服务值结算动作动态(),
            结果.D2_服务值结算动作动态,
            now);
        (void)世界树.写入特征_指针(
            记录宿主,
            服务模块::特征_服务值结算动作动态(),
            结果.D2_服务值结算动作动态,
            now);
    } else {
        项目运行警告日志(
            "成功服务G0饱和入账缺D2动作动态"
            " | 任务=" + 任务头->获取主键()
            + " | 需求=" + 来源需求->获取主键()
            + " | G0=" + 输入.G0治理视图->获取主键());
    }

    结果.已结算 = true;
    结果.旧服务值 = 计算结果.结算前服务值;
    结果.新服务值 = 计算结果.结算后服务值;
    结果.实际服务增量 = 计算结果.服务值入账增量;
    结果.lambda使用 = 计算结果.lambda使用;
    g_最近成功服务入账时间_线程侧 = now;
    g_服务值归零连续Tick_线程侧 = 0;
    std::ostringstream 摘要;
    摘要 << "成功服务G0饱和入账"
        << " | 任务=" << 任务头->获取主键()
        << " | 需求=" << 来源需求->获取主键()
        << " | G0=" << 输入.G0治理视图->获取主键()
        << " | 候选记录=" << 输入.候选记录->获取主键()
        << " | 服务=" << 结果.旧服务值 << "->" << 结果.新服务值
        << " | 服务+=" << 结果.实际服务增量
        << " | lambda=" << 结果.lambda使用
        << " | 标准服务单位=" << 标准服务单位
        << " | D2=" << (结果.D2_服务值结算动作动态
            ? 结果.D2_服务值结算动作动态->获取主键()
            : std::string("缺"));
    结果.摘要 = 摘要.str();
    项目运行日志(结果.摘要);
    return 结果;
}

// 功能：从指定来源读取数据或状态。
I64 私有_读取成功服务候选标准服务单位_线程侧(
    存在节点类* G0治理视图,
    存在节点类* 候选记录) noexcept
{
    I64 标准服务单位 = 0;
    if (候选记录
        && 世界树.读取特征_I64(
            reinterpret_cast<基础信息节点类*>(候选记录),
            服务模块::特征_标准服务单位(),
            标准服务单位)
        && 标准服务单位 > 0) {
        return 标准服务单位;
    }
    if (G0治理视图
        && 世界树.读取特征_I64(
            reinterpret_cast<基础信息节点类*>(G0治理视图),
            服务模块::特征_标准服务单位(),
            标准服务单位)
        && 标准服务单位 > 0) {
        return 标准服务单位;
    }
    return 0;
}

动态节点类* 私有_读取成功服务候选动态_线程侧(
    存在节点类* 候选记录,
    const 语素入口节点类* 主特征,
    const 语素入口节点类* 兼容特征 = nullptr) noexcept
{
    auto* 宿主 = 候选记录 ? reinterpret_cast<基础信息节点类*>(候选记录) : nullptr;
    if (!宿主 || !主特征) {
        return nullptr;
    }
    void* 指针 = nullptr;
    if (世界树.读取特征_指针(宿主, 主特征, 指针) && 指针) {
        return reinterpret_cast<动态节点类*>(指针);
    }
    if (兼容特征 && 世界树.读取特征_指针(宿主, 兼容特征, 指针) && 指针) {
        return reinterpret_cast<动态节点类*>(指针);
    }
    return nullptr;
}

// 功能：结算任务、需求、价值或结果贡献。
bool 私有_成功服务候选已结算_线程侧(存在节点类* 候选记录) noexcept
{
    if (!候选记录) {
        return false;
    }
    void* 指针 = nullptr;
    return 世界树.读取特征_指针(
            reinterpret_cast<基础信息节点类*>(候选记录),
            服务模块::特征_服务值结算动作动态(),
            指针)
        && 指针;
}

// 功能：从指定来源读取数据或状态。
存在节点类* 私有_读取任务成功服务候选池_线程侧(任务节点* 任务头) noexcept
{
    auto* 任务存在 = 服务模块::读取任务虚拟存在(任务头);
    auto* 任务宿主 = 任务存在 ? reinterpret_cast<基础信息节点类*>(任务存在) : nullptr;
    if (!任务宿主) {
        return nullptr;
    }
    void* 指针 = nullptr;
    return 世界树.读取特征_指针(
            任务宿主,
            服务模块::特征_成功服务候选池(),
            指针)
        ? reinterpret_cast<存在节点类*>(指针)
        : nullptr;
}

// 功能：服务所在模块的内部辅助流程。
std::vector<任务节点*> 私有_收集当前任务树头任务_线程侧(
    const 自我类& 自我对象,
    std::size_t 上限) noexcept
{
    std::vector<任务节点*> 任务集{};
    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 任务根节点 = 自我存在
        ? reinterpret_cast<任务节点*>(世界树.存在().获取任务根节点(自我存在))
        : nullptr;
    if (!任务根节点 || 上限 == 0) {
        return 任务集;
    }

    std::size_t 保护计数 = 0;
    for (auto* 当前 = reinterpret_cast<任务节点*>(任务根节点->链下);
         当前 && 当前 != 任务根节点 && 保护计数 < 4096 && 任务集.size() < 上限;
         当前 = reinterpret_cast<任务节点*>(当前->链下), ++保护计数) {
        if (任务类::读取任务节点种类(当前) == 枚举_任务节点种类::头结点
            && 私有_节点属于独立树(任务根节点, 当前)) {
            任务集.push_back(当前);
        }
    }
    if (保护计数 >= 4096) {
        项目运行错误日志("成功服务候选池复核扫描任务树超过保护上限");
    }
    return 任务集;
}

// 功能：服务所在模块的内部辅助流程。
void 私有_复核成功服务候选池_线程侧(
    自我类& 自我对象,
    时间戳 now,
    结构_线程服务治理维护结果& 结果) noexcept
{
    auto 任务集 = 私有_收集当前任务树头任务_线程侧(自我对象, 128);
    for (auto* 任务头 : 任务集) {
        if (结果.复核候选数 >= 服务候选池单轮复核上限_线程侧) {
            break;
        }
        ++结果.扫描任务数;
        auto* 候选池 = 私有_读取任务成功服务候选池_线程侧(任务头);
        if (!候选池) {
            continue;
        }
        for (auto* 子节点 : 世界树.获取子节点(reinterpret_cast<基础信息节点类*>(候选池))) {
            if (结果.复核候选数 >= 服务候选池单轮复核上限_线程侧) {
                break;
            }
            auto* 候选记录 = reinterpret_cast<存在节点类*>(子节点);
            if (!候选记录 || 私有_成功服务候选已结算_线程侧(候选记录)) {
                continue;
            }
            auto* G0治理视图 = 服务模块::读取候选记录G0(候选记录);
            if (!G0治理视图) {
                continue;
            }
            const I64 标准服务单位 =
                私有_读取成功服务候选标准服务单位_线程侧(G0治理视图, 候选记录);
            if (标准服务单位 <= 0) {
                continue;
            }
            ++结果.复核候选数;

            结构_线程成功服务G0候选结果 候选结果{};
            候选结果.已尝试 = true;
            候选结果.成功 = true;
            候选结果.G0治理视图 = G0治理视图;
            候选结果.候选记录 = 候选记录;
            候选结果.候选状态 = static_cast<I64>(服务模块::读取G0候选状态(G0治理视图));
            候选结果.服务层级 = static_cast<I64>(服务模块::读取G0服务层级(G0治理视图));

            auto* 来源需求 = reinterpret_cast<需求节点*>(
                服务模块::读取任务来源需求(任务头));
            auto* D0 = 私有_读取成功服务候选动态_线程侧(
                候选记录,
                服务模块::特征_D0服务业务动作动态(),
                服务模块::特征_服务业务动作动态());
            auto* D1 = 私有_读取成功服务候选动态_线程侧(
                候选记录,
                服务模块::特征_D1任务状态动作动态(),
                服务模块::特征_任务状态动作动态());
            const auto 入账结果 = 私有_尝试G0服务值饱和入账_线程侧(
                自我对象,
                任务头,
                来源需求,
                候选结果,
                标准服务单位,
                D0,
                D1,
                now);
            if (入账结果.已结算) {
                ++结果.确认入账数;
            }
        }
    }
}

// 功能：执行任务、方法或动作的主体逻辑。
结构_线程服务治理维护结果 私有_执行服务治理周期维护_线程侧(
    自我类& 自我对象,
    时间戳 now,
    std::uint64_t 当前Tick) noexcept
{
    结构_线程服务治理维护结果 结果{};
    const bool 应复核候选 =
        当前Tick % 服务候选池复核间隔Tick_线程侧 == 0
        && g_最近服务候选池复核Tick_线程侧 != 当前Tick;
    if (应复核候选) {
        g_最近服务候选池复核Tick_线程侧 = 当前Tick;
        结果.已执行候选复核 = true;
        私有_复核成功服务候选池_线程侧(自我对象, now, 结果);
    }

    const bool 应衰减服务值 =
        当前Tick % 服务值衰减间隔Tick_线程侧 == 0
        && g_最近服务值衰减Tick_线程侧 != 当前Tick;
    if (应衰减服务值) {
        g_最近服务值衰减Tick_线程侧 = 当前Tick;
        结果.已执行服务衰减 = true;
        结果.衰减前服务值 = 自我对象.获取服务值();
        (void)自我对象.应用按双值重算服务衰减步长(now);
        if (结果.衰减前服务值 > 0) {
            (void)自我对象.应用定时衰减服务值(0, now);
        }
        结果.衰减后服务值 = 自我对象.获取服务值();
        结果.衰减量 = (std::max<I64>)(0, 结果.衰减前服务值 - 结果.衰减后服务值);
    }

    if (自我对象.获取服务值() == 0) {
        if (结果.确认入账数 == 0) {
            g_服务值归零连续Tick_线程侧 += 服务值衰减间隔Tick_线程侧;
        }
    } else {
        g_服务值归零连续Tick_线程侧 = 0;
    }
    结果.休眠候选 =
        自我对象.获取服务值() == 0
        && g_服务值归零连续Tick_线程侧 >= 服务值归零休眠候选阈值Tick_线程侧
        && 结果.复核候选数 == 0
        && 结果.确认入账数 == 0;

    if (结果.已执行候选复核 || 结果.已执行服务衰减 || 结果.休眠候选) {
        std::ostringstream 摘要;
        摘要 << "服务治理周期维护"
            << " | 候选复核=" << (结果.已执行候选复核 ? "是" : "否")
            << " | 扫描任务=" << 结果.扫描任务数
            << " | 复核候选=" << 结果.复核候选数
            << " | 确认入账=" << 结果.确认入账数
            << " | 服务衰减=" << (结果.已执行服务衰减 ? "是" : "否")
            << " | 服务=" << 结果.衰减前服务值 << "->" << 结果.衰减后服务值
            << " | 衰减量=" << 结果.衰减量
            << " | 服务归零连续Tick=" << g_服务值归零连续Tick_线程侧
            << " | 休眠候选=" << (结果.休眠候选 ? "是" : "否")
            << " | 不直接休眠=1";
        结果.摘要 = 摘要.str();
        项目运行日志(结果.摘要);
    }
    return 结果;
}

结构_线程价值结算结果 私有_调用结算叶子任务价值本能方法_线程侧(
    自我类& 自我对象,
    需求节点* 来源需求,
    任务节点* 任务头,
    I64 安全结算增量,
    I64 服务结算增量,
    I64 任务完成度百万分比,
    状态节点类* 实际结果状态,
    const 结构_线程服务价值结算证据摘要* 服务证据摘要,
    动态节点类* 来源动作动态,
    动态节点类* 满足证据动态,
    时间戳 now) noexcept;

bool 私有_增强任务结算被动因果_线程侧(
    自我类& 自我对象,
    任务节点* 任务头,
    动态节点类* 任务已结算动作动态,
    动态节点类* D2结算动作动态,
    时间戳 now) noexcept;

const 语素入口节点类* 私有_需求动作动态特征词(const char* 名称) noexcept;

// 功能：从指定来源读取数据或状态。
动态节点类* 私有_读取任务状态动作动态_线程侧(const 任务节点* 任务头) noexcept
{
    auto* 任务虚拟存在 = 任务头 ? 任务头->主信息.任务虚拟存在.指针 : nullptr;
    if (!任务虚拟存在) {
        return nullptr;
    }
    void* 动态指针 = nullptr;
    if (!世界树.读取特征_指针(
            reinterpret_cast<基础信息节点类*>(任务虚拟存在),
            私有_需求动作动态特征词("任务状态动作动态"),
            动态指针)) {
        return nullptr;
    }
    return reinterpret_cast<动态节点类*>(动态指针);
}

// 功能：提交事实、动态、任务状态或运行回执。
bool 私有_提交任务已结算状态_线程侧(
    任务节点* 任务头,
    需求节点* 来源需求,
    时间戳 now) noexcept
{
    if (!任务头) {
        return false;
    }
    任务管理线程协议::结构_任务价值结算完成通知 通知{};
    通知.任务信息节点 = reinterpret_cast<任务节点类*>(任务头);
    通知.来源需求 = reinterpret_cast<需求节点类*>(来源需求);
    通知.当前时间 = now;
    通知.事件摘要 = "任务价值反馈完成后通知任务管理结算任务状态";
    const bool 已提交 = 任务管理界面线程::提交任务价值结算完成通知(通知);
    if (!已提交
        || 任务类::读取任务状态(任务头, 枚举_任务状态::未定义)
            != 枚举_任务状态::已结算) {
        项目运行错误日志(
            "任务价值反馈提交已结算状态失败"
            " | 任务=" + 任务头->获取主键()
            + " | 需求=" + (来源需求 ? 来源需求->获取主键() : std::string("空")));
        return false;
    }

    项目运行日志(
        "任务价值反馈提交已结算状态"
        " | 任务=" + 任务头->获取主键()
        + " | 需求=" + (来源需求 ? 来源需求->获取主键() : std::string("空")));
    return true;
}

bool 私有_动作验证摘要允许普通价值结算_线程侧(
    const 动作验证报告::结构_动作验证报告摘要& 摘要) noexcept;
std::string 私有_动作验证摘要日志文本_线程侧(
    const 动作验证报告::结构_动作验证报告摘要& 摘要);

结构_线程价值结算结果 私有_处理任务价值反馈_线程侧(
    自我类& 自我对象,
    任务节点* 任务头,
    需求节点* 来源需求,
    const 结构_线程任务价值反馈段& 反馈,
    时间戳 now,
    const 结构_叶子任务正式结算证据* 正式结算证据 = nullptr,
    const std::vector<结构_任务管理状态变化项>* 服务对象状态变化集 = nullptr,
    const 动作验证报告::结构_动作验证报告摘要* 结算验证报告摘要 = nullptr,
    bool 普通价值结算域已确认 = false) noexcept
{
    结构_线程价值结算结果 结果{};
    if (!任务头) {
        结果.摘要 = "任务价值反馈结算失败 | 原因=任务为空";
        return 结果;
    }
    if (!来源需求) {
        结果.摘要 = "任务价值反馈结算失败 | 原因=来源需求为空";
        return 结果;
    }
    if (任务类::读取任务状态(任务头) == 枚举_任务状态::已结算) {
        项目运行日志(
            "任务价值反馈结算 | 任务已处于已结算状态，继续检查结算被动果"
            " | 任务=" + 任务头->获取主键()
            + " | 需求=" + 来源需求->获取主键());
    }

    const bool 使用外部正式证据 =
        正式结算证据
        && 正式结算证据->叶子任务 == 任务头
        && 正式结算证据->来源需求 == 来源需求;
    const auto 因果投影预判 = 使用外部正式证据
        ? 正式结算证据->投影预判
        : 私有_查询叶子任务结算前因果投影_线程侧(来源需求, 任务头);
    const auto 本轮正式结算证据 = 使用外部正式证据
        ? *正式结算证据
        : 私有_收集叶子任务正式结算证据_线程侧(
            来源需求,
            任务头,
            因果投影预判,
            now);
    if (!本轮正式结算证据.摘要.empty() && !使用外部正式证据) {
        项目运行日志(本轮正式结算证据.摘要);
    }
    if (因果投影预判.缺硬目标证据) {
        结果.摘要 = "任务价值反馈结算失败 | 原因=叶子任务因果投影缺目标宿主或目标特征";
        项目运行错误日志(结果.摘要 + " | " + 因果投影预判.摘要);
        return 结果;
    }
    const bool 任务改变结果可用 = 本轮正式结算证据.actual状态 != nullptr;
    if (!任务改变结果可用) {
        结果.成功 = true;
        结果.已处理 = true;
        结果.摘要 = "任务价值反馈结算跳过 | 原因=缺任务完成后的实际改变结果状态";
        项目运行警告日志(
            结果.摘要 + " | " + 因果投影预判.摘要
            + (本轮正式结算证据.摘要.empty() ? std::string{} : " | " + 本轮正式结算证据.摘要));
        return 结果;
    }
    if (!本轮正式结算证据.D0_业务动作动态) {
        项目运行日志(
            "任务价值反馈结算因果证据不完整但不阻断权重折算"
            " | 任务=" + 任务头->获取主键()
            + " | 需求=" + 来源需求->获取主键()
            + " | D0=" + std::string(本轮正式结算证据.D0_业务动作动态 ? "有" : "缺")
            + " | actual=" + (本轮正式结算证据.actual状态
                ? 本轮正式结算证据.actual状态->获取主键()
                : std::string("缺")));
    }

    const bool 闭环验证通过 =
        结算验证报告摘要
        && 私有_动作验证摘要允许普通价值结算_线程侧(*结算验证报告摘要);
    if (!普通价值结算域已确认 || !闭环验证通过) {
        结果.成功 = true;
        结果.已处理 = true;
        结果.摘要 =
            "任务价值反馈结算阻断"
            " | 原因=" + std::string(!普通价值结算域已确认
                ? "结算域未确认普通价值"
                : "结算闭环验证报告未通过")
            + " | 任务=" + 任务头->获取主键()
            + " | 需求=" + 来源需求->获取主键()
            + " | 普通价值结算域=" + std::string(普通价值结算域已确认 ? "是" : "否")
            + " | " + (结算验证报告摘要
                ? 私有_动作验证摘要日志文本_线程侧(*结算验证报告摘要)
                : std::string("动作验证报告摘要=无"))
            + " | 不调用结算叶子任务价值=1"
            + " | 不写核心安全值=1"
            + " | 不写服务值=1";
        项目运行日志(结果.摘要);
        return 结果;
    }

    const auto 正式结算结果目标键 = 私有_正式结算结果目标键_线程侧(
        任务头,
        来源需求,
        本轮正式结算证据);
    if (私有_正式结算结果目标已处理_线程侧(正式结算结果目标键)) {
        结果.成功 = true;
        结果.已处理 = true;
        结果.已去重 = true;
        结果.摘要 = "任务价值反馈结算 | 任务结果目标已结算，跳过去重";
        项目运行日志(结果.摘要 + " | 去重键=" + 正式结算结果目标键);
        return 结果;
    }

    const auto 任务主键 = 任务头->获取主键();
    if (私有_是增量反馈_线程侧(反馈)
        && !私有_登记增量反馈事件_线程侧(任务主键, 反馈.反馈事件主键, 结果)) {
        return 结果;
    }

    const I64 原始任务安全权重上限 = 任务类::读取任务承接安全权重上限(任务头);
    const bool 安全上限是未设置哨兵 =
        原始任务安全权重上限 == (std::numeric_limits<I64>::max)();
    const I64 任务安全权重上限 = 安全上限是未设置哨兵
        ? 0
        : (std::max<I64>)(0, 原始任务安全权重上限);
    const I64 原始任务服务权重上限 = 任务类::读取任务承接服务权重上限(任务头);
    const bool 服务上限是未设置哨兵 =
        原始任务服务权重上限 == (std::numeric_limits<I64>::max)();
    const I64 任务服务权重上限 = 服务上限是未设置哨兵
        ? 0
        : (std::max<I64>)(0, 原始任务服务权重上限);
    const I64 已折算安全值 =
        (std::max<I64>)(0, 任务类::读取任务已折算安全值(任务头));
    const I64 已折算服务值 =
        (std::max<I64>)(0, 任务类::读取任务已折算服务值(任务头));

    const I64 计划安全增量 = 私有_计算反馈增量_线程侧(
        任务安全权重上限,
        已折算安全值,
        反馈.本次安全满足量,
        反馈.安全累计比例_百万分比);
    const I64 计划服务增量 = 私有_计算反馈增量_线程侧(
        任务服务权重上限,
        已折算服务值,
        反馈.本次服务满足量,
        反馈.服务累计比例_百万分比);
    const I64 安全完成度百万分比 = 反馈.安全累计比例_百万分比 >= 0
        ? std::clamp<I64>(反馈.安全累计比例_百万分比, 0, 1'000'000)
        : 0;
    const I64 服务完成度百万分比 = 反馈.服务累计比例_百万分比 >= 0
        ? std::clamp<I64>(反馈.服务累计比例_百万分比, 0, 1'000'000)
        : 0;
    const I64 任务完成度百万分比 =
        (std::max<I64>)(安全完成度百万分比, 服务完成度百万分比);
    结构_线程服务价值结算证据摘要 服务证据摘要{};
    const 结构_线程服务价值结算证据摘要* 服务证据摘要指针 = nullptr;
    if (计划服务增量 > 0) {
        服务证据摘要 = 私有_评估服务价值结算证据_线程侧(
            服务对象状态变化集,
            本轮正式结算证据);
        服务证据摘要指针 = &服务证据摘要;
        项目运行日志(
            "任务价值反馈服务结算证据已提交结算方法"
            " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键()
            + " | 计划服务增量=" + std::to_string(计划服务增量)
            + " | " + 服务证据摘要.摘要);
    }

    if (服务上限是未设置哨兵
        && (反馈.本次服务满足量 > 0 || 反馈.服务累计比例_百万分比 >= 0)) {
        std::ostringstream 日志;
        日志 << "任务价值反馈服务结算已忽略"
            << " | 原因=服务上限为I64_MAX哨兵，不能作为真实权重"
            << " | 任务=" << 任务主键
            << " | 需求=" << 来源需求->获取主键()
            << " | 原始服务上限=" << 原始任务服务权重上限
            << " | 本次服务满足量=" << 反馈.本次服务满足量
            << " | 服务累计比例=" << 反馈.服务累计比例_百万分比;
        项目运行日志(日志.str());
    }
    if (安全上限是未设置哨兵) {
        std::ostringstream 日志;
        日志 << "任务价值反馈安全结算已忽略"
            << " | 原因=安全上限为I64_MAX哨兵，不能作为真实权重"
            << " | 任务=" << 任务主键
            << " | 需求=" << 来源需求->获取主键()
            << " | 本次安全满足量=" << 反馈.本次安全满足量
            << " | 安全累计比例=" << 反馈.安全累计比例_百万分比;
        项目运行警告日志(日志.str());
    }

    auto* D2来源动作动态 = 本轮正式结算证据.任务完成动作动态
        ? 本轮正式结算证据.任务完成动作动态
        : 本轮正式结算证据.D0_业务动作动态;
    if (本轮正式结算证据.任务完成动作动态) {
        项目运行日志(
            "任务价值反馈结算因果来源"
            " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键()
            + " | D2来源=任务完成动作动态"
            + " | 动态=" + 本轮正式结算证据.任务完成动作动态->获取主键()
            + " | 说明=结算叶子任务价值建立任务完成到核心值变化的账务因果");
    } else {
        项目运行警告日志(
            "任务价值反馈结算缺任务完成动作动态"
            " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键()
            + " | 说明=本轮仍可按实际结果和权重折算，但D2缺少任务完成直接来源边");
    }

    const bool 任务已结算状态已提交 =
        私有_提交任务已结算状态_线程侧(任务头, 来源需求, now);
    if (!任务已结算状态已提交) {
        结果.摘要 = "任务价值反馈结算失败 | 原因=无法形成任务已结算被动因";
        项目运行错误日志(
            结果.摘要
            + " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键());
        return 结果;
    }
    auto* 任务已结算动作动态 = 私有_读取任务状态动作动态_线程侧(任务头);
    if (!任务已结算动作动态) {
        结果.摘要 = "任务价值反馈结算失败 | 原因=任务已结算状态动作动态缺失";
        项目运行错误日志(
            结果.摘要
            + " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键());
        return 结果;
    }
    D2来源动作动态 = 任务已结算动作动态;
    项目运行日志(
        "任务价值反馈结算被动因已形成"
        " | 任务=" + 任务主键
        + " | 需求=" + 来源需求->获取主键()
        + " | 被动因=任务虚拟存在.任务状态=已结算"
        + " | 状态动态=" + 任务已结算动作动态->获取主键());

    if (任务完成度百万分比 <= 0 || (计划安全增量 <= 0 && 计划服务增量 <= 0)) {
        结果.成功 = true;
        结果.已处理 = true;
        结果.摘要 =
            "任务价值反馈结算阻断"
            " | 原因=" + std::string(任务完成度百万分比 <= 0
                ? "完成度为0"
                : "缺合法核心价值增量")
            + " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键()
            + " | 完成度百万分比=" + std::to_string(任务完成度百万分比)
            + " | 计划安全增量=" + std::to_string(计划安全增量)
            + " | 计划服务增量=" + std::to_string(计划服务增量)
            + " | 不调用结算叶子任务价值=1"
            + " | 不写核心安全值=1"
            + " | 不写服务值=1";
        项目运行日志(结果.摘要);
        return 结果;
    }

    结构_线程成功服务G0候选结果 G0候选结果{};
    if (计划服务增量 > 0) {
        G0候选结果 = 私有_生成成功服务G0候选_线程侧(
            任务头,
            来源需求,
            本轮正式结算证据,
            服务证据摘要指针,
            服务完成度百万分比,
            计划服务增量,
            任务已结算动作动态,
            正式结算结果目标键,
            now);
        if (G0候选结果.已尝试 && !G0候选结果.成功) {
            项目运行警告日志(
                G0候选结果.摘要
                + " | 不阻断旧任务价值结算=1");
        }
        项目运行日志(
            "任务价值反馈旧服务值直接入账已关闭"
            " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键()
            + " | 原计划服务增量=" + std::to_string(计划服务增量)
            + " | 服务值权威入口=G0已确认成功服务饱和入账");
    }

    auto 应用结果 = 私有_调用结算叶子任务价值本能方法_线程侧(
        自我对象,
        来源需求,
        任务头,
        计划安全增量,
        0,
        任务完成度百万分比,
        本轮正式结算证据.actual状态,
        服务证据摘要指针,
        D2来源动作动态,
        本轮正式结算证据.D0_业务动作动态,
        now);
    if (!应用结果.成功) {
        return 应用结果;
    }

    if (计划服务增量 > 0 && G0候选结果.成功) {
        const auto G0服务入账结果 = 私有_尝试G0服务值饱和入账_线程侧(
            自我对象,
            任务头,
            来源需求,
            G0候选结果,
            计划服务增量,
            本轮正式结算证据.D0_业务动作动态,
            任务已结算动作动态,
            now);
        if (G0服务入账结果.已结算) {
            应用结果.旧服务值 = G0服务入账结果.旧服务值;
            应用结果.新服务值 = G0服务入账结果.新服务值;
            应用结果.实际服务增量 = G0服务入账结果.实际服务增量;
            if (!应用结果.D2_结算动作动态) {
                应用结果.D2_结算动作动态 =
                    G0服务入账结果.D2_服务值结算动作动态;
            }
        }
    }
    const bool 被动因果已增强 = 私有_增强任务结算被动因果_线程侧(
        自我对象,
        任务头,
        任务已结算动作动态,
        应用结果.D2_结算动作动态,
        now);
    if (!被动因果已增强) {
        项目运行警告日志(
            "任务价值反馈结算被动因果增强失败"
            " | 任务=" + 任务主键
            + " | 需求=" + 来源需求->获取主键()
            + " | 被动因=任务虚拟存在.任务状态=已结算");
    }

    const I64 实际安全增量 = 应用结果.实际安全增量;
    const I64 实际服务增量 = 应用结果.实际服务增量;
    if (实际安全增量 > 0 || 实际服务增量 > 0) {
        std::ostringstream 回写日志;
        回写日志 << "任务价值反馈应用到自我核心状态"
            << " | 任务=" << 任务主键
            << " | 需求=" << 来源需求->获取主键()
            << " | 安全=" << 应用结果.旧安全值 << "->" << 应用结果.新安全值
            << " | 服务=" << 应用结果.旧服务值 << "->" << 应用结果.新服务值
            << " | 安全净变化=" << 实际安全增量
            << " | 服务净变化=" << 实际服务增量;
        项目运行日志(回写日志.str());
    }
    私有_登记正式结算结果目标_线程侧(正式结算结果目标键);
    if (实际安全增量 > 0 || 实际服务增量 > 0) {
        任务管理线程协议::结构_任务价值结算回执 回执{};
        回执.任务信息节点 = reinterpret_cast<任务节点类*>(任务头);
        回执.来源需求 = reinterpret_cast<需求节点类*>(来源需求);
        回执.写入已折算安全值 = 实际安全增量 > 0;
        回执.写入已折算服务值 = 实际服务增量 > 0;
        回执.已折算安全值 =
            (std::min<I64>)(任务安全权重上限, 已折算安全值 + 实际安全增量);
        回执.已折算服务值 =
            (std::min<I64>)(任务服务权重上限, 已折算服务值 + 实际服务增量);
        回执.当前时间 = now;
        回执.反馈事件主键 = 反馈.反馈事件主键;
        (void)任务管理界面线程::提交任务价值结算回执(回执);
    }

    结果.成功 = true;
    结果.已处理 = true;
    结果.实际安全增量 = 实际安全增量;
    结果.实际服务增量 = 实际服务增量;
    std::ostringstream 摘要;
    摘要 << "任务价值反馈结算"
        << " | 任务=" << 任务主键
        << " | 需求=" << 来源需求->获取主键()
        << " | 安全+=" << 实际安全增量
        << " | 服务+=" << 实际服务增量
        << " | 安全账本="
        << (std::min<I64>)(任务安全权重上限, 已折算安全值 + 实际安全增量)
        << "/" << 任务安全权重上限
        << " | 服务账本="
        << (std::min<I64>)(任务服务权重上限, 已折算服务值 + 实际服务增量)
        << "/" << 任务服务权重上限
        << " | 任务状态已结算=" << (任务已结算状态已提交 ? "是" : "否");
    结果.摘要 = 摘要.str();
    项目运行日志(结果.摘要);
    return 结果;
}

