template<class T节点>
bool 私有_引用指向节点_线程侧(const 可解析引用<T节点>& 引用, const T节点* 节点) noexcept
{
    if (!节点) {
        return false;
    }
    if (引用.指针 == 节点) {
        return true;
    }
    return !引用.主键.empty() && 引用.主键 == 节点->获取主键();
}

template<class T节点>
bool 私有_引用集合包含节点_线程侧(
    const std::vector<可解析引用<T节点>>& 引用集,
    const T节点* 节点) noexcept
{
    for (const auto& 引用 : 引用集) {
        if (私有_引用指向节点_线程侧(引用, 节点)) {
            return true;
        }
    }
    return false;
}

