template<class T节点, class T谓词>
T节点* 私有_查找直接子节点_按谓词(T节点* 父节点, T谓词&& 谓词) noexcept
{
    if (!父节点 || !父节点->子) {
        return nullptr;
    }

    auto* 首节点 = reinterpret_cast<T节点*>(父节点->子);
    auto* 当前 = 首节点;
    do {
        if (当前 && 谓词(当前)) {
            return 当前;
        }
        当前 = reinterpret_cast<T节点*>(当前->下);
    } while (当前 && 当前 != 首节点);
    return nullptr;
}

template<class T节点>
bool 私有_节点属于独立树(const T节点* 根节点, const T节点* 候选节点) noexcept
{
    if (!根节点 || !候选节点) {
        return false;
    }

    if (根节点 == 候选节点) {
        return true;
    }

    for (auto* 当前节点 = reinterpret_cast<const T节点*>(根节点->链下);
         当前节点 && 当前节点 != 根节点;
         当前节点 = reinterpret_cast<const T节点*>(当前节点->链下)) {
        if (当前节点 == 候选节点) {
            return true;
        }
    }
    return false;
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_需求节点属于当前需求树_线程侧(const 需求节点* 候选节点) noexcept
{
    auto* 自我存在 = 世界树.自我指针;
    auto* 需求根节点 = 自我存在
        ? reinterpret_cast<需求节点*>(世界树.存在().获取需求根节点(自我存在))
        : nullptr;
    if (!需求根节点 || !候选节点) {
        return false;
    }
    if (私有_节点属于独立树(需求根节点, 候选节点)) {
        return true;
    }
    for (auto* 当前 = 候选节点; 当前; 当前 = reinterpret_cast<const 需求节点*>(当前->父)) {
        if (当前 == 需求根节点) {
            return true;
        }
    }
    return false;
}

template<class T节点>
T节点* 私有_按主键扫描独立树(T节点* 根节点, const std::string& 主键) noexcept
{
    if (!根节点 || 主键.empty()) {
        return nullptr;
    }

    if (根节点->获取主键() == 主键) {
        return 根节点;
    }

    for (auto* 当前节点 = reinterpret_cast<T节点*>(根节点->链下);
         当前节点 && 当前节点 != 根节点;
         当前节点 = reinterpret_cast<T节点*>(当前节点->链下)) {
        if (当前节点->获取主键() == 主键) {
            return 当前节点;
        }
    }
    return nullptr;
}

// 功能：解析输入文本、消息、场景或运行包。
const 语素入口节点类* 私有_解析入口节点引用(
    const std::uintptr_t 节点指针,
    const std::string& 主键) noexcept
{
    auto* 语素根 = reinterpret_cast<语素入口节点类*>(语素集.根指针);
    if (!主键.empty()) {
        return 私有_按主键扫描独立树(语素根, 主键);
    }

    auto* 候选节点 = reinterpret_cast<语素入口节点类*>(节点指针);
    return 私有_节点属于独立树(语素根, 候选节点) ? 候选节点 : nullptr;
}

// 功能：解析输入文本、消息、场景或运行包。
基础信息节点类* 私有_解析基础信息节点引用_线程侧(
    const std::uintptr_t 节点指针,
    const std::string& 主键) noexcept
{
    if (!主键.empty()) {
        return 世界树.基础信息().查找主键(主键);
    }

    auto* 候选节点 = reinterpret_cast<基础信息节点类*>(节点指针);
    return (候选节点 && 候选节点->主信息) ? 候选节点 : nullptr;
}

