// 功能：解析输入文本、消息、场景或运行包。
状态节点类* 私有_从状态引用解析状态节点(
    const 可解析引用<状态节点类>& 引用) noexcept
{
    if (!引用.主键.empty()) {
        return 私有_按主键解析状态节点(引用.主键);
    }

    auto* 候选节点 = reinterpret_cast<状态节点类*>(引用.指针);
    return 世界树.状态().取状态主信息(候选节点) ? 候选节点 : nullptr;
}

// 功能：服务所在模块的内部辅助流程。
const 特征节点主信息类* 私有_状态特征主信息_线程侧(const 状态节点类* 状态节点) noexcept
{
    const auto* 状态主信息 =
        状态节点 ? 世界树.状态().取状态主信息(const_cast<状态节点类*>(状态节点)) : nullptr;
    if (!状态主信息) {
        return nullptr;
    }

    auto* 特征节点 = 状态主信息->状态特征.指针;
    if (!特征节点 && !状态主信息->状态特征.主键.empty()) {
        特征节点 = dynamic_cast<特征节点类*>(
            世界树.基础信息().查找主键(状态主信息->状态特征.主键));
    }
    return 特征节点 ? 世界树.特征().取特征主信息(特征节点) : nullptr;
}

// 功能：服务所在模块的内部辅助流程。
特征节点类* 私有_状态特征节点_线程侧(const 状态节点类* 状态节点) noexcept
{
    const auto* 状态主信息 =
        状态节点 ? 世界树.状态().取状态主信息(const_cast<状态节点类*>(状态节点)) : nullptr;
    if (!状态主信息) {
        return nullptr;
    }

    auto* 特征节点 = 状态主信息->状态特征.指针;
    if (!特征节点 && !状态主信息->状态特征.主键.empty()) {
        特征节点 = dynamic_cast<特征节点类*>(
            世界树.基础信息().查找主键(状态主信息->状态特征.主键));
    }
    return 特征节点 && 世界树.特征().取特征主信息(特征节点) ? 特征节点 : nullptr;
}

// 功能：服务所在模块的内部辅助流程。
const 语素入口节点类* 私有_状态节点特征类型_线程侧(const 状态节点类* 状态节点) noexcept
{
    const auto* 特征主信息 = 私有_状态特征主信息_线程侧(状态节点);
    return 特征主信息 ? 特征主信息->类型 : nullptr;
}

// 功能：服务所在模块的内部辅助流程。
std::string 私有_状态主体主键_线程侧(const 状态节点类* 状态节点) noexcept
{
    const auto* 状态主信息 =
        状态节点 ? 世界树.状态().取状态主信息(const_cast<状态节点类*>(状态节点)) : nullptr;
    if (!状态主信息) {
        return {};
    }
    if (!状态主信息->状态主体.主键.empty()) {
        return 状态主信息->状态主体.主键;
    }
    return 状态主信息->状态主体.指针
        ? 状态主信息->状态主体.指针->获取主键()
        : std::string{};
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_状态语义相同_线程侧(
    const 状态节点类* 左,
    const 状态节点类* 右) noexcept
{
    if (左 == 右 && 左) {
        return true;
    }

    const auto* 左主信息 =
        左 ? 世界树.状态().取状态主信息(const_cast<状态节点类*>(左)) : nullptr;
    const auto* 右主信息 =
        右 ? 世界树.状态().取状态主信息(const_cast<状态节点类*>(右)) : nullptr;
    if (!左主信息 || !右主信息) {
        return false;
    }

    const auto* 左特征类型 = 私有_状态节点特征类型_线程侧(左);
    const auto* 右特征类型 = 私有_状态节点特征类型_线程侧(右);
    if (左特征类型 && 右特征类型 && 左特征类型 != 右特征类型) {
        const auto 左特征主键 = 左特征类型->获取主键();
        const auto 右特征主键 = 右特征类型->获取主键();
        if (左特征主键.empty() || 左特征主键 != 右特征主键) {
            return false;
        }
    }

    const auto 左主体主键 = 私有_状态主体主键_线程侧(左);
    const auto 右主体主键 = 私有_状态主体主键_线程侧(右);
    if (!左主体主键.empty() && !右主体主键.empty() && 左主体主键 != 右主体主键) {
        return false;
    }

    return 左主信息->状态值 == 右主信息->状态值;
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_状态需求条件兼容_线程侧(
    const 可解析引用<状态节点类>& 已有引用,
    const 状态节点类* 派生状态) noexcept
{
    if (!派生状态) {
        return true;
    }

    auto* 已有状态 = 私有_从状态引用解析状态节点(已有引用);
    if (!已有状态) {
        return false;
    }
    return 私有_状态语义相同_线程侧(已有状态, 派生状态);
}

// 功能：服务所在模块的内部辅助流程。
存在节点类* 私有_状态主体存在_线程侧(const 状态节点类* 状态节点) noexcept
{
    const auto* 状态主信息 =
        状态节点 ? 世界树.状态().取状态主信息(const_cast<状态节点类*>(状态节点)) : nullptr;
    auto* 主体 = 状态主信息
        ? reinterpret_cast<基础信息节点类*>(状态主信息->状态主体.指针)
        : nullptr;
    return 主体 && 主体->主信息 && 主体->主信息->主信息类型 == 枚举_主信息类型::存在
        ? reinterpret_cast<存在节点类*>(主体)
        : nullptr;
}

// 功能：服务所在模块的内部辅助流程。
基础信息节点类* 私有_状态主体基础节点_线程侧(const 状态节点类* 状态节点) noexcept
{
    const auto* 状态主信息 =
        状态节点 ? 世界树.状态().取状态主信息(const_cast<状态节点类*>(状态节点)) : nullptr;
    if (!状态主信息) {
        return nullptr;
    }
    if (状态主信息->状态主体.指针) {
        return reinterpret_cast<基础信息节点类*>(状态主信息->状态主体.指针);
    }
    return 状态主信息->状态主体.主键.empty()
        ? nullptr
        : 世界树.基础信息().查找主键(状态主信息->状态主体.主键);
}

// 功能：服务所在模块的内部辅助流程。
基础信息节点类* 私有_需求目标宿主基础节点_线程侧(const 需求节点* 来源需求) noexcept
{
    if (!来源需求) {
        return nullptr;
    }
    if (auto* 目标状态 = 私有_从状态引用解析状态节点(来源需求->主信息.需求状态)) {
        if (auto* 主体 = 私有_状态主体基础节点_线程侧(目标状态)) {
            return 主体;
        }
    }
    if (auto* 当前状态 = 私有_从状态引用解析状态节点(来源需求->主信息.被需求当前状态)) {
        if (auto* 主体 = 私有_状态主体基础节点_线程侧(当前状态)) {
            return 主体;
        }
    }
    if (来源需求->主信息.被需求存在.指针) {
        return reinterpret_cast<基础信息节点类*>(来源需求->主信息.被需求存在.指针);
    }
    if (!来源需求->主信息.被需求存在.主键.empty()) {
        if (auto* 节点 = 世界树.基础信息().查找主键(来源需求->主信息.被需求存在.主键)) {
            return 节点;
        }
    }
    return nullptr;
}

// 功能：服务所在模块的内部辅助流程。
特征节点类* 私有_需求目标特征节点_线程侧(const 需求节点* 来源需求) noexcept
{
    if (!来源需求) {
        return nullptr;
    }
    if (auto* 目标状态 = 私有_从状态引用解析状态节点(来源需求->主信息.需求状态)) {
        if (auto* 特征 = 私有_状态特征节点_线程侧(目标状态)) {
            return 特征;
        }
    }
    if (auto* 当前状态 = 私有_从状态引用解析状态节点(来源需求->主信息.被需求当前状态)) {
        return 私有_状态特征节点_线程侧(当前状态);
    }
    return nullptr;
}

