// 功能：计算权重、状态、差值或派生结果。
I64 私有_计算安全因果风险树输入版本_线程侧(因果节点类* 来源因果) noexcept
{
    (void)来源因果;
    return 安全因果风险树层级_风险安全_线程侧 * 1000000000LL
        + 安全因果风险树同层因素集合版本_风险安全_线程侧 * 1000000LL
        + 安全因果风险树来源因果结构版本_风险安全_线程侧 * 1009LL;
}

// 功能：服务所在模块的内部辅助流程。
