// 功能：确保目标结构、状态或前置条件存在并可用。
二次特征节点类* 私有_确保安全风险树I64比较_线程侧(
    自我类& 自我对象,
    基础信息节点类* 主体,
    const char* 特征名,
    I64 当前值,
    I64 目标值,
    时间戳 now) noexcept
{
    if (!主体 || !特征名 || !*特征名) {
        return nullptr;
    }
    auto* 所属场景 = 自我对象.获取自我内部世界();
    if (!所属场景) {
        所属场景 = 自我对象.获取自我现实场景();
    }
    const auto* 特征 = 私有_需求动作动态特征词(特征名);
    auto* 当前状态 = 私有_创建安全风险树I64状态节点_线程侧(
        自我对象,
        主体,
        特征,
        当前值,
        now);
    auto* 目标状态 = 私有_创建安全风险树I64状态节点_线程侧(
        自我对象,
        主体,
        特征,
        目标值,
        now);
    return 所属场景 && 当前状态 && 目标状态
        ? 私有_创建安全风险树状态比较_线程侧(所属场景, 当前状态, 目标状态)
        : nullptr;
}

