struct 结构_被动触发初始因果规则_线程侧 {
    基础信息节点类* 父节点 = nullptr;
    二次特征节点类* 条件比较 = nullptr;
    二次特征节点类* 果比较 = nullptr;
    std::string 规则名{};
    std::string 被动因描述{};
    std::string 承接条件描述{};
    std::string 自动果描述{};
    std::string 幂等键{};
    std::uint32_t 适用层级 = 0;
};

// 功能：按被动触发证据动态生成或命中因果信息。
bool 私有_按动态生成被动触发因果信息_线程侧(
    const 结构_被动触发初始因果规则_线程侧& 规则,
    std::initializer_list<动态节点类*> 证据动态集) noexcept
{
    std::size_t 证据动态数量 = 0;
    std::size_t 因果生成数量 = 0;
    for (auto* 动态 : 证据动态集) {
        if (!动态) {
            continue;
        }
        ++证据动态数量;
        if (世界树.因果().生成因果信息(动态)) {
            ++因果生成数量;
        }
    }

    项目运行日志(
        "自我线程/被动触发因果信息生成"
        " | 规则=" + (规则.规则名.empty() ? std::string("未命名") : 规则.规则名)
        + " | 被动因=" + (规则.被动因描述.empty() ? std::string("未定义") : 规则.被动因描述)
        + " | 承接=" + (规则.承接条件描述.empty() ? std::string("未定义") : 规则.承接条件描述)
        + " | 自动果=" + (规则.自动果描述.empty() ? std::string("未定义") : 规则.自动果描述)
        + " | 证据动态数量=" + std::to_string(static_cast<I64>(证据动态数量))
        + " | 因果生成数量=" + std::to_string(static_cast<I64>(因果生成数量))
        + " | 动态职责=按动态生成或命中因果信息"
        + " | 幂等键=" + (规则.幂等键.empty() ? std::string("未定义") : 规则.幂等键));
    return 因果生成数量 > 0;
}

// 功能：结算任务、需求、价值或结果贡献。
bool 私有_增强任务结算被动因果_线程侧(
    自我类& 自我对象,
    任务节点* 任务头,
    动态节点类* 任务已结算动作动态,
    动态节点类* D2结算动作动态,
    时间戳 now) noexcept
{
    (void)自我对象;
    (void)now;

    结构_被动触发初始因果规则_线程侧 规则{};
    规则.父节点 = 世界树.基础信息().世界根();
    规则.条件比较 = nullptr;
    规则.果比较 = nullptr;
    规则.规则名 = "初始因果.结算被动果.任务已结算触发叶子任务价值结算";
    规则.被动因描述 = "任务虚拟存在.任务状态=已结算";
    规则.承接条件描述 = "任务完成后结算资格成立";
    规则.自动果描述 = "结算叶子任务价值被动果出现/安全服务值账务变化";
    规则.幂等键 = "任务结算|任务=" + (任务头 ? 任务头->获取主键() : std::string("空"));
    const bool 已生成 = 私有_按动态生成被动触发因果信息_线程侧(
        规则,
        { 任务已结算动作动态, D2结算动作动态 });

    项目运行日志(
        "自我线程/结算被动因果增强"
        " | 任务=" + (任务头 ? 任务头->获取主键() : std::string("空"))
        + " | 被动因=任务虚拟存在.任务状态=已结算"
        + " | 任务状态动态=" + (任务已结算动作动态 ? 任务已结算动作动态->获取主键() : std::string("缺"))
        + " | D2=" + (D2结算动作动态 ? D2结算动作动态->获取主键() : std::string("缺"))
        + " | 动态职责=按动态生成被动触发因果信息"
        + " | 因果生成=" + std::to_string(已生成 ? 1 : 0));
    return 已生成;
}

// 功能：推进任务筹办，形成候选、缺口或就绪回执。
bool 私有_增强父任务重筹办被动因果_线程侧(
    自我类& 自我对象,
    需求节点* 子需求,
    任务节点* 子任务,
    需求节点* 父需求,
    任务节点* 父任务,
    枚举_任务状态 父任务旧状态,
    枚举_任务状态 父任务新状态,
    动态节点类* 子任务状态动作动态,
    动态节点类* 父任务状态动作动态,
    时间戳 now) noexcept
{
    auto* 子任务虚拟存在 = 私有_任务虚拟存在基础节点_线程侧(子任务);
    auto* 父任务虚拟存在 = 私有_任务虚拟存在基础节点_线程侧(父任务);
    if (!子需求 || !子任务 || !父需求 || !父任务
        || !子任务虚拟存在 || !父任务虚拟存在
        || 父任务旧状态 == 枚举_任务状态::未定义
        || 父任务新状态 == 枚举_任务状态::未定义
        || !父任务状态动作动态) {
        项目运行警告日志(
            "自我线程/父任务重筹办被动因果缺口"
            " | 原因=因果宿主或父任务状态动态缺失"
            " | 子需求=" + (子需求 ? 子需求->获取主键() : std::string("空"))
            + " | 子任务=" + (子任务 ? 子任务->获取主键() : std::string("空"))
            + " | 父需求=" + (父需求 ? 父需求->获取主键() : std::string("空"))
            + " | 父任务=" + (父任务 ? 父任务->获取主键() : std::string("空"))
            + " | 子任务虚拟存在=" + (子任务虚拟存在 ? 子任务虚拟存在->获取主键() : std::string("缺"))
            + " | 父任务虚拟存在=" + (父任务虚拟存在 ? 父任务虚拟存在->获取主键() : std::string("缺"))
            + " | 父任务状态动态=" + (父任务状态动作动态 ? 父任务状态动作动态->获取主键() : std::string("缺")));
        return false;
    }

    auto* 条件比较 = 私有_确保线程I64状态比较_线程侧(
        自我对象,
        子任务虚拟存在,
        "对应需求满足状态",
        0,
        1,
        now);
    auto* 果比较 = 私有_确保线程I64状态比较_线程侧(
        自我对象,
        父任务虚拟存在,
        "任务状态",
        static_cast<I64>(父任务旧状态),
        static_cast<I64>(父任务新状态),
        now);
    if (!条件比较 || !果比较) {
        项目运行警告日志(
            "自我线程/父任务重筹办被动因果缺口"
            " | 原因=条件比较或果比较创建失败"
            " | 子需求=" + 子需求->获取主键()
            + " | 父任务=" + 父任务->获取主键()
            + " | 条件比较=" + (条件比较 ? 条件比较->获取主键() : std::string("缺"))
            + " | 果比较=" + (果比较 ? 果比较->获取主键() : std::string("缺")));
        return false;
    }

    auto* 父节点 = reinterpret_cast<基础信息节点类*>(自我对象.获取自我内部世界());
    if (!父节点) {
        父节点 = reinterpret_cast<基础信息节点类*>(自我对象.获取自我现实场景());
    }
    if (!父节点) {
        父节点 = 世界树.基础信息().世界根();
    }

    结构_被动触发初始因果规则_线程侧 规则{};
    规则.父节点 = 父节点;
    规则.条件比较 = 条件比较;
    规则.果比较 = 果比较;
    规则.规则名 = "初始因果.父任务重筹办.子目标满足解除等待";
    规则.被动因描述 =
        "子任务虚拟存在.对应需求满足状态=已满足";
    规则.承接条件描述 =
        "父任务虚拟存在.等待来源子需求=子任务对应需求 且 父任务状态属于等待类";
    规则.自动果描述 =
        "父任务虚拟存在.任务状态进入待重筹办/任务阶段回到筹办/等待缺口唤醒=1";
    规则.幂等键 =
        "父任务重筹办|父任务=" + 父任务->获取主键()
        + "|子需求=" + 子需求->获取主键();
    规则.适用层级 = 2;

    const bool 已增强 = 私有_按动态生成被动触发因果信息_线程侧(
        规则,
        { 子任务状态动作动态, 父任务状态动作动态 });
    if (已增强) {
        项目运行日志(
            "自我线程/父任务重筹办被动因果增强"
            " | 子需求=" + 子需求->获取主键()
            + " | 子任务=" + 子任务->获取主键()
            + " | 父需求=" + 父需求->获取主键()
            + " | 父任务=" + 父任务->获取主键()
            + " | 父任务旧状态=" + std::to_string(static_cast<int>(父任务旧状态))
            + " | 父任务新状态=" + std::to_string(static_cast<int>(父任务新状态))
            + " | 子任务状态动态=" + (子任务状态动作动态 ? 子任务状态动作动态->获取主键() : std::string("缺"))
            + " | 父任务状态动态=" + 父任务状态动作动态->获取主键()
            + " | 被动因=子任务虚拟存在.对应需求满足状态=已满足"
            + " | 承接=父任务等待来源子需求匹配且父任务处于等待类状态"
            + " | 自动果=父任务进入待重筹办并回到筹办阶段");
    }
    return 已增强;
}

// 功能：创建并返回或登记对应对象。
状态节点类* 私有_创建安全风险树I64状态节点_线程侧(
    自我类& 自我对象,
    基础信息节点类* 主体,
    const 语素入口节点类* 特征类型,
    const I64 值,
    const 时间戳 now) noexcept
{
    if (!主体 || !特征类型) {
        return nullptr;
    }
    auto* 场景 = 自我对象.获取自我内部世界();
    if (!场景) {
        场景 = 自我对象.获取自我现实场景();
    }
    auto* 特征 = 世界树.确保特征(主体, 特征类型);
    if (!场景 || !特征) {
        return nullptr;
    }
    return 世界树.状态().创建状态(
        场景,
        主体,
        特征,
        特征值{ 值 },
        now,
        now);
}

// 功能：创建并返回或登记对应对象。
二次特征节点类* 私有_创建安全风险树状态比较_线程侧(
    场景节点类* 所属场景,
    状态节点类* 初始状态,
    状态节点类* 结果状态) noexcept
{
    if (!所属场景 || !初始状态 || !结果状态) {
        return nullptr;
    }

    const auto* 初始状态主信息 = 世界树.状态().取状态主信息(初始状态);
    const auto* 结果状态主信息 = 世界树.状态().取状态主信息(结果状态);
    if (!初始状态主信息 || !结果状态主信息) {
        return nullptr;
    }

    const auto* 初始特征主信息 = 初始状态主信息->状态特征.指针
        ? 世界树.特征().取特征主信息(初始状态主信息->状态特征.指针)
        : nullptr;
    const auto* 结果特征主信息 = 结果状态主信息->状态特征.指针
        ? 世界树.特征().取特征主信息(结果状态主信息->状态特征.指针)
        : nullptr;
    const auto* 初始特征类型 = 初始特征主信息 ? 初始特征主信息->类型 : nullptr;
    const auto* 结果特征类型 = 结果特征主信息 ? 结果特征主信息->类型 : nullptr;
    if (!初始特征类型 || !结果特征类型
        || 初始特征类型->获取主键() != 结果特征类型->获取主键()) {
        return nullptr;
    }

    const auto 比较方法结果 = 世界树.特征().获取比较方法结果(
        初始特征类型,
        初始状态主信息->状态值,
        结果状态主信息->状态值,
        初始特征主信息,
        结果特征主信息);
    if (!比较方法结果.可比较) {
        return nullptr;
    }

    const auto 初始时间 = 初始状态主信息->发生时间 != 0
        ? 初始状态主信息->发生时间
        : 初始状态主信息->收到时间;
    const auto 结果时间 = 结果状态主信息->发生时间 != 0
        ? 结果状态主信息->发生时间
        : 结果状态主信息->收到时间;
    结构_时间段 来源时间段{ 初始时间, 结果时间 };
    if (来源时间段.起 != 0 && 来源时间段.止 != 0 && 来源时间段.止 < 来源时间段.起) {
        std::swap(来源时间段.起, 来源时间段.止);
    }

    二次特征主信息类 模板{};
    模板.种类 = 枚举_二次特征种类::状态比较;
    模板.域 = 枚举_二次特征域::存在;
    模板.粒度 = 枚举_二次特征粒度::当前场景;
    模板.基准类型 = 枚举_二次特征基准类型::无;
    模板.时间归一方式 = 枚举_时间归一方式::无;
    模板.值形态 = 枚举_二次特征值形态::标量;
    模板.主体 = 初始状态主信息->状态主体;
    if (初始状态主信息->状态主体.指针 != 结果状态主信息->状态主体.指针
        && 初始状态主信息->状态主体.主键 != 结果状态主信息->状态主体.主键) {
        模板.客体 = 结果状态主信息->状态主体;
    }
    模板.左对象 = 私有_制节点引用_线程侧(static_cast<基础信息节点类*>(初始状态));
    模板.右对象 = 私有_制节点引用_线程侧(static_cast<基础信息节点类*>(结果状态));
    模板.来源起始状态 = 私有_制节点引用_线程侧(初始状态);
    模板.来源结果状态 = 私有_制节点引用_线程侧(结果状态);
    模板.来源场景 = 私有_制节点引用_线程侧(所属场景);
    模板.来源类型 = 枚举_二次特征来源类型::状态;
    模板.来源时间段 = 来源时间段;
    模板.刷新度量签名_链键();

    auto* 节点 = 世界树.二次特征().获取或创建子二次特征_按签名(所属场景, 模板);
    if (!节点) {
        return nullptr;
    }

    (void)世界树.二次特征().绑定场景(节点, 所属场景);
    (void)世界树.二次特征().设置生成语义(
        节点,
        枚举_二次特征域::存在,
        枚举_二次特征粒度::当前场景,
        枚举_二次特征基准类型::无,
        枚举_时间归一方式::无,
        枚举_二次特征值形态::标量);
    (void)世界树.二次特征().绑定来源(
        节点,
        初始状态,
        结果状态,
        nullptr,
        所属场景,
        0,
        0,
        枚举_二次特征来源类型::状态,
        来源时间段,
        0,
        0,
        0);
    (void)世界树.二次特征().设置主体客体(
        节点,
        初始状态主信息->状态主体.指针,
        (初始状态主信息->状态主体.指针 != 结果状态主信息->状态主体.指针
            && 初始状态主信息->状态主体.主键 != 结果状态主信息->状态主体.主键)
            ? 结果状态主信息->状态主体.指针
            : nullptr);
    (void)世界树.二次特征().设置左右对象(
        节点,
        static_cast<基础信息节点类*>(初始状态),
        static_cast<基础信息节点类*>(结果状态));
    (void)世界树.二次特征().写入差值结果(
        节点,
        比较方法结果.左比较值,
        比较方法结果.右比较值);

    const auto* 主信息 = 世界树.二次特征().取二次特征主信息(节点);
    const auto 差值 = 主信息 && 主信息->差值.has_value() ? *主信息->差值 : 0;
    (void)世界树.二次特征().写入标量值(节点, 差值, 差值 != 0, 10000);
    return 节点;
}

// 功能：创建并返回或登记对应对象。
存在节点类* 私有_取或创建安全因果风险树因素节点_线程侧(
    基础信息节点类* 父宿主,
    因果节点类* 来源因果,
    I64 层级,
    I64 因素ID,
    时间戳 now) noexcept
{
    if (!父宿主 || 层级 <= 0 || 因素ID <= 0) {
        return nullptr;
    }
    const I64 节点键 = 私有_安全因果风险树节点键_线程侧(层级, 因素ID);
    auto* 节点 = 世界树.取或创建子存在_按类型并按特征I64(
        父宿主,
        私有_安全风险树节点类型词_线程侧(),
        私有_需求动作动态特征词("安全因果风险树节点键"),
        节点键);
    auto* 宿主 = reinterpret_cast<基础信息节点类*>(节点);
    if (!宿主) {
        return nullptr;
    }
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果风险树节点键"),
        节点键,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果层级"),
        层级,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果因素ID"),
        因素ID,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果证据方向"),
        安全因果风险树证据方向_负向_线程侧,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果因素证据搜索状态"),
        安全因果风险树搜索状态_未执行_线程侧,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果风险树上级因素ID"),
        0,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果风险树同层因素集合版本"),
        安全因果风险树同层因素集合版本_风险安全_线程侧,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果风险树入账状态"),
        安全因果风险树入账状态_未入账_线程侧,
        now);
    (void)世界树.写入特征_I64(
        宿主,
        私有_需求动作动态特征词("安全因果风险树聚合状态"),
        安全因果风险树聚合状态_未聚合_线程侧,
        now);
    if (来源因果) {
        (void)世界树.写入特征_指针(
            宿主,
            私有_需求动作动态特征词("目标安全因果信息"),
            来源因果,
            now);
    }
    return 节点;
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_安全风险树派生消息字段完整_线程侧(
    const 结构_任务管理派生需求消息& 消息) noexcept
{
    return !消息.父需求主键.empty()
        && 消息.派生需求类型 != 枚举_任务管理派生需求类型::未定义
        && 消息.因果路径生成类型 != 枚举_任务管理因果路径生成类型::未定义
        && 消息.阻塞级别 != 枚举_任务管理阻塞级别::未定义
        && 消息.需求特征类型指针 != 0
        && !消息.需求特征类型主键.empty()
        && 消息.需求目标主体指针 != 0
        && !消息.需求目标主体主键.empty()
        && 消息.需求当前状态指针 != 0
        && !消息.需求当前状态主键.empty()
        && 消息.需求目标状态指针 != 0
        && !消息.需求目标状态主键.empty()
        && 消息.满足关系 != 0;
}

// 功能：服务所在模块的内部辅助流程。
结构_任务管理派生需求消息 私有_构造安全风险树缺口派生消息_线程侧(
    const 任务节点* 任务头,
    const 需求节点* 来源需求,
    因果节点类* 来源因果,
    基础信息节点类* 目标主体,
    const 语素入口节点类* 目标特征,
    状态节点类* 当前状态,
    状态节点类* 目标状态,
    const char* 派生原因,
    时间戳 now) noexcept
{
    结构_任务管理派生需求消息 消息{};
    消息.消息头.任务主键 = 任务头 ? 任务头->获取主键() : std::string{};
    消息.消息头.产生时间 = now;
    消息.父需求指针 = reinterpret_cast<std::uintptr_t>(
        const_cast<需求节点*>(来源需求));
    消息.父需求主键 = 来源需求 ? 来源需求->获取主键() : std::string{};
    消息.来源因果指针 = reinterpret_cast<std::uintptr_t>(来源因果);
    消息.来源因果主键 = 来源因果 ? 来源因果->获取主键() : std::string{};
    消息.派生需求类型 = 枚举_任务管理派生需求类型::缺确认;
    消息.因果路径生成类型 = 枚举_任务管理因果路径生成类型::证据补齐;
    消息.阻塞级别 = 枚举_任务管理阻塞级别::轻微;
    消息.是否阻塞当前步骤 = true;
    消息.是否影响父任务推进 = true;
    消息.是否可能影响安全 = true;
    消息.是否可能影响服务 = false;
    消息.是否建议线程重判 = true;
    消息.需求特征类型指针 = reinterpret_cast<std::uintptr_t>(目标特征);
    消息.需求特征类型主键 = 私有_入口主键_线程侧(目标特征);
    消息.需求目标主体指针 = reinterpret_cast<std::uintptr_t>(目标主体);
    消息.需求目标主体主键 = 私有_基础主键_线程侧(目标主体);
    消息.需求当前状态指针 = reinterpret_cast<std::uintptr_t>(当前状态);
    消息.需求当前状态主键 = 私有_状态主键_线程侧(当前状态);
    消息.需求目标状态指针 = reinterpret_cast<std::uintptr_t>(目标状态);
    消息.需求目标状态主键 = 私有_状态主键_线程侧(目标状态);
    消息.满足关系 = 关系_等于;
    消息.贡献层级 = static_cast<std::uint32_t>(安全因果风险树层级_风险安全_线程侧);
    消息.层级权重 = 私有_计算因果层级权重_百万分比_线程侧(消息.贡献层级);
    if (auto* 因果信息 = 来源因果 ? 世界树.因果().取因果主信息(来源因果) : nullptr) {
        消息.稳定度摘要 = 因果信息->计算稳定度();
        消息.证据摘要 =
            std::string("安全因果风险树缺口派生需求消息")
            + " | 来源因果键=" + 消息.来源因果主键
            + " | 证据动态样本数=" + std::to_string(因果信息->证据动态样本.size())
            + " | 初始因果模板=" + std::to_string((!因果信息->已验证 && 因果信息->证据动态样本.empty()) ? 1 : 0)
            + " | 后天验证=" + std::to_string(因果信息->已验证 ? 1 : 0)
            + " | 缺口报告=1";
    } else {
        消息.证据摘要 = "安全因果风险树缺口派生需求消息 | 来源因果键=空 | 缺口报告=1";
    }
    消息.派生原因 = 派生原因 ? 派生原因 : "安全因果风险树缺口";
    同步任务管理派生需求消息语义槽(消息);
    return 消息;
}

// 功能：服务所在模块的内部辅助流程。
void 私有_追加安全风险树缺口消息_线程侧(
    结构_安全因果风险树线程维护结果& 结果,
    const 任务节点* 任务头,
    const 需求节点* 来源需求,
    因果节点类* 来源因果,
    基础信息节点类* 目标主体,
    const 语素入口节点类* 目标特征,
    状态节点类* 当前状态,
    状态节点类* 目标状态,
    const char* 派生原因,
    时间戳 now) noexcept
{
    auto 消息 = 私有_构造安全风险树缺口派生消息_线程侧(
        任务头,
        来源需求,
        来源因果,
        目标主体,
        目标特征,
        当前状态,
        目标状态,
        派生原因,
        now);
    if (私有_安全风险树派生消息字段完整_线程侧(消息)) {
        结果.缺口派生需求消息集.push_back(std::move(消息));
    }
}

// 功能：服务所在模块的内部辅助流程。
结构_安全因果风险树线程维护结果 私有_维护安全因果风险树_线程侧(
    自我类& 自我对象,
    时间戳 now) noexcept
{
    结构_安全因果风险树线程维护结果 结果{};
    结果.已执行 = true;
    if (now == 0) {
        now = 结构体_时间戳::当前_微秒();
    }

    auto* 来源需求 = 自我对象.获取安全根需求();
    auto* 任务头 = 自我对象.获取安全根任务();
    auto 记录跳过 = [&](const std::string& 原因) noexcept {
        结果.已跳过 = true;
        结果.跳过原因 = 原因;
        项目运行日志(
            "自我线程/安全因果风险树维护跳过"
            " | 原因=" + 原因
            + " | 任务=" + (任务头 ? 任务头->获取主键() : std::string("空"))
            + " | 来源需求=" + (来源需求 ? 来源需求->获取主键() : std::string("空"))
            + " | 更新持有者=自我线程"
            + " | 任务筹办更新权=0"
            + " | 不执行搜索=1"
            + " | 不写默认满足=1"
            + " | 不写因素值=1"
            + " | 不写自我安全值=1");
    };

    if (!来源需求) {
        记录跳过("缺安全根需求");
        return 结果;
    }
    auto* 目标宿主 = 私有_需求目标宿主基础节点_线程侧(来源需求);
    auto* 目标特征节点 = 私有_需求目标特征节点_线程侧(来源需求);
    const auto* 目标特征主信息 =
        目标特征节点 ? 世界树.特征().取特征主信息(目标特征节点) : nullptr;
    const auto* 目标特征类型 = 目标特征主信息 ? 目标特征主信息->类型 : nullptr;
    auto* 当前状态 = 私有_从状态引用解析状态节点(来源需求->主信息.被需求当前状态);
    auto* 目标状态 = 私有_从状态引用解析状态节点(来源需求->主信息.需求状态);
    if (!目标宿主) {
        记录跳过("缺目标宿主");
        return 结果;
    }
    if (!目标特征类型) {
        记录跳过("缺目标特征");
        return 结果;
    }
    if (!当前状态 || !目标状态) {
        记录跳过("缺安全根目标状态");
        return 结果;
    }

    需求类 需求服务{};
    auto* 目标比较 = 需求服务.获取需求方向(来源需求);
    if (!目标比较) {
        记录跳过("目标比较未构造");
        return 结果;
    }

    std::size_t 因果节点数量 = 0;
    std::size_t 主果命中数量 = 0;
    auto* 来源因果 = 私有_查找安全因果风险树来源因果_线程侧(
        目标比较,
        &因果节点数量,
        &主果命中数量);
    if (!来源因果) {
        std::ostringstream 原因;
        原因 << "缺来源因果"
            << "/因果节点=" << static_cast<I64>(因果节点数量)
            << "/主果命中=" << static_cast<I64>(主果命中数量);
        记录跳过(原因.str());
        return 结果;
    }

    const I64 输入版本 = 私有_计算安全因果风险树输入版本_线程侧(来源因果);
    I64 旧同步状态 = 0;
    I64 旧树版本 = 0;
    const bool 有旧同步状态 = 世界树.读取特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树同步状态"),
        旧同步状态);
    const bool 有旧树版本 = 世界树.读取特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树版本"),
        旧树版本);
    if (有旧同步状态
        && 有旧树版本
        && 旧同步状态 == 安全因果风险树同步状态_已同步_线程侧
        && 旧树版本 == 输入版本) {
        结果.已跳过 = true;
        结果.已同步 = true;
        结果.树版本 = 输入版本;
        结果.跳过原因 = "已同步";
        项目运行日志(
            "自我线程/安全因果风险树维护跳过"
            " | 原因=已同步"
            " | 来源需求=" + 来源需求->获取主键()
            + " | 来源因果信息ID=" + 来源因果->获取主键()
            + " | 树版本=" + std::to_string(输入版本)
            + " | 更新持有者=自我线程"
            + " | 任务筹办更新权=0");
        return 结果;
    }

    const I64 根分区 = 私有_推导需求根分区_线程侧(来源需求);
    if (!(根分区 == 1 || 根分区 == 3)) {
        记录跳过("非安全目标");
        return 结果;
    }

    项目运行日志(
        "自我线程/安全因果风险树因果前置展开未执行"
        " | 来源需求=" + 来源需求->获取主键()
        + " | 来源因果信息ID=" + 来源因果->获取主键()
        + " | 原因=当前缺动态生成的条件链"
        + " | 因果前置缺口报告数量=" + std::to_string(结果.因果前置缺口数量)
        + " | 自我线程固定五因素表=0"
        + " | 固定五因素生成=0"
        + " | 自我线程固定场景OR路径=0"
        + " | 自我线程直接生成缺口子需求=0");

    结果.树版本 = 输入版本;
    结果.版本变化 = !有旧树版本 || 旧树版本 != 输入版本;
    bool ok = true;
    ok = 世界树.写入特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树同步状态"),
        安全因果风险树同步状态_已同步_线程侧,
        now) && ok;
    ok = 世界树.写入特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树版本"),
        输入版本,
        now) && ok;
    ok = 世界树.写入特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树节点数量"),
        static_cast<I64>(结果.节点数量),
        now) && ok;
    ok = 世界树.写入特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树因果前置缺口报告数量"),
        static_cast<I64>(结果.因果前置缺口数量),
        now) && ok;
    ok = 世界树.写入特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树搜索缺口报告数量"),
        static_cast<I64>(结果.搜索缺口数量),
        now) && ok;
    ok = 世界树.写入特征_I64(
        目标宿主,
        私有_需求动作动态特征词("安全因果风险树最近维护时间"),
        static_cast<I64>(now),
        now) && ok;
    结果.已同步 = ok;

    std::ostringstream 输出;
    输出 << "自我线程/安全因果风险树维护完成"
        << " | 任务=" << (任务头 ? 任务头->获取主键() : std::string("空"))
        << " | 来源需求=" << 来源需求->获取主键()
        << " | 来源因果信息ID=" << 来源因果->获取主键()
        << " | 树版本=" << 结果.树版本
        << " | 版本变化=" << (结果.版本变化 ? 1 : 0)
        << " | 节点数量=" << static_cast<I64>(结果.节点数量)
        << " | 因果前置缺口报告数量=" << static_cast<I64>(结果.因果前置缺口数量)
        << " | 搜索缺口报告数量=" << static_cast<I64>(结果.搜索缺口数量)
        << " | 场景特征值明确缺口报告数量=" << static_cast<I64>(结果.场景特征值明确缺口数量)
        << " | 场景影响前置缺口报告数量=" << static_cast<I64>(结果.场景影响前置缺口数量)
        << " | 派生需求消息数量=" << static_cast<I64>(结果.缺口派生需求消息集.size())
        << " | 更新持有者=自我线程"
        << " | 任务筹办更新权=0"
        << " | 只反推更新风险树=1"
        << " | 直接写需求树=0"
        << " | 不执行搜索=1"
        << " | 不写默认满足=1"
        << " | 不写因素值=1"
        << " | 不写风险安全层总值=1"
        << " | 不写自我安全值=1";
    项目运行日志(输出.str());
    return 结果;
}

// 功能：结算任务、需求、价值或结果贡献。
void 私有_刷新父级需求结算_线程侧(需求节点* 起点需求) noexcept
{
    auto* 父需求 = 起点需求 ? reinterpret_cast<需求节点*>(起点需求->父) : nullptr;
    while (父需求 && 父需求->父) {
        I64 子安全合计 = 0;
        I64 子服务合计 = 0;
        if (auto* 首子 = reinterpret_cast<需求节点*>(父需求->子)) {
            auto* 子 = 首子;
            do {
                if (子) {
                    子安全合计 += (std::max<I64>)(0, 子->主信息.累计安全结算);
                    子服务合计 += (std::max<I64>)(0, 子->主信息.累计服务结算);
                }
                子 = 子 ? reinterpret_cast<需求节点*>(子->下) : nullptr;
            } while (子 && 子 != 首子);
        }
        父需求->主信息.累计安全结算 =
            (std::min<I64>)((std::max<I64>)(0, 父需求->主信息.安全权重), 子安全合计);
        父需求->主信息.累计服务结算 =
            (std::min<I64>)((std::max<I64>)(0, 父需求->主信息.服务权重), 子服务合计);
        父需求->主信息.最近结算时间 = 起点需求->主信息.最近结算时间;
        父需求->主信息.最近结算任务主键 = 起点需求->主信息.最近结算任务主键;
        父需求 = reinterpret_cast<需求节点*>(父需求->父);
    }
}

// 功能：服务所在模块的内部辅助流程。
结构_线程需求收束结果 私有_收束来源需求_任务价值反馈后处理_线程侧(
    需求节点* 来源需求,
    任务节点* 任务头,
    I64 安全结算增量,
    I64 服务结算增量,
    bool 允许收束当前状态,
    时间戳 now) noexcept
{
    结构_线程需求收束结果 结果{};
    if (!来源需求) {
        结果.摘要 = "自我线程/来源需求收束失败 | 原因=来源需求为空";
        return 结果;
    }

    const auto 旧状态指针 = 来源需求->主信息.被需求当前状态.指针;
    const auto 旧状态主键 = 来源需求->主信息.被需求当前状态.主键;
    bool 已提交收束 = false;
    if (允许收束当前状态
        && (来源需求->主信息.需求状态.指针
            || !来源需求->主信息.需求状态.主键.empty())) {
        来源需求->主信息.被需求当前状态 = 来源需求->主信息.需求状态;
        来源需求->主信息.需求有效截止 = now;
        已提交收束 = true;
        结果.当前状态已回写 =
            来源需求->主信息.被需求当前状态.指针 != 旧状态指针
            || 来源需求->主信息.被需求当前状态.主键 != 旧状态主键;
    }

    if (安全结算增量 > 0) {
        来源需求->主信息.累计安全结算 += 安全结算增量;
        结果.已写结算 = true;
    }
    if (服务结算增量 > 0) {
        来源需求->主信息.累计服务结算 += 服务结算增量;
        结果.已写结算 = true;
    }
    来源需求->主信息.累计安全结算 =
        (std::min<I64>)((std::max<I64>)(0, 来源需求->主信息.安全权重), 来源需求->主信息.累计安全结算);
    来源需求->主信息.累计服务结算 =
        (std::min<I64>)((std::max<I64>)(0, 来源需求->主信息.服务权重), 来源需求->主信息.累计服务结算);

    if (任务头) {
        来源需求->主信息.最近结算任务主键 = 任务头->获取主键();
    }
    if (已提交收束 || 结果.当前状态已回写 || 结果.已写结算) {
        来源需求->主信息.最近结算时间 = now;
        来源需求->主信息.统计.最后观测时间 = now;
        私有_刷新父级需求结算_线程侧(来源需求);

        需求类 需求服务{};
        if (auto* 父需求 = reinterpret_cast<需求节点*>(来源需求->父)) {
            (void)需求服务.刷新子需求权重(父需求);
        }
        (void)需求服务.刷新子需求权重(来源需求);
        需求类::刷新需求及祖先结构角色(来源需求);
        结果.已刷新权重 = true;
    }

    结果.成功 = true;
    std::ostringstream 摘要;
    摘要 << "自我线程/来源需求收束"
        << " | 需求=" << 来源需求->获取主键()
        << " | 任务=" << (任务头 ? 任务头->获取主键() : std::string("空"))
        << " | 已截止=" << (来源需求->主信息.需求有效截止 != 0 ? "是" : "否")
        << " | 当前状态已回写=" << (结果.当前状态已回写 ? "是" : "否")
        << " | 已写结算=" << (结果.已写结算 ? "是" : "否")
        << " | 已刷新权重=" << (结果.已刷新权重 ? "是" : "否")
        << " | 安全账本=" << 来源需求->主信息.累计安全结算
        << "/" << 来源需求->主信息.安全权重
        << " | 服务账本=" << 来源需求->主信息.累计服务结算
        << "/" << 来源需求->主信息.服务权重
        << " | 方法动作动态=0";
    结果.摘要 = 摘要.str();
    项目运行日志(结果.摘要);
    return 结果;
}

// 功能：把处理结果写入指定对象、场景或日志。
bool 私有_写入结算叶子任务价值输入(
    基础信息节点类* 输入包,
    需求节点* 来源需求,
    任务节点* 任务头,
    I64 安全结算增量,
    I64 服务结算增量,
    I64 任务完成度百万分比,
    状态节点类* 实际结果状态,
    const 结构_线程服务价值结算证据摘要* 服务证据摘要,
    动态节点类* 来源动作动态,
    动态节点类* 满足证据动态,
    时间戳 now) noexcept
{
    if (!输入包 || !来源需求 || !任务头) {
        return false;
    }

    bool ok = 世界树.写入特征_指针(
        输入包,
        私有_需求动作动态特征词("来源需求"),
        来源需求,
        now);
    ok = 世界树.写入特征_指针(
        输入包,
        私有_需求动作动态特征词("任务信息节点"),
        任务头,
        now) && ok;
    if (auto* 任务虚拟存在 = 任务类::取或创建_任务虚拟存在(
            任务头,
            任务头->主信息.场景.指针)) {
        ok = 世界树.写入特征_指针(
            输入包,
            私有_需求动作动态特征词("任务虚拟存在"),
            任务虚拟存在,
            now) && ok;
    } else {
        ok = false;
    }
    ok = 世界树.写入特征_I64(
        输入包,
        私有_需求动作动态特征词("任务状态"),
        static_cast<I64>(任务类::读取任务状态(任务头)),
        now) && ok;
    ok = 世界树.写入特征_I64(
        输入包,
        私有_需求动作动态特征词("安全结算增量"),
        安全结算增量,
        now) && ok;
    ok = 世界树.写入特征_I64(
        输入包,
        私有_需求动作动态特征词("服务结算增量"),
        服务结算增量,
        now) && ok;
    ok = 世界树.写入特征_I64(
        输入包,
        私有_需求动作动态特征词("任务完成度百万分比"),
        std::clamp<I64>(任务完成度百万分比, 0, 1'000'000),
        now) && ok;
    if (服务证据摘要) {
        const auto 状态变化数 =
            (std::min<std::size_t>)(服务证据摘要->服务对象外在特征状态变化数,
                static_cast<std::size_t>((std::numeric_limits<I64>::max)()));
        ok = 世界树.写入特征_I64(
            输入包,
            私有_需求动作动态特征词("服务对象外在特征状态变化数"),
            static_cast<I64>(状态变化数),
            now) && ok;
        ok = 世界树.写入特征_I64(
            输入包,
            私有_需求动作动态特征词("服务对象外在特征状态改善证据"),
            服务证据摘要->有服务对象外在特征状态改善证据 ? 1 : 0,
            now) && ok;
        ok = 世界树.写入特征_I64(
            输入包,
            私有_需求动作动态特征词("服务结果可验证"),
            服务证据摘要->服务结果可验证 ? 1 : 0,
            now) && ok;
        ok = 世界树.写入特征_I64(
            输入包,
            私有_需求动作动态特征词("服务结果可归因于自我动作"),
            服务证据摘要->服务结果可归因于自我动作 ? 1 : 0,
            now) && ok;
    }
    if (实际结果状态) {
        ok = 世界树.写入特征_指针(
            输入包,
            私有_需求动作动态特征词("实际结果状态"),
            实际结果状态,
            now) && ok;
    }
    if (来源动作动态) {
        ok = 世界树.写入特征_指针(
            输入包,
            私有_需求动作动态特征词("来源动作动态"),
            来源动作动态,
            now) && ok;
    }
    if (满足证据动态) {
        ok = 世界树.写入特征_指针(
            输入包,
            私有_需求动作动态特征词("满足证据"),
            满足证据动态,
            now) && ok;
    }
    return ok;
}

// 自我线程只负责决定调用“结算叶子任务价值”本能方法，并读取运行存在中的
// 实际安全结算结果；服务值增加由 G0 已确认成功服务后的饱和入账路径提交。

// 功能：自我线程只负责决定调用“结算叶子任务价值”本能方法，并读取运行存在中的 实际安全结算结果；服务值增加由 G0 已确认成功服...
结构_线程价值结算结果 私有_调用结算叶子任务价值本能方法_线程侧(
    自我类& 自我对象,
    需求节点* 来源需求,
    任务节点* 任务头,
    I64 安全结算增量,
    I64 服务结算增量,
    I64 任务完成度百万分比,
    状态节点类* 实际结果状态,
    const 结构_线程服务价值结算证据摘要* 服务证据摘要,
    动态节点类* 来源动作动态,
    动态节点类* 满足证据动态,
    时间戳 now) noexcept
{
    结构_线程价值结算结果 结果{};
    结果.旧安全值 = 自我对象.获取安全值();
    结果.旧服务值 = 自我对象.获取服务值();
    结果.新安全值 = 结果.旧安全值;
    结果.新服务值 = 结果.旧服务值;

    if (!来源需求 || !任务头) {
        结果.摘要 = "结算叶子任务价值失败 | 原因=来源需求或任务为空";
        return 结果;
    }
    if (任务类::读取任务状态(任务头) != 枚举_任务状态::已结算) {
        结果.摘要 = "结算叶子任务价值失败 | 原因=任务未形成已结算被动因";
        return 结果;
    }
    if (安全结算增量 < 0
        || 服务结算增量 < 0
        || 安全结算增量 == (std::numeric_limits<I64>::max)()
        || 服务结算增量 == (std::numeric_limits<I64>::max)()) {
        结果.摘要 = "结算叶子任务价值失败 | 原因=非法结算增量";
        return 结果;
    }

    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 自我内部世界 = 自我对象.确保自我内部世界();
    if (!自我存在 || !自我内部世界) {
        结果.摘要 = "结算叶子任务价值失败 | 原因=自我存在或内部世界缺失";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    auto* 方法首节点 = 本能方法类::查找或创建本能方法首节点(
        自我存在,
        枚举_本能方法ID::自我_结算叶子任务价值,
        now);
    if (!方法首节点) {
        结果.摘要 = "结算叶子任务价值失败 | 原因=本能方法首节点缺失";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    const auto* 输入场景名 = 语素集.添加信息入口词(
        "结算叶子任务价值_输入_" + std::to_string(now),
        枚举_信息入口类型::场景实例入口);
    const auto* 输出场景名 = 语素集.添加信息入口词(
        "结算叶子任务价值_输出_" + std::to_string(now),
        枚举_信息入口类型::场景实例入口);
    auto* 输入参数场景 = 世界树.场景().创建场景_按名称(
        reinterpret_cast<基础信息节点类*>(自我内部世界),
        输入场景名,
        枚举_世界类型::内部世界);
    auto* 输出结果场景 = 世界树.场景().创建场景_按名称(
        reinterpret_cast<基础信息节点类*>(自我内部世界),
        输出场景名,
        枚举_世界类型::内部世界);
    auto* 输入包 = 输入参数场景
        ? 世界树.取或创建子特征_按类型(
            reinterpret_cast<基础信息节点类*>(输入参数场景),
            私有_需求动作动态特征词("输入条件包"))
        : nullptr;
    if (!输入包
        || !私有_写入结算叶子任务价值输入(
            reinterpret_cast<基础信息节点类*>(输入包),
            来源需求,
            任务头,
            安全结算增量,
            服务结算增量,
            任务完成度百万分比,
            实际结果状态,
            服务证据摘要,
            来源动作动态,
            满足证据动态,
            now)) {
        结果.摘要 = "结算叶子任务价值失败 | 原因=输入条件包构造失败";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    auto* 运行存在 = 取本能动作集().执行功能函数(
        static_cast<枚举_本能动作ID>(枚举_本能方法ID::自我_结算叶子任务价值),
        方法首节点,
        输入参数场景,
        输出结果场景);
    auto* 运行宿主 = reinterpret_cast<基础信息节点类*>(运行存在);
    if (!运行宿主) {
        结果.摘要 = "结算叶子任务价值失败 | 原因=本能方法未返回运行存在";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    (void)世界树.读取特征_I64(
        运行宿主,
        私有_需求动作动态特征词("旧安全值"),
        结果.旧安全值);
    (void)世界树.读取特征_I64(
        运行宿主,
        私有_需求动作动态特征词("新安全值"),
        结果.新安全值);
    (void)世界树.读取特征_I64(
        运行宿主,
        私有_需求动作动态特征词("旧服务值"),
        结果.旧服务值);
    (void)世界树.读取特征_I64(
        运行宿主,
        私有_需求动作动态特征词("新服务值"),
        结果.新服务值);
    (void)世界树.读取特征_I64(
        运行宿主,
        私有_需求动作动态特征词("安全结算增量"),
        结果.实际安全增量);
    (void)世界树.读取特征_I64(
        运行宿主,
        私有_需求动作动态特征词("服务结算增量"),
        结果.实际服务增量);
    结果.D2_结算动作动态 = 私有_读取动作动态_线程侧(运行宿主);
    if ((结果.实际安全增量 > 0 || 结果.实际服务增量 > 0)
        && !结果.D2_结算动作动态) {
        项目运行警告日志(
            "结算叶子任务价值缺D2动作动态"
            " | 任务=" + 任务头->获取主键()
            + " | 需求=" + 来源需求->获取主键()
            + " | 安全+=" + std::to_string(结果.实际安全增量)
            + " | 服务+=" + std::to_string(结果.实际服务增量));
    }

    结果.成功 = true;
    结果.已处理 = true;
    std::ostringstream 摘要;
    摘要 << "结算叶子任务价值"
        << " | 任务=" << 任务头->获取主键()
        << " | 需求=" << 来源需求->获取主键()
        << " | 安全+=" << 结果.实际安全增量
        << " | 服务+=" << 结果.实际服务增量
        << " | D2=" << (结果.D2_结算动作动态
            ? 结果.D2_结算动作动态->获取主键()
            : std::string("缺"));
    结果.摘要 = 摘要.str();
    项目运行日志(结果.摘要);
    return 结果;
}

// 功能：服务所在模块的内部辅助流程。
std::size_t 私有_处理共享任务挂接需求满足反馈_线程侧(
    自我类& 自我对象,
    任务节点* 来源任务,
    需求节点* 来源需求,
    I64 本次安全满足量,
    I64 本次服务满足量,
    I64 安全累计比例_百万分比,
    I64 服务累计比例_百万分比,
    bool 任务域已完成,
    时间戳 now,
    const std::string& 反馈事件主键,
    动态节点类* 来源任务动态,
    const std::vector<结构_任务管理状态变化项>* 服务对象状态变化集,
    const 动作验证报告::结构_动作验证报告摘要* 源动作验证报告摘要) noexcept
{
    auto* 任务头 = 私有_归一到任务头结点(来源任务);
    if (!任务头 || !来源需求) {
        return 0;
    }

    auto 挂接需求集 = 私有_按任务收集非根需求集_线程侧(任务头);
    std::size_t 跳过来源需求数 = 0;
    std::size_t 跳过已截止数 = 0;
    std::size_t 处理需求数 = 0;
    std::size_t 已生成快照数 = 0;

    for (auto* 挂接需求 : 挂接需求集) {
        if (!挂接需求 || 私有_需求节点是结构根_线程侧(挂接需求)) {
            continue;
        }
        if (挂接需求 == 来源需求) {
            ++跳过来源需求数;
            continue;
        }
        if (挂接需求->主信息.需求有效截止 != 0) {
            ++跳过已截止数;
            项目运行日志(
                "自我线程/共享任务挂接需求扇出跳过"
                " | 任务=" + 任务头->获取主键()
                + " | 需求=" + 挂接需求->获取主键()
                + " | 原因=需求已截止");
            continue;
        }

        auto 挂接投影预判 =
            私有_查询叶子任务结算前因果投影_线程侧(挂接需求, 任务头);
        auto 挂接正式结算证据 = 私有_收集叶子任务正式结算证据_线程侧(
            挂接需求,
            任务头,
            挂接投影预判,
            now);
        if (!挂接正式结算证据.任务完成动作动态 && 来源任务动态) {
            挂接正式结算证据.任务完成动作动态 = 来源任务动态;
            私有_移除正式结算缺失证据_线程侧(
                挂接正式结算证据,
                "缺任务完成动作动态");
            私有_刷新叶子任务正式结算证据摘要_线程侧(挂接正式结算证据);
        }

        const std::string 共享反馈事件主键 = 反馈事件主键.empty()
            ? std::string{}
            : 反馈事件主键 + "|共享|" + 挂接需求->获取主键() + "|" + 任务头->获取主键();
        const auto 判定消息 = 私有_构造结算域判定消息_线程侧(
            源动作验证报告摘要,
            本次安全满足量,
            本次服务满足量);
        const auto 结算域判定 = 私有_判定任务结算域_线程侧(
            任务头,
            挂接需求,
            判定消息,
            安全累计比例_百万分比 > 0
                ? 安全累计比例_百万分比
                : 服务累计比例_百万分比,
            挂接正式结算证据);
        项目运行日志(
            "自我线程/任务结算域分类"
            " | 来源=共享挂接"
            " | 任务=" + 任务头->获取主键()
            + " | 需求=" + 挂接需求->获取主键()
            + " | 域=" + 私有_任务结算域文本_线程侧(结算域判定.域)
            + " | 原因=" + 结算域判定.原因
            + " | actual状态=" + (挂接正式结算证据.actual状态
                ? 挂接正式结算证据.actual状态->获取主键()
                : std::string("缺"))
            + " | " + 私有_动作验证摘要日志文本_线程侧(判定消息.动作验证报告摘要));
        if (结算域判定.域 != 枚举_任务结算域_线程侧::普通价值) {
            const auto 闭账结果 = 私有_处理非核心结算闭账_任务管理新链(
                自我对象,
                任务头,
                挂接需求,
                结算域判定.域,
                挂接正式结算证据,
                来源任务动态,
                now);
            ++处理需求数;
            if (闭账结果.成功) {
                ++已生成快照数;
            }
            项目运行日志(
                "自我线程/共享任务挂接需求扇出处理"
                " | 任务=" + 任务头->获取主键()
                + " | 来源需求=" + 来源需求->获取主键()
                + " | 挂接需求=" + 挂接需求->获取主键()
                + " | 域=" + 私有_任务结算域文本_线程侧(结算域判定.域)
                + " | 已生成=" + std::string(闭账结果.成功 ? "是" : "否")
                + " | 不进入普通满足反馈=1");
            continue;
        }
        auto 快照 = 私有_处理任务满足反馈_线程侧(
            自我对象,
            任务头,
            本次安全满足量,
            本次服务满足量,
            安全累计比例_百万分比,
            服务累计比例_百万分比,
            now,
            共享反馈事件主键,
            任务域已完成 || !私有_存在活动直接子需求_任务管理新链(挂接需求),
            来源任务动态,
            服务对象状态变化集,
            挂接需求,
            &挂接正式结算证据,
            &判定消息.动作验证报告摘要,
            true);

        私有_唤醒派生需求来源任务_任务管理新链(
            自我对象,
            挂接需求,
            now,
            快照.任务完成动作动态
                ? 快照.任务完成动作动态
                : 挂接正式结算证据.任务完成动作动态);

        ++处理需求数;
        if (快照.已生成) {
            ++已生成快照数;
        }
        项目运行日志(
            "自我线程/共享任务挂接需求扇出处理"
            " | 任务=" + 任务头->获取主键()
            + " | 来源需求=" + 来源需求->获取主键()
            + " | 挂接需求=" + 挂接需求->获取主键()
            + " | 已生成=" + std::string(快照.已生成 ? "是" : "否")
            + " | 摘要=" + 快照.摘要);
    }

    项目运行日志(
        "自我线程/共享任务挂接需求扇出扫描"
        " | 任务=" + 任务头->获取主键()
        + " | 来源需求=" + 来源需求->获取主键()
        + " | 挂接需求数=" + std::to_string(挂接需求集.size())
        + " | 跳过来源=" + std::to_string(跳过来源需求数)
        + " | 跳过已截止=" + std::to_string(跳过已截止数)
        + " | 已处理=" + std::to_string(处理需求数)
        + " | 已生成=" + std::to_string(已生成快照数));
    return 已生成快照数;
}

// 功能：结算任务、需求、价值或结果贡献。
const char* 私有_任务结算域文本_线程侧(const 枚举_任务结算域_线程侧 域) noexcept
{
    switch (域) {
    case 枚举_任务结算域_线程侧::普通价值: return "普通价值";
    case 枚举_任务结算域_线程侧::内部治理: return "内部治理";
    case 枚举_任务结算域_线程侧::证据无核心价值: return "证据无核心价值";
    case 枚举_任务结算域_线程侧::仅闭账: return "仅闭账";
    default: return "未定义";
    }
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_任务节点同一_线程侧(const 任务节点* 左, const 任务节点* 右) noexcept
{
    if (左 == 右) {
        return 左 != nullptr;
    }
    return 左
        && 右
        && !左->获取主键().empty()
        && 左->获取主键() == 右->获取主键();
}

// 功能：结算任务、需求、价值或结果贡献。
bool 私有_动作验证摘要允许普通价值结算_线程侧(
    const 动作验证报告::结构_动作验证报告摘要& 摘要) noexcept
{
    if (!摘要.有报告) {
        return false;
    }

    const bool 验证可用 =
        摘要.验证状态 == 动作验证报告::枚举_动作验证状态::验证成功
        || 摘要.验证状态 == 动作验证报告::枚举_动作验证状态::验证相似
        || 摘要.验证状态 == 动作验证报告::枚举_动作验证状态::已提交正常事实;
    const bool 事实可提交 =
        摘要.事实提交等级 == 动作验证报告::枚举_事实提交等级::正常事实
        || 摘要.事实提交等级 == 动作验证报告::枚举_事实提交等级::待复核事实;
    return 验证可用 && 事实可提交;
}

// 功能：服务所在模块的内部辅助流程。
std::string 私有_动作验证摘要日志文本_线程侧(
    const 动作验证报告::结构_动作验证报告摘要& 摘要)
{
    if (!摘要.有报告) {
        return "动作验证报告摘要=无";
    }

    std::ostringstream 输出;
    输出 << "动作验证报告摘要"
        << " | 报告ID=" << (摘要.动作验证报告ID.empty() ? "空" : 摘要.动作验证报告ID)
        << " | 验证状态值=" << static_cast<int>(摘要.验证状态)
        << " | 事实提交等级值=" << static_cast<int>(摘要.事实提交等级)
        << " | 回读置信度=" << 摘要.回读置信度_Q10000;
    return 输出.str();
}

// 功能：结算任务、需求、价值或结果贡献。
结构_任务管理结果状态消息 私有_构造结算域判定消息_线程侧(
    const 动作验证报告::结构_动作验证报告摘要* 摘要,
    I64 本次安全满足量,
    I64 本次服务满足量)
{
    结构_任务管理结果状态消息 消息{};
    if (摘要) {
        消息.动作验证报告摘要 = *摘要;
    }
    消息.任务价值反馈.本次安全满足量 = 本次安全满足量;
    消息.任务价值反馈.本次服务满足量 = 本次服务满足量;
    return 消息;
}

// 功能：结算任务、需求、价值或结果贡献。
结构_任务结算域判定_线程侧 私有_判定任务结算域_线程侧(
    任务节点* 任务头,
    需求节点* 来源需求,
    const 结构_任务管理结果状态消息& 结果消息,
    I64 消息完成度百万分比,
    const 结构_叶子任务正式结算证据& 正式结算证据) noexcept
{
    结构_任务结算域判定_线程侧 判定{};
    if (!任务头) {
        判定.原因 = "任务为空";
        return 判定;
    }
    if (!来源需求) {
        判定.原因 = "来源需求为空";
        return 判定;
    }

    const auto* 目标特征类型 = 需求类::读取需求目标特征类型(来源需求);
    if (私有_目标特征类型命中任一_线程侧(
            目标特征类型,
            { "安全因果因素证据搜索状态" })) {
        判定.域 = 枚举_任务结算域_线程侧::证据无核心价值;
        判定.原因 = "目标特征为证据搜索状态";
        return 判定;
    }

    const auto 任务角色 = 任务类::读取任务角色(
        任务头,
        枚举_任务角色::未定义);
    auto* 管理对象任务 = 任务类::读取任务管理对象任务(任务头);
    const bool 是管理壳任务 =
        任务角色 == 枚举_任务角色::需求管理任务
        || 来源需求->子 != nullptr
        || (管理对象任务 && !私有_任务节点同一_线程侧(管理对象任务, 任务头));
    if (是管理壳任务) {
        判定.域 = 枚举_任务结算域_线程侧::内部治理;
        判定.原因 = "任务为需求管理或任务管理壳";
        return 判定;
    }

    if (消息完成度百万分比 <= 0) {
        判定.原因 = "完成度为零或未形成";
        return 判定;
    }
    if (!私有_动作验证摘要允许普通价值结算_线程侧(结果消息.动作验证报告摘要)) {
        判定.原因 = "闭环验证报告未允许普通价值结算";
        return 判定;
    }
    if (!正式结算证据.actual状态) {
        判定.原因 = "缺实际结果状态";
        return 判定;
    }

    const I64 安全权重上限 = 任务类::读取任务承接安全权重上限(任务头);
    const I64 服务权重上限 = 任务类::读取任务承接服务权重上限(任务头);
    const bool 安全权重合法 =
        安全权重上限 > 0
        && 安全权重上限 != (std::numeric_limits<I64>::max)();
    const bool 服务权重合法 =
        服务权重上限 > 0
        && 服务权重上限 != (std::numeric_limits<I64>::max)();
    if (!安全权重合法
        && !服务权重合法
        && 结果消息.任务价值反馈.本次安全满足量 <= 0
        && 结果消息.任务价值反馈.本次服务满足量 <= 0) {
        判定.原因 = "缺合法核心价值权重或增量";
        return 判定;
    }

    判定.域 = 枚举_任务结算域_线程侧::普通价值;
    判定.原因 = "VX0通过且普通叶子任务具备核心价值输入";
    return 判定;
}

// 功能：结算任务、需求、价值或结果贡献。
结构_非核心结算闭账结果_线程侧 私有_处理非核心结算闭账_任务管理新链(
    自我类& 自我对象,
    任务节点* 任务头,
    需求节点* 来源需求,
    枚举_任务结算域_线程侧 结算域,
    const 结构_叶子任务正式结算证据& 正式结算证据,
    动态节点类* 来源任务动态,
    时间戳 now) noexcept
{
    结构_非核心结算闭账结果_线程侧 结果{};
    if (!任务头) {
        结果.摘要 = "自我线程/任务结算域闭账失败 | 原因=任务为空";
        项目运行错误日志(结果.摘要);
        return 结果;
    }

    const auto 当前任务状态 = 任务类::读取任务状态(任务头, 枚举_任务状态::未定义);
    const bool 任务状态可闭账 =
        当前任务状态 == 枚举_任务状态::完成
        || 当前任务状态 == 枚举_任务状态::已结算;
    if (!任务状态可闭账) {
        结果.摘要 =
            "自我线程/任务结算域闭账延后"
            " | 原因=任务尚未形成完成或已结算被动因"
            " | 域=" + std::string(私有_任务结算域文本_线程侧(结算域))
            + " | 任务=" + 任务头->获取主键()
            + " | 需求=" + (来源需求 ? 来源需求->获取主键() : std::string("空"))
            + " | 当前任务状态=" + std::to_string(static_cast<int>(当前任务状态))
            + " | 不收束来源需求=1"
            + " | 不提交已结算=1";
        项目运行日志(结果.摘要);
        return 结果;
    }

    const bool 允许收束来源需求 =
        正式结算证据.actual满足目标
        || (来源需求 && 私有_需求状态已满足_任务管理新链(来源需求));
    if (来源需求 && 允许收束来源需求) {
        const auto 收束结果 = 私有_收束来源需求_任务价值反馈后处理_线程侧(
            来源需求,
            任务头,
            0,
            0,
            true,
            now);
        if (!收束结果.成功) {
            结果.摘要 = 收束结果.摘要.empty()
                ? "自我线程/任务结算域闭账失败 | 原因=来源需求收束失败"
                : 收束结果.摘要;
            项目运行错误日志(结果.摘要);
            return 结果;
        }
    }

    if (结算域 == 枚举_任务结算域_线程侧::证据无核心价值 && 来源需求) {
        const auto 默认满足提交结果 =
            私有_尝试提交安全因果因素无负证据默认满足_线程侧(
                自我对象,
                来源需求,
                任务头,
                正式结算证据,
                now);
        if (默认满足提交结果.已尝试 && !默认满足提交结果.成功) {
            结果.摘要 = 默认满足提交结果.摘要.empty()
                ? "自我线程/任务结算域闭账失败 | 原因=证据默认满足提交失败"
                : 默认满足提交结果.摘要;
            项目运行错误日志(结果.摘要);
            return 结果;
        }

        const auto 场景影响提交结果 =
            私有_尝试提交风险安全场景影响部分_线程侧(
                自我对象,
                来源需求,
                任务头,
                正式结算证据,
                now);
        if (场景影响提交结果.已尝试 && 场景影响提交结果.已拒绝) {
            项目运行日志(
                场景影响提交结果.摘要
                + " | 非核心证据闭账继续=1");
        }
    }

    if (任务类::读取任务状态(任务头, 枚举_任务状态::未定义)
        != 枚举_任务状态::已结算) {
        if (!私有_提交任务已结算状态_线程侧(任务头, 来源需求, now)) {
            结果.摘要 =
                "自我线程/任务结算域闭账失败 | 原因=任务已结算状态提交失败"
                " | 域=" + std::string(私有_任务结算域文本_线程侧(结算域))
                + " | 任务=" + 任务头->获取主键()
                + " | 需求=" + (来源需求 ? 来源需求->获取主键() : std::string("空"));
            项目运行错误日志(结果.摘要);
            return 结果;
        }
        结果.已提交已结算 = true;
    }

    auto* 已结算动作动态 = 私有_读取任务状态动作动态_线程侧(任务头);
    结果.任务闭账动作动态 = 已结算动作动态
        ? 已结算动作动态
        : (正式结算证据.任务完成动作动态
            ? 正式结算证据.任务完成动作动态
            : 来源任务动态);
    if (来源需求) {
        私有_唤醒派生需求来源任务_任务管理新链(
            自我对象,
            来源需求,
            now,
            结果.任务闭账动作动态);
    }

    结果.成功 = true;
    结果.摘要 =
        "自我线程/任务结算域闭账"
        " | 域=" + std::string(私有_任务结算域文本_线程侧(结算域))
        + " | 任务=" + 任务头->获取主键()
        + " | 需求=" + (来源需求 ? 来源需求->获取主键() : std::string("空"))
        + " | 已提交已结算=" + std::string(结果.已提交已结算 ? "是" : "否")
        + " | 不进入普通满足反馈=1"
        + " | 不调用结算叶子任务价值=1"
        + " | 不写核心安全值=1"
        + " | 不写服务值=1";
    项目运行日志(结果.摘要);
    return 结果;
}

// 功能：唤醒等待中的任务、线程或治理链。
void 私有_按成功结果满足来源需求并唤醒父任务_任务管理新链(
    自我类& 自我对象,
    const 结构_任务管理结果状态消息& 结果消息,
    时间戳 now) noexcept
{
    auto* 任务头 = 私有_归一到任务头结点(
        私有_按主键解析任务节点(结果消息.消息头.任务主键));
    const auto 任务域状态 = 任务头
        ? 任务类::读取任务状态(任务头, 枚举_任务状态::未定义)
        : 枚举_任务状态::未定义;
    const bool 任务域已完成 =
        任务头
        && (任务域状态 == 枚举_任务状态::完成
            || 任务域状态 == 枚举_任务状态::已结算);
    if (!结果消息.是否成功
        && 结果消息.结果状态 != 枚举_任务管理结果状态::成功
        && 结果消息.结果状态 != 枚举_任务管理结果状态::收束完成
        && !任务域已完成) {
        return;
    }

    auto* 来源需求 = 私有_任务来源需求_线程侧(任务头);
    if (!来源需求) {
        return;
    }

    动态节点类* 来源任务动态 = nullptr;
    if (任务头 && 任务头->主信息.任务虚拟存在.指针) {
        void* 动态指针 = nullptr;
        if (世界树.读取特征_指针(
                reinterpret_cast<基础信息节点类*>(任务头->主信息.任务虚拟存在.指针),
                私有_需求动作动态特征词("任务状态动作动态"),
                动态指针)) {
            来源任务动态 = reinterpret_cast<动态节点类*>(动态指针);
        }
    }

    const I64 消息完成度百万分比 = std::clamp<I64>(
        static_cast<I64>(结果消息.完成度 * 1'000'000.0 + 0.5),
        0,
        1'000'000);
    const I64 默认累计比例_百万分比 =
        消息完成度百万分比 > 0
            ? 消息完成度百万分比
            : (任务域已完成 ? 1'000'000 : -1);
    const I64 安全累计比例_百万分比 =
        结果消息.任务价值反馈.安全累计比例_百万分比 >= 0
            ? 结果消息.任务价值反馈.安全累计比例_百万分比
            : 默认累计比例_百万分比;
    const I64 服务累计比例_百万分比 =
        结果消息.任务价值反馈.服务累计比例_百万分比 >= 0
            ? 结果消息.任务价值反馈.服务累计比例_百万分比
            : 默认累计比例_百万分比;

    auto 来源投影预判 = 私有_查询叶子任务结算前因果投影_线程侧(来源需求, 任务头);
    auto 来源正式结算证据 = 私有_收集叶子任务正式结算证据_线程侧(
        来源需求,
        任务头,
        来源投影预判,
        now);
    if (!来源正式结算证据.任务完成动作动态 && 来源任务动态) {
        来源正式结算证据.任务完成动作动态 = 来源任务动态;
        私有_移除正式结算缺失证据_线程侧(
            来源正式结算证据,
            "缺任务完成动作动态");
        私有_刷新叶子任务正式结算证据摘要_线程侧(来源正式结算证据);
    }

    const auto 结算域判定 = 私有_判定任务结算域_线程侧(
        任务头,
        来源需求,
        结果消息,
        消息完成度百万分比,
        来源正式结算证据);
    项目运行日志(
        "自我线程/任务结算域分类"
        " | 任务=" + 任务头->获取主键()
        + " | 需求=" + 来源需求->获取主键()
        + " | 域=" + 私有_任务结算域文本_线程侧(结算域判定.域)
        + " | 原因=" + 结算域判定.原因
        + " | 完成度百万分比=" + std::to_string(消息完成度百万分比)
        + " | actual状态=" + (来源正式结算证据.actual状态
            ? 来源正式结算证据.actual状态->获取主键()
            : std::string("缺"))
        + " | " + 私有_动作验证摘要日志文本_线程侧(结果消息.动作验证报告摘要));
    if (结算域判定.域 != 枚举_任务结算域_线程侧::普通价值) {
        (void)私有_处理非核心结算闭账_任务管理新链(
            自我对象,
            任务头,
            来源需求,
            结算域判定.域,
            来源正式结算证据,
            来源任务动态,
            now);
        return;
    }

    auto 自身结算快照 = 私有_处理任务满足反馈_线程侧(
        自我对象,
        任务头,
        结果消息.任务价值反馈.本次安全满足量,
        结果消息.任务价值反馈.本次服务满足量,
        安全累计比例_百万分比,
        服务累计比例_百万分比,
        now,
        结果消息.任务价值反馈.反馈事件主键,
        任务域已完成 || !私有_存在活动直接子需求_任务管理新链(来源需求),
        来源任务动态,
        &结果消息.服务对象状态变化集,
        来源需求,
        &来源正式结算证据,
        &结果消息.动作验证报告摘要,
        true);

    私有_唤醒派生需求来源任务_任务管理新链(
        自我对象,
        来源需求,
        now,
        自身结算快照.任务完成动作动态
            ? 自身结算快照.任务完成动作动态
            : 来源正式结算证据.任务完成动作动态);

    (void)私有_处理共享任务挂接需求满足反馈_线程侧(
        自我对象,
        任务头,
        来源需求,
        结果消息.任务价值反馈.本次安全满足量,
        结果消息.任务价值反馈.本次服务满足量,
        安全累计比例_百万分比,
        服务累计比例_百万分比,
        任务域已完成,
        now,
        结果消息.任务价值反馈.反馈事件主键,
        来源任务动态,
        &结果消息.服务对象状态变化集,
        &结果消息.动作验证报告摘要);

    if (自身结算快照.已生成) {
        (void)私有_处理横向任务满足反馈_线程侧(
            自我对象,
            任务头,
            来源需求,
            来源正式结算证据,
            安全累计比例_百万分比,
            服务累计比例_百万分比,
            now,
            结果消息.任务价值反馈.反馈事件主键,
            来源任务动态,
            &结果消息.服务对象状态变化集,
            &结果消息.动作验证报告摘要);
    }
}

// 功能：解析输入文本、消息、场景或运行包。
方法节点* 私有_按主键解析方法节点_任务管理新链(
    自我类& 自我对象,
    const std::string& 主键) noexcept
{
    if (主键.empty()) {
        return nullptr;
    }
    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 方法根节点 = 自我存在
        ? reinterpret_cast<方法节点*>(世界树.存在().获取方法根节点(自我存在))
        : nullptr;
    if (!方法根节点) {
        return nullptr;
    }
    for (auto* 当前 = reinterpret_cast<方法节点*>(方法根节点->链下);
         当前 && 当前 != 方法根节点;
         当前 = reinterpret_cast<方法节点*>(当前->链下)) {
        if (当前->获取主键() == 主键) {
            return 当前;
        }
    }
    return nullptr;
}

// 功能：解析输入文本、消息、场景或运行包。
方法节点* 私有_按方法虚拟存在解析方法节点_任务管理新链(
    自我类& 自我对象,
    const 存在节点类* 方法虚拟存在,
    const std::string& 方法虚拟存在主键) noexcept
{
    if (!方法虚拟存在 && 方法虚拟存在主键.empty()) {
        return nullptr;
    }
    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 方法根节点 = 自我存在
        ? reinterpret_cast<方法节点*>(世界树.存在().获取方法根节点(自我存在))
        : nullptr;
    if (!方法根节点) {
        return nullptr;
    }
    for (auto* 当前 = reinterpret_cast<方法节点*>(方法根节点->链下);
         当前 && 当前 != 方法根节点;
         当前 = reinterpret_cast<方法节点*>(当前->链下)) {
        const auto* 首节点信息 = 当前 ? 当前->主信息.取首节点信息() : nullptr;
        if (!首节点信息) {
            continue;
        }
        const auto& 引用 = 首节点信息->方法虚拟存在;
        if ((方法虚拟存在 && 引用.指针 == 方法虚拟存在)
            || (!方法虚拟存在主键.empty() && 引用.主键 == 方法虚拟存在主键)) {
            return 当前;
        }
    }
    return nullptr;
}

// 功能：解析输入文本、消息、场景或运行包。
存在节点类* 私有_解析存在引用_任务语义(
    const 可解析引用<存在节点类>& 引用) noexcept
{
    if (引用.指针) {
        return 引用.指针;
    }
    if (引用.主键.empty()) {
        return nullptr;
    }
    auto* 基础节点 = 世界树.基础信息().查找主键(引用.主键);
    return dynamic_cast<存在节点类*>(基础节点);
}

// 功能：解析输入文本、消息、场景或运行包。
场景节点类* 私有_解析场景引用_任务语义(
    const 可解析引用<场景节点类>& 引用) noexcept
{
    if (引用.指针) {
        return 引用.指针;
    }
    if (引用.主键.empty()) {
        return nullptr;
    }
    auto* 基础节点 = 世界树.基础信息().查找主键(引用.主键);
    return dynamic_cast<场景节点类*>(基础节点);
}

// 功能：服务所在模块的内部辅助流程。
存在节点类* 私有_取任务虚拟存在_任务管理新链(
    const 任务节点* 任务头) noexcept
{
    return 任务头
        ? reinterpret_cast<存在节点类*>(任务头->主信息.任务虚拟存在.指针)
        : nullptr;
}

// 功能：解析输入文本、消息、场景或运行包。
存在节点类* 私有_按任务主键解析任务虚拟存在_任务管理新链(
    自我类& 自我对象,
    const std::string& 任务主键,
    时间戳 now) noexcept
{
    (void)自我对象;
    (void)now;
    auto* 任务头 = 私有_归一到任务头结点(私有_按主键解析任务节点(任务主键));
    if (!任务头) {
        return nullptr;
    }
    return 私有_取任务虚拟存在_任务管理新链(任务头);
}

任务节点* 私有_提交任务发起请求到任务管理界面线程_线程侧(
    自我类& 自我对象,
    需求节点* 需求节点,
    时间戳 now,
    bool 允许派发工作线程 = false,
    任务管理线程协议::结构_任务界面承接结果* 输出 = nullptr) noexcept
{
    if (!需求节点) {
        return nullptr;
    }

    if (auto* 既有同方法学习任务 = 私有_查找同方法活跃学习任务_线程侧(自我对象, 需求节点)) {
        const auto& 来源方法主键 =
            需求类::读取派生来源方法主键_兼容(需求节点->主信息);
        项目运行日志(
            "自我线程/任务化过滤同方法活跃学习任务"
            " | 当前需求=" + 需求节点->获取主键()
            + " | 来源方法=" + 来源方法主键
            + " | 学习缺口去重签名="
            + 私有_学习任务去重签名文本_线程侧(
                私有_构造学习任务去重签名_线程侧(
                    自我对象,
                    需求节点,
                    来源方法主键))
            + " | 既有任务=" + 既有同方法学习任务->获取主键());
        return nullptr;
    }

    任务管理线程协议::结构_任务治理请求 请求{};
    请求.请求类型 = 任务管理线程协议::枚举_任务管理请求类型::发起任务;
    请求.任务信息节点 = nullptr;
    请求.来源需求 = reinterpret_cast<需求节点类*>(需求节点);
    请求.发起存在 = 私有_解析存在引用_任务语义(需求节点->主信息.需求主体);
    请求.作用对象 = 私有_解析存在引用_任务语义(需求节点->主信息.被需求存在);
    请求.所属场景 = 私有_解析场景引用_任务语义(需求节点->主信息.需求场景);
    请求.当前时间 = now;
    请求.允许创建任务信息节点 = true;
    请求.允许创建任务虚拟存在 = true;
    请求.允许初始化任务语义 = true;
    请求.允许派发工作线程 = 允许派发工作线程;
    请求.允许复用等待任务 = true;
    请求.幂等键 = "发起任务|需求=" + 需求节点->获取主键();
    请求.请求摘要 = "自我线程任务发起意图";

    任务管理线程协议::结构_任务界面承接结果 局部输出{};
    auto* 有效输出 = 输出 ? 输出 : &局部输出;
    const bool 已承接 = 任务管理界面线程::提交任务治理请求(
        自我对象,
        请求,
        有效输出);
    if (!已承接) {
        return nullptr;
    }
    std::vector<结构_任务管理上行消息> 上行消息集{};
    if (任务管理界面线程::提取任务管理上行消息(&上行消息集)) {
        有效输出->上行消息集 = 上行消息集;
        for (const auto& 上行消息 : 上行消息集) {
            (void)上报任务管理上行消息(上行消息);
        }
    }
    return reinterpret_cast<任务节点*>(有效输出->任务信息节点);
}

// 功能：创建并返回或登记对应对象。
任务节点* 私有_按需求创建任务头_任务管理统一挂接(
    自我类& 自我对象,
    需求节点* 需求节点,
    时间戳 now) noexcept
{
    // 兼容旧调用名：自我线程不再创建任务头，只提交任务发起意图。
    return 私有_提交任务发起请求到任务管理界面线程_线程侧(
        自我对象,
        需求节点,
        now,
        false,
        nullptr);
}

// 功能：创建并返回或登记对应对象。
任务节点* 私有_按需求创建任务头_任务管理新链(
    自我类& 自我对象,
    需求节点* 需求节点,
    时间戳 now) noexcept
{
    return 私有_按需求创建任务头_任务管理统一挂接(
        自我对象,
        需求节点,
        now);
}

// 功能：提交事实、动态、任务状态或运行回执。
std::size_t 私有_提交活动需求任务化意图_线程侧(
    自我类& 自我对象,
    const std::vector<自我线程类::结构_需求列表项>& 服务优先需求列表,
    const std::vector<自我线程类::结构_需求列表项>& 安全优先需求列表,
    时间戳 now) noexcept
{
    std::unordered_set<需求节点*> 已检查需求{};
    std::unordered_map<std::string, std::size_t> 方法状态拒绝原因计数{};
    std::vector<std::string> 方法状态拒绝样本{};
    std::size_t 已提交数量 = 0;
    std::size_t 方法状态扫描数 = 0;
    std::size_t 方法状态可任务化数 = 0;
    std::size_t 方法状态已有任务数 = 0;
    std::size_t 方法状态已提交数 = 0;

    const auto 扫描列表 = [&](const std::vector<自我线程类::结构_需求列表项>& 需求列表) {
        for (const auto& 列表项 : 需求列表) {
            auto* 需求节点 = 私有_从需求列表项解析需求节点(列表项);
            if (!需求节点 || !已检查需求.insert(需求节点).second) {
                continue;
            }

            const bool 是方法状态目标 = 私有_目标特征类型命中任一_线程侧(
                需求类::读取需求目标特征类型(需求节点),
                { "方法状态" });
            if (是方法状态目标) {
                ++方法状态扫描数;
            }

            std::string 拒绝原因{};
            if (!私有_需求可提交活动任务化意图_线程侧(需求节点, &拒绝原因)) {
                if (是方法状态目标) {
                    ++方法状态拒绝原因计数[拒绝原因];
                    if (方法状态拒绝样本.size() < 6) {
                        方法状态拒绝样本.push_back(
                            需求节点->获取主键()
                            + ":" + (拒绝原因.empty() ? std::string("未知") : 拒绝原因));
                    }
                }
                continue;
            }
            if (是方法状态目标) {
                ++方法状态可任务化数;
            }

            if (auto* 已有任务头 = 私有_解析需求相关任务头_任务管理新链(需求节点)) {
                // 任务列表里已有可用任务头时，只把它提升为该需求当前权威承接壳；
                // 不重复发起任务，避免同一需求产生多条并行任务链。
                私有_登记需求相关任务_任务管理新链(需求节点, 已有任务头);
                if (是方法状态目标) {
                    ++方法状态已有任务数;
                }
                continue;
            }

            if (需求节点->主信息.对应任务.有效()) {
                任务节点类* 已确认任务节点 = nullptr;
                std::string 关联任务确认说明{};
                const auto& 对应任务主键 = 需求节点->主信息.对应任务.主键;
                if (!对应任务主键.empty()
                    && 任务管理界面线程::确认需求已有关联任务可承接(
                        自我对象,
                        reinterpret_cast<需求节点类*>(需求节点),
                        对应任务主键,
                        now,
                        &已确认任务节点,
                        &关联任务确认说明)
                    && 已确认任务节点) {
                    auto* 已确认任务头 = reinterpret_cast<任务节点*>(已确认任务节点);
                    私有_登记需求相关任务_任务管理新链(需求节点, 已确认任务头);
                    项目运行日志(
                        "自我线程/活动需求任务化已确认关联任务引用"
                        " | 需求=" + 需求节点->获取主键()
                        + " | 对应任务主键=" + 对应任务主键
                        + " | 原因=" + (关联任务确认说明.empty()
                            ? std::string("任务管理侧确认可承接")
                            : 关联任务确认说明)
                        + " | 发起任务=0");
                    if (是方法状态目标) {
                        ++方法状态已有任务数;
                    }
                    continue;
                }
                项目运行警告日志(
                    "自我线程/活动需求任务化忽略不可解析旧任务引用"
                    " | 需求=" + 需求节点->获取主键()
                    + " | 对应任务主键=" + 对应任务主键
                    + " | 确认结果=" + (关联任务确认说明.empty()
                        ? std::string("未确认")
                        : 关联任务确认说明));
            }

            auto* 已发起任务头 = 私有_提交任务发起请求到任务管理界面线程_线程侧(
                自我对象,
                需求节点,
                now,
                false,
                nullptr);
            if (已发起任务头) {
                ++已提交数量;
                if (是方法状态目标) {
                    ++方法状态已提交数;
                }
                if (需求节点->主信息.安全权重 == 0 && 需求节点->主信息.服务权重 == 0) {
                    项目运行日志(
                        "自我线程/活动需求任务化零权重需求承接"
                        " | 需求=" + 需求节点->获取主键()
                        + " | 目标特征=" + 私有_需求类型标题(需求类::读取需求目标特征类型(需求节点))
                        + " | 说明=安全/服务权重只参与排序和优先级，不作为任务化准入闸门");
                }
            }
        }
    };

    扫描列表(服务优先需求列表);
    扫描列表(安全优先需求列表);
    if (方法状态扫描数 > 0 || !方法状态拒绝原因计数.empty()) {
        std::ostringstream 输出;
        输出 << "自我线程/活动需求任务化方法状态扫描诊断"
            << " | 扫描=" << 方法状态扫描数
            << " | 可任务化=" << 方法状态可任务化数
            << " | 已有任务=" << 方法状态已有任务数
            << " | 已提交=" << 方法状态已提交数;
        for (const auto& [原因, 数量] : 方法状态拒绝原因计数) {
            输出 << " | 拒绝_" << (原因.empty() ? std::string("未知") : 原因)
                << "=" << 数量;
        }
        if (!方法状态拒绝样本.empty()) {
            输出 << " | 样本=";
            for (std::size_t i = 0; i < 方法状态拒绝样本.size(); ++i) {
                if (i > 0) {
                    输出 << ",";
                }
                输出 << 方法状态拒绝样本[i];
            }
        }
        项目运行日志(输出.str());
    }
    if (已提交数量 > 0) {
        std::ostringstream 输出;
        输出 << "自我线程/活动需求任务化意图"
            << " | 已提交=" << 已提交数量;
        项目运行日志(输出.str());
    }
    return 已提交数量;
}

// 功能：确保目标结构、状态或前置条件存在并可用。
void 私有_刷新需求列表并确保需求相关任务_任务管理新链(
    自我类& 自我对象,
    std::vector<自我线程类::结构_需求列表项>* 服务优先需求列表,
    std::vector<自我线程类::结构_需求列表项>* 安全优先需求列表,
    时间戳 now)
{
    (void)now;
    auto 服务列表 = 私有_从需求树构建需求列表(自我对象, 枚举_需求列表排序主轴::服务优先);
    auto 安全列表 = 私有_从需求树构建需求列表(自我对象, 枚举_需求列表排序主轴::安全优先);

    if (服务优先需求列表) {
        *服务优先需求列表 = std::move(服务列表);
    }
    if (安全优先需求列表) {
        *安全优先需求列表 = std::move(安全列表);
    }
}

// 功能：提交事实、动态、任务状态或运行回执。
bool 私有_提交任务到任务管理界面线程_任务管理新链(
    自我类& 自我对象,
    任务节点* 当前主任务,
    需求节点* 当前主需求,
    时间戳 当前时间,
    任务管理线程协议::结构_任务界面承接结果* 输出) noexcept
{
    if (!当前主任务) {
        return false;
    }

    auto* 任务来源需求 = 私有_任务来源需求_线程侧(当前主任务);
    if (鱼巢_不允许空指(任务来源需求, "任务派发逻辑错误：任务缺少自身对应需求，拒绝使用当前主需求兜底。")) {
        std::ostringstream 输出;
        输出 << "任务派发逻辑错误：任务缺少自身对应需求，拒绝使用当前主需求兜底。"
            << " | 任务=" << 当前主任务->获取主键()
            << " | 当前主需求=" << (当前主需求 ? 当前主需求->获取主键() : std::string("空"));
#if !鱼巢_开关_启用不允许空指诊断
        项目运行日志(输出.str());
        项目弹窗错误提示("鱼巢 - 任务派发逻辑错误", 输出.str());
#else
        项目运行错误日志(输出.str());
#endif
        return false;
    }
    {
        auto* 目标状态 = 私有_从状态引用解析状态节点(任务来源需求->主信息.需求状态);
        const auto* 目标特征 = 私有_状态节点特征类型_线程侧(目标状态);
        std::ostringstream 输出;
        输出 << "自我线程/任务派发目标"
            << " | 任务=" << 当前主任务->获取主键()
            << " | 对应需求=" << 任务来源需求->获取主键()
            << " | 需求目标特征=" << (目标特征 ? 目标特征->获取主键() : std::string("空"))
            << " | 需求目标状态=" << (目标状态 ? 目标状态->获取主键() : std::string("空"))
            << " | 当前主需求=" << (当前主需求 ? 当前主需求->获取主键() : std::string("空"));
        项目运行日志(输出.str());
    }

    任务管理线程协议::结构_任务治理请求 请求{};
    请求.请求类型 = 任务管理线程协议::枚举_任务管理请求类型::调度任务;
    请求.任务信息节点 = reinterpret_cast<任务节点类*>(当前主任务);
    请求.来源需求 = reinterpret_cast<需求节点类*>(任务来源需求);
    请求.发起存在 = 私有_解析存在引用_任务语义(任务来源需求->主信息.需求主体);
    请求.作用对象 = 私有_解析存在引用_任务语义(任务来源需求->主信息.被需求存在);
    请求.所属场景 = 私有_解析场景引用_任务语义(任务来源需求->主信息.需求场景);
    请求.当前时间 = 当前时间;
    请求.允许创建任务虚拟存在 = true;
    请求.允许初始化任务语义 = true;
    请求.允许派发工作线程 = true;
    请求.允许复用等待任务 = true;
    // 调度幂等键由任务管理界面线程按任务状态 / 阶段 / 运行版本生成。
    // 自我线程不能写旧式固定键，否则“等待中 -> 待重筹办”后会复用旧等待结果，父任务无法重新筹办。
    请求.请求摘要 = "自我线程主派发提交任务管理界面线程";

    任务管理线程协议::结构_任务界面承接结果 局部输出{};
    auto* 有效输出 = 输出 ? 输出 : &局部输出;
    const bool 已承接 = 任务管理界面线程::提交任务治理请求(
        自我对象,
        请求,
        有效输出);

    std::vector<结构_任务管理上行消息> 上行消息集{};
    if (任务管理界面线程::提取任务管理上行消息(&上行消息集)) {
        有效输出->上行消息集 = 上行消息集;
        for (const auto& 上行消息 : 上行消息集) {
            (void)上报任务管理上行消息(上行消息);
        }
    }
    return 已承接;
}

// 功能：更新已有对象、状态、索引或缓存。
std::size_t 私有_观察事实更新后触发来源需求重筹办_线程侧(
    const 结构_任务管理观察事实承接请求& 请求,
    const 结构_外设观察报告队列项* 报告,
    const bool 承接成功,
    const bool 报告可回查,
    时间戳 now) noexcept
{
    const auto 报告ID = 请求.报告ID != 0
        ? 请求.报告ID
        : (报告 ? 报告->报告ID : 0);
    if (!承接成功 || !报告可回查) {
        项目运行日志(
            std::string("自我线程/观察事实更新来源需求唤醒跳过")
            + " | 原因="
            + (!承接成功 ? "观察事实承接未成功" : "报告不可回查")
            + " | 报告ID=" + std::to_string(报告ID)
            + " | 等待项ID=" + std::to_string(请求.等待项ID)
            + " | 来源需求=" + (请求.来源需求ID.empty() ? std::string("空") : 请求.来源需求ID));
        return 0;
    }
    if (请求.来源需求ID.empty()) {
        项目运行日志(
            "自我线程/观察事实更新来源需求唤醒跳过"
            " | 原因=观察承接请求缺少来源需求ID"
            " | 报告ID=" + std::to_string(报告ID)
            + " | 等待项ID=" + std::to_string(请求.等待项ID));
        return 0;
    }

    auto* 来源需求 = 私有_按主键解析需求节点(请求.来源需求ID);
    if (!来源需求) {
        项目运行日志(
            "自我线程/观察事实更新来源需求唤醒跳过"
            " | 原因=来源需求不在当前需求树"
            " | 来源需求=" + 请求.来源需求ID
            + " | 报告ID=" + std::to_string(报告ID)
            + " | 等待项ID=" + std::to_string(请求.等待项ID));
        return 0;
    }

    auto* 安全根需求 = 自我.获取安全根需求();
    if (来源需求 == 安全根需求) {
        项目运行日志(
            "自我线程/观察事实更新来源需求唤醒跳过"
            " | 原因=来源需求就是安全根需求，由安全根路径处理"
            " | 来源需求=" + 来源需求->获取主键()
            + " | 报告ID=" + std::to_string(报告ID)
            + " | 等待项ID=" + std::to_string(请求.等待项ID));
        return 0;
    }

    std::ostringstream 命中日志;
    命中日志 << "需求裁决/观察事实更新命中来源需求"
        << " | 命中=是"
        << " | 来源需求=" << 来源需求->获取主键()
        << " | 报告ID=" << 报告ID
        << " | 等待项ID=" << 请求.等待项ID
        << " | 来源外设=" << 请求.来源外设
        << " | 直接生成子需求=否"
        << " | 直接写需求满足=否"
        << " | 仅唤醒等待任务=是";
    项目运行日志(命中日志.str());

    auto 任务集 = 私有_收集需求承接任务头_线程侧(来源需求);
    if (任务集.empty()) {
        项目运行日志(
            "自我线程/观察事实更新来源需求唤醒跳过"
            " | 原因=来源需求没有承接任务"
            " | 来源需求=" + 来源需求->获取主键()
            + " | 报告ID=" + std::to_string(报告ID)
            + " | 等待项ID=" + std::to_string(请求.等待项ID));
        return 0;
    }

    std::size_t 已标记重筹办 = 0;
    std::size_t 已提交治理 = 0;
    std::size_t 已派发筹办 = 0;
    for (auto* 任务 : 任务集) {
        if (!任务) {
            continue;
        }
        const auto 原状态 = 任务类::读取任务状态(任务, 枚举_任务状态::未定义);
        任务管理线程协议::结构_观察事实更新任务唤醒通知 通知{};
        通知.任务信息节点 = reinterpret_cast<任务节点类*>(任务);
        通知.来源需求 = reinterpret_cast<需求节点类*>(来源需求);
        通知.报告ID = 报告ID;
        通知.等待项ID = 请求.等待项ID;
        通知.安全根路径 = false;
        通知.当前时间 = now;
        通知.事件摘要 = "观察事实更新触发来源需求承接任务唤醒";
        任务管理线程协议::结构_任务状态推进结果 推进结果{};
        const bool 状态已就位 =
            任务管理界面线程::提交观察事实更新任务唤醒通知(通知, &推进结果);

        std::ostringstream 标记日志;
        标记日志 << "自我线程/来源需求观察事实唤醒通知结果"
            << " | 来源需求=" << 来源需求->获取主键()
            << " | 任务=" << 任务->获取主键()
            << " | 原状态=" << static_cast<int>(原状态)
            << " | 当前状态=" << static_cast<int>(任务类::读取任务状态(任务, 枚举_任务状态::未定义))
            << " | 界面裁决可重筹办=" << (状态已就位 ? "是" : "否")
            << " | 报告ID=" << 报告ID
            << " | 等待项ID=" << 请求.等待项ID;
        项目运行日志(标记日志.str());
        if (!状态已就位) {
            continue;
        }
        ++已标记重筹办;

        任务管理线程协议::结构_任务治理请求 治理请求{};
        治理请求.请求类型 = 任务管理线程协议::枚举_任务管理请求类型::重筹办任务;
        治理请求.任务信息节点 = reinterpret_cast<任务节点类*>(任务);
        治理请求.来源需求 = reinterpret_cast<需求节点类*>(来源需求);
        治理请求.发起存在 = 私有_解析存在引用_任务语义(来源需求->主信息.需求主体);
        治理请求.作用对象 = 私有_解析存在引用_任务语义(来源需求->主信息.被需求存在);
        治理请求.所属场景 = 私有_解析场景引用_任务语义(来源需求->主信息.需求场景);
        治理请求.当前时间 = now;
        治理请求.允许创建任务虚拟存在 = true;
        治理请求.允许初始化任务语义 = true;
        治理请求.允许派发工作线程 = false;
        治理请求.允许复用等待任务 = true;
        治理请求.幂等键 =
            "观察事实更新来源需求重筹办|来源需求="
            + 来源需求->获取主键()
            + "|任务=" + 任务->获取主键();
        治理请求.请求摘要 = "观察事实更新触发来源需求重筹办";

        任务管理线程协议::结构_任务界面承接结果 承接{};
        const bool 已承接 = 任务管理界面线程::提交任务治理请求(
            自我,
            治理请求,
            &承接);
        std::vector<结构_任务管理上行消息> 上行消息集{};
        if (任务管理界面线程::提取任务管理上行消息(&上行消息集)) {
            承接.上行消息集 = 上行消息集;
            for (const auto& 上行消息 : 上行消息集) {
                (void)上报任务管理上行消息(上行消息);
            }
        }
        if (已承接) {
            ++已提交治理;
        }
        if (承接.已派发工作线程) {
            ++已派发筹办;
        }
        std::ostringstream 治理日志;
        治理日志 << "任务管理领取来源需求重筹办"
            << " | 来源=观察事实更新"
            << " | 来源需求=" << 来源需求->获取主键()
            << " | 任务=" << 任务->获取主键()
            << " | 报告ID=" << 报告ID
            << " | 等待项ID=" << 请求.等待项ID
            << " | 已承接=" << (已承接 ? "是" : "否")
            << " | 已派发工作线程=" << (承接.已派发工作线程 ? "是" : "否")
            << " | 同步派发=否"
            << " | 后续巡检消费=是"
            << " | 工作项ID=" << 承接.工作项ID
            << " | 请求状态=" << static_cast<int>(承接.请求状态)
            << " | 说明=" << 承接.说明;
        项目运行日志(治理日志.str());
    }

    std::ostringstream 汇总;
    汇总 << "自我线程/观察事实更新触发来源需求重筹办汇总"
        << " | 来源需求=" << 来源需求->获取主键()
        << " | 报告ID=" << 报告ID
        << " | 等待项ID=" << 请求.等待项ID
        << " | 候选任务数=" << 任务集.size()
        << " | 已标记重筹办=" << 已标记重筹办
        << " | 已提交治理=" << 已提交治理
        << " | 已派发筹办=" << 已派发筹办;
    项目运行日志(汇总.str());
    return 已提交治理;
}

// 功能：更新已有对象、状态、索引或缓存。
std::size_t 私有_观察事实更新后刷新来源需求材料子需求_线程侧(
    const 结构_任务管理观察事实承接请求& 请求,
    const 结构_外设观察报告队列项* 报告,
    const bool 承接成功,
    const bool 报告可回查,
    时间戳 now) noexcept
{
    const auto 报告ID = 请求.报告ID != 0
        ? 请求.报告ID
        : (报告 ? 报告->报告ID : 0);
    if (!承接成功
        || !报告可回查
        || !报告
        || 请求.来源需求ID.empty()) {
        return 0;
    }

    auto* 来源需求 = 私有_按主键解析需求节点(请求.来源需求ID);
    if (!来源需求 || !来源需求->子) {
        return 0;
    }

    std::vector<需求节点*> 待刷新{};
    {
        std::lock_guard<std::recursive_mutex> 借用锁{ 需求类::借用需求树全局互斥() };
        auto* 首子 = reinterpret_cast<需求节点*>(来源需求->子);
        auto* 当前 = 首子;
        std::size_t 保护计数 = 0;
        do {
            if (当前
                && 当前->主信息.需求有效截止 == 0
                && 当前->主信息.是否阻塞父任务执行
                && !私有_需求状态已满足_任务管理新链(当前)
                && 私有_目标特征类型命中任一_线程侧(
                    需求类::读取需求目标特征类型(当前),
                    { "外设观察材料可回查状态" })) {
                待刷新.push_back(当前);
            }
            当前 = 当前 ? reinterpret_cast<需求节点*>(当前->下) : nullptr;
            ++保护计数;
        } while (当前 && 当前 != 首子 && 保护计数 < 2048);
    }

    if (待刷新.empty()) {
        return 0;
    }

    auto* 需求树根 = 来源需求;
    std::size_t 追根保护计数 = 0;
    while (需求树根 && 需求树根->父 && 追根保护计数 < 2048) {
        需求树根 = reinterpret_cast<需求节点*>(需求树根->父);
        ++追根保护计数;
    }
    if (!需求树根) {
        return 0;
    }

    需求类 需求服务{};
    std::size_t 已刷新 = 0;
    for (auto* 子需求 : 待刷新) {
        if (!子需求 || 子需求->主信息.需求有效截止 != 0) {
            continue;
        }

        auto* 目标状态 = 私有_从状态引用解析状态节点(子需求->主信息.需求状态);
        I64 目标值 = 0;
        if (!目标状态
            || !私有_读取状态I64值_线程侧(目标状态, 目标值)
            || 目标值 != 1) {
            项目运行警告日志(
                "自我线程/观察事实更新材料子需求刷新跳过"
                " | 原因=目标状态不是可回查"
                " | 来源需求=" + 来源需求->获取主键()
                + " | 子需求=" + (子需求 ? 子需求->获取主键() : std::string("空"))
                + " | 报告ID=" + std::to_string(报告ID));
            continue;
        }

        结构_需求树更新指令 指令{};
        指令.指令类型 = 枚举_需求树更新指令类型::更新需求;
        指令.父需求指针 = reinterpret_cast<std::uintptr_t>(来源需求);
        指令.父需求主键 = 来源需求->获取主键();
        指令.目标需求指针 = reinterpret_cast<std::uintptr_t>(子需求);
        指令.目标需求主键 = 子需求->获取主键();
        指令.当前状态指针 = reinterpret_cast<std::uintptr_t>(目标状态);
        指令.当前状态主键 = 目标状态->获取主键();
        指令.需求状态指针 = reinterpret_cast<std::uintptr_t>(目标状态);
        指令.需求状态主键 = 目标状态->获取主键();
        指令.满足关系 = 子需求->主信息.满足关系 != 0
            ? 子需求->主信息.满足关系
            : 关系_等于;
        指令.目标特征类型缓存 = 需求类::读取需求目标特征类型(子需求);
        指令.记录观测统计 = true;
        指令.统计观测时间 = now;

        auto* 结果 = 需求服务.执行更新指令(需求树根, 指令);
        if (!结果) {
            项目运行错误日志(
                "自我线程/观察事实更新材料子需求当前状态刷新失败"
                " | 来源需求=" + 来源需求->获取主键()
                + " | 子需求=" + 子需求->获取主键()
                + " | 报告ID=" + std::to_string(报告ID));
            continue;
        }

        ++已刷新;
        std::ostringstream 日志;
        日志 << "自我线程/观察事实更新材料子需求当前状态刷新"
            << " | 来源需求=" << 来源需求->获取主键()
            << " | 子需求=" << 子需求->获取主键()
            << " | 目标特征="
            << 私有_需求类型标题(需求类::读取需求目标特征类型(子需求))
            << " | 报告ID=" << 报告ID
            << " | 当前状态=" << 目标状态->获取主键()
            << " | 目标状态=" << 目标状态->获取主键()
            << " | 来源=L1正式报告可回查"
            << " | 只刷新子需求当前状态=1"
            << " | 不截止需求=1"
            << " | 不直接写父需求满足=1"
            << " | 不写世界真值=1";
        项目运行日志(日志.str());
    }

    if (已刷新 > 0) {
        (void)需求服务.刷新子需求权重(来源需求);
        需求类::刷新需求及祖先结构角色(来源需求);
    }
    return 已刷新;
}

// 功能：更新已有对象、状态、索引或缓存。
std::size_t 私有_观察事实更新后触发安全根需求重筹办_线程侧(
    const 结构_任务管理观察事实承接请求& 请求,
    const 结构_外设观察报告队列项* 报告,
    const bool 承接成功,
    const bool 报告可回查,
    时间戳 now) noexcept
{
    const auto 报告ID = 请求.报告ID != 0
        ? 请求.报告ID
        : (报告 ? 报告->报告ID : 0);
    std::ostringstream 事件日志;
    事件日志 << "自我线程/观察事实更新事件发布"
        << " | 事件类型=外设报告承接完成"
        << " | 报告ID=" << 报告ID
        << " | 等待项ID=" << 请求.等待项ID
        << " | 来源需求=" << (请求.来源需求ID.empty() ? std::string("空") : 请求.来源需求ID)
        << " | 来源外设=" << 请求.来源外设
        << " | 承接成功=" << (承接成功 ? "是" : "否")
        << " | 报告可回查=" << (报告可回查 ? "是" : "否")
        << " | 短期材料页ID=" << (报告ID == 0 ? std::string("空") : ("D455材料页#报告" + std::to_string(报告ID)))
        << " | 来源动作动态=任务管理观察事实承接请求"
        << " | 只发布事实变化事件=是";
    if (报告) {
        if (!报告->原始观察帧句柄.empty()) {
            事件日志 << " | 原始观察帧句柄=" << 报告->原始观察帧句柄;
        }
        if (!报告->深度帧句柄.empty()) {
            事件日志 << " | 深度帧句柄=" << 报告->深度帧句柄;
        }
        if (!报告->彩色帧句柄.empty()) {
            事件日志 << " | 彩色帧句柄=" << 报告->彩色帧句柄;
        }
        if (!报告->对齐帧句柄.empty()) {
            事件日志 << " | 对齐帧句柄=" << 报告->对齐帧句柄;
        }
        if (!报告->空间候选队列引用.empty()) {
            事件日志 << " | 空间候选句柄=" << 报告->空间候选队列引用;
        }
        if (!报告->像素归属账本引用.empty()) {
            事件日志 << " | 像素归属账本句柄=" << 报告->像素归属账本引用;
        }
    }
    项目运行日志(事件日志.str());

    auto* 安全根需求 = 自我.获取安全根需求();
    std::ostringstream 命中日志;
    命中日志 << "需求裁决/观察事实更新命中安全根需求"
        << " | 命中=" << ((承接成功 && 报告可回查 && 安全根需求) ? "是" : "否")
        << " | 安全根需求=" << (安全根需求 ? 安全根需求->获取主键() : std::string("空"))
        << " | 报告ID=" << 报告ID
        << " | 来源需求=" << (请求.来源需求ID.empty() ? std::string("空") : 请求.来源需求ID)
        << " | 直接生成子需求=否"
        << " | 直接写风险状态=否";
    项目运行日志(命中日志.str());

    if (!承接成功 || !报告可回查 || !安全根需求) {
        项目运行日志(
            std::string("自我线程/观察事实更新唤醒跳过")
            + " | 原因="
            + (!承接成功 ? "观察事实承接未成功" : (!报告可回查 ? "报告不可回查" : "安全根需求不存在"))
            + " | 报告ID=" + std::to_string(报告ID));
        return 0;
    }

    auto 任务集 = 私有_收集需求承接任务头_线程侧(安全根需求);
    if (任务集.empty()) {
        任务管理线程协议::结构_任务界面承接结果 承接{};
        auto* 新任务 = 私有_提交任务发起请求到任务管理界面线程_线程侧(
            自我,
            安全根需求,
            now,
            true,
            &承接);
        std::ostringstream 输出;
        输出 << "自我线程/观察事实更新触发安全根需求任务发起"
            << " | 安全根需求=" << 安全根需求->获取主键()
            << " | 报告ID=" << 报告ID
            << " | 既有承接任务=0"
            << " | 已提交=" << (新任务 ? "是" : "否")
            << " | 任务=" << (新任务 ? 新任务->获取主键() : std::string("空"))
            << " | 已派发工作线程=" << (承接.已派发工作线程 ? "是" : "否")
            << " | 工作项ID=" << 承接.工作项ID
            << " | 说明=" << 承接.说明;
        项目运行日志(输出.str());
        return 新任务 ? 1 : 0;
    }

    std::size_t 已标记重筹办 = 0;
    std::size_t 已提交治理 = 0;
    std::size_t 已派发筹办 = 0;
    for (auto* 任务 : 任务集) {
        if (!任务) {
            continue;
        }
        const auto 原状态 = 任务类::读取任务状态(任务, 枚举_任务状态::未定义);
        任务管理线程协议::结构_观察事实更新任务唤醒通知 通知{};
        通知.任务信息节点 = reinterpret_cast<任务节点类*>(任务);
        通知.来源需求 = reinterpret_cast<需求节点类*>(安全根需求);
        通知.报告ID = 报告ID;
        通知.等待项ID = 请求.等待项ID;
        通知.安全根路径 = true;
        通知.当前时间 = now;
        通知.事件摘要 = "观察事实更新触发安全根需求承接任务唤醒";
        任务管理线程协议::结构_任务状态推进结果 推进结果{};
        const bool 状态已就位 =
            任务管理界面线程::提交观察事实更新任务唤醒通知(通知, &推进结果);

        std::ostringstream 标记日志;
        标记日志 << "自我线程/安全根需求观察事实唤醒通知结果"
            << " | 安全根需求=" << 安全根需求->获取主键()
            << " | 任务=" << 任务->获取主键()
            << " | 原状态=" << static_cast<int>(原状态)
            << " | 当前状态=" << static_cast<int>(任务类::读取任务状态(任务, 枚举_任务状态::未定义))
            << " | 界面裁决可重筹办=" << (状态已就位 ? "是" : "否")
            << " | 报告ID=" << 报告ID;
        项目运行日志(标记日志.str());
        if (!状态已就位) {
            continue;
        }
        ++已标记重筹办;

        任务管理线程协议::结构_任务治理请求 治理请求{};
        治理请求.请求类型 = 任务管理线程协议::枚举_任务管理请求类型::重筹办任务;
        治理请求.任务信息节点 = reinterpret_cast<任务节点类*>(任务);
        治理请求.来源需求 = reinterpret_cast<需求节点类*>(安全根需求);
        治理请求.发起存在 = 私有_解析存在引用_任务语义(安全根需求->主信息.需求主体);
        治理请求.作用对象 = 私有_解析存在引用_任务语义(安全根需求->主信息.被需求存在);
        治理请求.所属场景 = 私有_解析场景引用_任务语义(安全根需求->主信息.需求场景);
        治理请求.当前时间 = now;
        治理请求.允许创建任务虚拟存在 = true;
        治理请求.允许初始化任务语义 = true;
        治理请求.允许派发工作线程 = false;
        治理请求.允许复用等待任务 = true;
        治理请求.幂等键 =
            "观察事实更新安全根需求重筹办|安全根需求="
            + 安全根需求->获取主键()
            + "|任务=" + 任务->获取主键();
        治理请求.请求摘要 = "观察事实更新触发安全根需求重筹办";

        任务管理线程协议::结构_任务界面承接结果 承接{};
        const bool 已承接 = 任务管理界面线程::提交任务治理请求(
            自我,
            治理请求,
            &承接);
        std::vector<结构_任务管理上行消息> 上行消息集{};
        if (任务管理界面线程::提取任务管理上行消息(&上行消息集)) {
            承接.上行消息集 = 上行消息集;
            for (const auto& 上行消息 : 上行消息集) {
                (void)上报任务管理上行消息(上行消息);
            }
        }
        if (已承接) {
            ++已提交治理;
        }
        if (承接.已派发工作线程) {
            ++已派发筹办;
        }
        std::ostringstream 治理日志;
        治理日志 << "任务管理领取重筹办"
            << " | 来源=观察事实更新"
            << " | 安全根需求=" << 安全根需求->获取主键()
            << " | 任务=" << 任务->获取主键()
            << " | 报告ID=" << 报告ID
            << " | 已承接=" << (已承接 ? "是" : "否")
            << " | 已派发工作线程=" << (承接.已派发工作线程 ? "是" : "否")
            << " | 同步派发=否"
            << " | 后续巡检消费=是"
            << " | 工作项ID=" << 承接.工作项ID
            << " | 请求状态=" << static_cast<int>(承接.请求状态)
            << " | 说明=" << 承接.说明;
        项目运行日志(治理日志.str());
    }

    std::ostringstream 汇总;
    汇总 << "自我线程/观察事实更新触发安全根需求重筹办汇总"
        << " | 安全根需求=" << 安全根需求->获取主键()
        << " | 报告ID=" << 报告ID
        << " | 候选任务数=" << 任务集.size()
        << " | 已标记重筹办=" << 已标记重筹办
        << " | 已提交治理=" << 已提交治理
        << " | 已派发筹办=" << 已派发筹办;
    项目运行日志(汇总.str());
    return 已提交治理;
}

