// 功能：提交事实、动态、任务状态或运行回执。
void 私有_刷新需求列表并确保需求相关任务_任务管理提交链(
    自我类& 自我对象,
    std::vector<自我线程类::结构_需求列表项>* 服务优先需求列表,
    std::vector<自我线程类::结构_需求列表项>* 安全优先需求列表,
    时间戳 now)
{
    (void)now;
    auto 服务列表 = 私有_从需求树构建需求列表(自我对象, 枚举_需求列表排序主轴::服务优先);
    auto 安全列表 = 私有_从需求树构建需求列表(自我对象, 枚举_需求列表排序主轴::安全优先);

    if (服务优先需求列表) {
        *服务优先需求列表 = std::move(服务列表);
    }
    if (安全优先需求列表) {
        *安全优先需求列表 = std::move(安全列表);
    }
}

