struct 结构_自检报告休眠处置映射 {
    bool 仅休眠期评估 = false;
    bool 需要映射确认 = true;
    const char* 处置类型 = "待映射确认";
    const char* 休眠期候选动作 = "未授权";
};

// 功能：服务所在模块的内部辅助流程。
结构_自检报告休眠处置映射 私有_映射自检报告休眠处置(
    const I64 缺口类型值) noexcept
{
    // 与自检线程上报的缺口类型值保持松耦合：这里只做治理处置分类，
    // 不直接生成修复需求，也不执行修复动作。
    switch (缺口类型值) {
    case 1: // 方法结构
    case 3: // 方法运行账
        return { false, false, "仅报告保留", "无" };
    case 4: // 方法虚拟存在
        return { true, true, "休眠期评估", "待定义_方法虚拟存在一致性检查" };
    case 5: // 可用方法数量镜像
        return { true, false, "休眠期评估", "重扫方法可用数量镜像" };
    case 6: // 状态清理阻塞
        return { true, false, "休眠期评估", "重扫状态清理阻塞快照" };
    default:
        return {};
    }
}

// 功能：服务所在模块的内部辅助流程。
自我线程消息协议::枚举_自检候选类型 私有_归一自检候选类型(
    const 自我线程消息协议::结构_自检缺口候选消息& 候选) noexcept
{
    if (候选.候选类型 != 自我线程消息协议::枚举_自检候选类型::未定义) {
        return 候选.候选类型;
    }
    return 候选.建议生成需求
        ? 自我线程消息协议::枚举_自检候选类型::需求型
        : 自我线程消息协议::枚举_自检候选类型::报告型;
}

// 功能：服务所在模块的内部辅助流程。
std::string 私有_构造自检候选门控文本(
    const 自我线程消息协议::结构_自检缺口候选消息& 候选) noexcept
{
    std::ostringstream 输出;
    输出 << "自检候选"
        << " | 类型=" << 私有_自检候选类型文本(私有_归一自检候选类型(候选))
        << " | 建议需求=" << (候选.建议生成需求 ? "是" : "否")
        << " | 目标=" << 候选.目标主键文本
        << " | 幂等键=" << 候选.幂等键
        << " | 缺口=" << 候选.缺口类型值;
    if (候选.缺失结构类型值 != 0) {
        输出 << " | 缺失结构=" << 候选.缺失结构类型值;
    }
    if (!候选.证据摘要.empty()) {
        输出 << " | 证据=" << 候选.证据摘要;
    }
    return 输出.str();
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_自检候选原子目标完整(
    const 自我线程消息协议::结构_自检缺口候选消息& 候选,
    std::string* 错误) noexcept
{
    const bool 有主体 = 候选.原子目标主体指针 != 0
        || !候选.原子目标主体主键.empty();
    const bool 有特征 = 候选.原子目标特征类型指针 != 0
        || !候选.原子目标特征类型主键.empty();
    const bool 有最初状态 = 候选.原子最初状态指针 != 0
        || !候选.原子最初状态主键.empty();
    const bool 有当前状态 = 候选.原子当前状态指针 != 0
        || !候选.原子当前状态主键.empty();
    const bool 有目标状态 = 候选.原子目标状态指针 != 0
        || !候选.原子目标状态主键.empty();
    if (有主体 && 有特征 && 有最初状态 && 有当前状态 && 有目标状态 && 候选.原子满足关系 != 0) {
        return true;
    }

    if (错误) {
        std::ostringstream 输出;
        输出 << "原子目标不完整"
            << " | 主体=" << (有主体 ? "有" : "缺")
            << " | 特征=" << (有特征 ? "有" : "缺")
            << " | 最初状态=" << (有最初状态 ? "有" : "缺")
            << " | 当前状态=" << (有当前状态 ? "有" : "缺")
            << " | 目标状态=" << (有目标状态 ? "有" : "缺")
            << " | 满足关系=" << (候选.原子满足关系 != 0 ? "有" : "缺");
        *错误 = 输出.str();
    }
    return false;
}

// 功能：解析输入文本、消息、场景或运行包。
存在节点类* 私有_解析自检原子目标宿主(
    const std::uintptr_t 节点指针,
    const std::string& 主键) noexcept
{
    if (!主键.empty()) {
        auto* 基础节点 = 世界树.基础信息().查找主键(主键);
        return dynamic_cast<存在节点类*>(基础节点);
    }

    auto* 候选节点 = reinterpret_cast<基础信息节点类*>(节点指针);
    return dynamic_cast<存在节点类*>(候选节点);
}

