// 功能：服务所在模块的内部辅助流程。
bool 私有_服务根闭环触发事实存在_线程侧(
    const 自我类& 自我对象,
    const 需求节点* 服务根需求) noexcept
{
    (void)自我对象;
    (void)服务根需求;
    // 服务触发事实必须来自当前会话输入、人类表达、外部请求或已确认服务目标等正式入口。
    // 禁止再用服务根下已有子需求反推触发事实，否则历史残留子需求会反向点亮服务因果链。
    return false;
}

// 功能：根据当前输入生成目标数据、场景、动态或回执。
std::vector<结构_根闭环信息位_线程侧> 私有_生成根闭环信息位_线程侧(
    自我类& 自我对象,
    需求节点* 根需求,
    const 结构_抽象根特征定义_线程侧& 根定义,
    const bool 根特征有缺口)
{
    std::vector<结构_根闭环信息位_线程侧> 输出{};
    if (!根需求 || !根定义.成功()) {
        return 输出;
    }

    const bool 是服务根 =
        根定义.根特征类型 == 枚举_自我根特征类型_线程侧::服务;
    const bool 服务触发事实存在 =
        !是服务根 || 私有_服务根闭环触发事实存在_线程侧(自我对象, 根需求);
    const auto 条件集 = 私有_根闭环可刷新条件集_线程侧(
        根定义,
        服务触发事实存在);
    输出.reserve(条件集.size());

    for (std::size_t 序号 = 0; 序号 < 条件集.size(); ++序号) {
        const auto& 条件 = 条件集[序号];
        结构_根闭环信息位_线程侧 信息位{};
        信息位.根特征类型 = 条件.根特征类型;
        信息位.位置序号 = 序号 + 1;
        信息位.根定义编号 =
            std::string("006.") + 私有_根特征类型文本_线程侧(条件.根特征类型);
        信息位.闭环位置 = 条件.条件键;
        信息位.事实类型 = 私有_需求类型标题(条件.检查特征类型);
        信息位.目标语义要求 =
            信息位.事实类型 + " >= " + std::to_string(条件.目标值);
        信息位.回写目标 =
            std::string("下一轮") + 私有_根特征类型文本_线程侧(条件.根特征类型)
            + "状态判断";
        信息位.下一轮判断入口 =
            std::string("自我线程根层重判.") + 私有_根特征类型文本_线程侧(条件.根特征类型);
        信息位.服务上下文字段 = 私有_根必要条件是服务上下文字段_线程侧(条件);
        信息位.间接服务维护字段 = 私有_根必要条件是间接服务维护字段_线程侧(条件);
        信息位.服务触发事实 = 服务触发事实存在;
        信息位.目标值 = 条件.目标值;

        const bool 位置已触发 = 根特征有缺口
            && (!是服务根 || 服务触发事实存在 || 信息位.间接服务维护字段);
        if (!位置已触发) {
            信息位.闭合状态 = 枚举_根闭环闭合状态_线程侧::未触发;
            信息位.缺口类型 = 根特征有缺口 && 是服务根
                ? std::string("等待直接服务触发事实")
                : std::string("根特征无缺口");
            信息位.闭合证据 = "未挂载当前事实";
            输出.push_back(std::move(信息位));
            continue;
        }

        if (!条件.缺口目标特征类型) {
            信息位.闭合状态 = 枚举_根闭环闭合状态_线程侧::已触发且缺目标;
            信息位.缺口类型 = "缺目标语义";
            输出.push_back(std::move(信息位));
            continue;
        }

        auto* 宿主 = 私有_解析根特征必要条件宿主_线程侧(
            自我对象,
            条件.检查宿主语义,
            false);
        auto* 特征节点 = 宿主
            ? 世界树.存在().查找子特征_按类型(宿主, 条件.检查特征类型)
            : nullptr;
        I64 当前值 = 0;
        信息位.当前事实存在 = 特征节点 && 世界树.读取特征_I64(特征节点, 当前值);
        信息位.当前值 = 当前值;
        if (!信息位.当前事实存在) {
            信息位.闭合状态 = 枚举_根闭环闭合状态_线程侧::已触发但事实不足;
            信息位.缺口类型 = 宿主 ? std::string("检查事实缺失") : std::string("检查宿主缺失");
            信息位.闭合证据 = "当前事实未挂载";
            信息位.可转需求 = true;
            输出.push_back(std::move(信息位));
            continue;
        }

        if (当前值 >= 条件.目标值) {
            信息位.闭合状态 = 枚举_根闭环闭合状态_线程侧::当前轮闭合;
            信息位.缺口类型 = "无缺口";
            信息位.闭合证据 =
                "当前值=" + std::to_string(当前值)
                + " >= 目标值=" + std::to_string(条件.目标值);
            输出.push_back(std::move(信息位));
            continue;
        }

        const auto 方法ID = 私有_根必要条件目标方法ID_线程侧(条件);
        信息位.闭合状态 = 方法ID == 枚举_本能方法ID::未定义
            ? 枚举_根闭环闭合状态_线程侧::已触发且缺路径
            : 枚举_根闭环闭合状态_线程侧::已触发且缺结果事实;
        信息位.缺口类型 = 方法ID == 枚举_本能方法ID::未定义
            ? std::string("缺获取或推进路径")
            : std::string("目标状态未闭合");
        信息位.闭合证据 =
            "当前值=" + std::to_string(当前值)
            + " < 目标值=" + std::to_string(条件.目标值);
        信息位.可转需求 = true;
        输出.push_back(std::move(信息位));
    }
    return 输出;
}

// 功能：记录日志、动态、证据或运行痕迹。
void 私有_记录根闭环信息位挂载_线程侧(
    const 需求节点* 根需求,
    const std::vector<结构_根闭环信息位_线程侧>& 信息位集) noexcept
{
    if (!根需求 || 信息位集.empty()) {
        return;
    }

    std::size_t 已触发数 = 0;
    std::size_t 已闭合数 = 0;
    std::size_t 缺口候选数 = 0;
    for (const auto& 信息位 : 信息位集) {
        if (信息位.闭合状态 != 枚举_根闭环闭合状态_线程侧::未触发) {
            ++已触发数;
        }
        if (信息位.闭合状态 == 枚举_根闭环闭合状态_线程侧::当前轮闭合) {
            ++已闭合数;
        }
        if (信息位.可转需求) {
            ++缺口候选数;
        }
    }

    std::ostringstream 摘要;
    摘要 << "自我线程/根闭环信息模板生成"
        << " | 根=" << 根需求->获取主键()
        << " | 根特征=" << 私有_根特征类型文本_线程侧(信息位集.front().根特征类型)
        << " | 信息位=" << 信息位集.size()
        << " | 已触发=" << 已触发数
        << " | 当前轮闭合=" << 已闭合数
        << " | 缺口候选=" << 缺口候选数
        << " | 直接生成需求=0"
        << " | 直接创建任务=0"
        << " | 直接创建方法头=0";

    static std::mutex 记录锁;
    static std::unordered_set<std::string> 已记录;
    auto 记录若首次 = [&](const std::string& 文本) {
        std::lock_guard<std::mutex> lk{ 记录锁 };
        if (!已记录.insert(文本).second) {
            return false;
        }
        return true;
    };

    const auto 摘要文本 = 摘要.str();
    if (记录若首次(摘要文本)) {
        项目运行日志(摘要文本);
    }

    for (const auto& 信息位 : 信息位集) {
        std::ostringstream 明细;
        明细 << "自我线程/根闭环信息位事实挂载"
            << " | 根=" << 根需求->获取主键()
            << " | 根特征=" << 私有_根特征类型文本_线程侧(信息位.根特征类型)
            << " | 位置序号=" << 信息位.位置序号
            << " | 位置=" << 信息位.闭环位置
            << " | 状态=" << 私有_根闭环闭合状态文本_线程侧(信息位.闭合状态)
            << " | 事实类型=" << 信息位.事实类型
            << " | 目标语义=" << 信息位.目标语义要求
            << " | 缺口类型=" << 信息位.缺口类型
            << " | 可转需求=" << (信息位.可转需求 ? 1 : 0)
            << " | 服务上下文字段=" << (信息位.服务上下文字段 ? 1 : 0)
            << " | 间接服务维护=" << (信息位.间接服务维护字段 ? 1 : 0)
            << " | 服务触发事实=" << (信息位.服务触发事实 ? 1 : 0)
            << " | 当前事实存在=" << (信息位.当前事实存在 ? 1 : 0)
            << " | 当前值=" << 信息位.当前值
            << " | 目标值=" << 信息位.目标值
            << " | 闭合证据=" << 信息位.闭合证据
            << " | 回写目标=" << 信息位.回写目标
            << " | 下一轮判断入口=" << 信息位.下一轮判断入口
            << " | 仅挂载不入树=1";
        const auto 明细文本 = 明细.str();
        if (记录若首次(明细文本)) {
            项目运行日志(明细文本);
        }
    }
}

// 功能：按条件查找目标对象、方法或事实。
const 结构_根闭环信息位_线程侧* 私有_查找根闭环信息位_线程侧(
    const std::vector<结构_根闭环信息位_线程侧>& 信息位集,
    const 结构_根特征必要条件定义_线程侧& 条件) noexcept
{
    for (const auto& 信息位 : 信息位集) {
        if (信息位.闭环位置 == 条件.条件键) {
            return &信息位;
        }
    }
    return nullptr;
}

// 功能：记录日志、动态、证据或运行痕迹。
void 私有_记录根闭环缺口准入_线程侧(
    const 需求节点* 根需求,
    const 结构_根特征必要条件定义_线程侧& 条件,
    const 结构_根闭环信息位_线程侧* 信息位,
    const bool 通过,
    const char* 阶段) noexcept
{
    if (!根需求) {
        return;
    }

    std::ostringstream 日志;
    日志 << "自我线程/根闭环缺口入树准入"
        << " | 根=" << 根需求->获取主键()
        << " | 根特征=" << 私有_根特征类型文本_线程侧(条件.根特征类型)
        << " | 条件=" << 条件.条件键
        << " | 闭环位置=" << (信息位 ? 信息位->闭环位置 : std::string("空"))
        << " | 闭合状态=" << (信息位
            ? 私有_根闭环闭合状态文本_线程侧(信息位->闭合状态)
            : "无闭环信息位")
        << " | 缺口类型=" << (信息位 ? 信息位->缺口类型 : std::string("缺闭环位置"))
        << " | 上游来源=自我觉醒根闭环"
        << " | 有闭环位置=" << (信息位 ? 1 : 0)
        << " | 有目标语义=" << (条件.缺口目标特征类型 ? 1 : 0)
        << " | 可转需求=" << (信息位 && 信息位->可转需求 ? 1 : 0)
        << " | 通过=" << (通过 ? 1 : 0)
        << " | 阶段=" << (阶段 ? 阶段 : "未定义")
        << " | 直接创建任务=0"
        << " | 直接创建方法头=0";

    static std::mutex 记录锁;
    static std::unordered_set<std::string> 已记录;
    const auto 文本 = 日志.str();
    {
        std::lock_guard<std::mutex> lk{ 记录锁 };
        if (!已记录.insert(文本).second) {
            return;
        }
    }
    if (通过) {
        项目运行日志(文本);
    }
    else {
        项目运行警告日志(文本);
    }
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_收束根特征必要条件子需求_线程侧(
    需求节点* 根需求,
    需求节点* 子需求,
    const 结构_根特征必要条件定义_线程侧& 条件,
    const 时间戳 now) noexcept
{
    if (!根需求 || !子需求 || 子需求->主信息.需求有效截止 != 0) {
        return false;
    }

    auto* 需求树根 = 根需求;
    while (需求树根 && 需求树根->父) {
        需求树根 = reinterpret_cast<需求节点*>(需求树根->父);
    }

    结构_需求树更新指令 指令{};
    指令.指令类型 = 枚举_需求树更新指令类型::满足需求;
    指令.目标需求指针 = reinterpret_cast<std::uintptr_t>(子需求);
    指令.目标需求主键 = 子需求->获取主键();
    指令.父需求指针 = reinterpret_cast<std::uintptr_t>(根需求);
    指令.父需求主键 = 根需求->获取主键();
    指令.当前状态指针 =
        reinterpret_cast<std::uintptr_t>(子需求->主信息.被需求当前状态.指针);
    指令.当前状态主键 = 子需求->主信息.被需求当前状态.主键;
    指令.需求状态指针 =
        reinterpret_cast<std::uintptr_t>(子需求->主信息.需求状态.指针);
    指令.需求状态主键 = 子需求->主信息.需求状态.主键;
    指令.满足关系 = 子需求->主信息.满足关系 != 0
        ? 子需求->主信息.满足关系
        : 关系_等于;
    指令.使用新安全权重 = true;
    指令.使用新服务权重 = true;
    指令.新安全权重 = 0;
    指令.新服务权重 = 0;
    指令.标记已满足 = true;
    指令.使用阻塞父任务执行 = true;
    指令.阻塞父任务执行 = false;
    指令.记录观测统计 = true;
    指令.统计观测时间 = now;

    需求类 需求服务{};
    auto* 结果 = 需求服务.执行更新指令(需求树根, 指令);
    if (!结果) {
        项目运行错误日志(
            "自我线程/根特征必要条件子需求收束失败"
            " | 根=" + 根需求->获取主键()
            + " | 子=" + 子需求->获取主键()
            + " | 条件=" + 条件.条件键);
        return false;
    }

    std::ostringstream 日志;
    日志 << "自我线程/根特征必要条件子需求收束"
        << " | 根=" << 根需求->获取主键()
        << " | 子=" << 子需求->获取主键()
        << " | 条件=" << 条件.条件键
        << " | 目标特征=" << 私有_需求类型标题(条件.缺口目标特征类型);
    项目运行日志(日志.str());
    return true;
}

// 功能：删除指定对象、状态或登记项。
bool 私有_删除遗留根子需求_线程侧(
    需求节点* 根需求,
    需求节点* 子需求,
    const char* 原因,
    const 时间戳) noexcept
{
    if (!根需求 || !子需求 || 子需求->主信息.需求有效截止 != 0) {
        return false;
    }

    auto* 需求树根 = 根需求;
    while (需求树根 && 需求树根->父) {
        需求树根 = reinterpret_cast<需求节点*>(需求树根->父);
    }

    const auto 根主键 = 根需求->获取主键();
    const auto 子主键 = 子需求->获取主键();
    const auto 目标特征 = 私有_需求类型标题(
        私有_需求目标特征类型_线程侧(子需求));

    结构_需求树更新指令 指令{};
    指令.指令类型 = 枚举_需求树更新指令类型::删除需求;
    指令.目标需求指针 = reinterpret_cast<std::uintptr_t>(子需求);
    指令.目标需求主键 = 子主键;
    指令.父需求指针 = reinterpret_cast<std::uintptr_t>(根需求);
    指令.父需求主键 = 根主键;

    需求类 需求服务{};
    auto* 结果 = 需求服务.执行更新指令(需求树根, 指令);
    if (!结果) {
        项目运行错误日志(
            "自我线程/遗留根子需求删除失败"
            " | 根=" + 根主键
            + " | 子=" + 子主键
            + " | 目标特征=" + 目标特征
            + " | 原因=" + std::string(原因 ? 原因 : "空"));
        return false;
    }

    项目运行日志(
        "自我线程/遗留根子需求删除"
        " | 根=" + 根主键
        + " | 子=" + 子主键
        + " | 目标特征=" + 目标特征
        + " | 原因=" + std::string(原因 ? 原因 : "空")
        + " | 根据因果链清理=1"
        + " | 不保留虚假主动需求=1");
    return true;
}

// 功能：清理缓存、临时状态或运行资源。
std::size_t 私有_清理遗留固定服务子需求_线程侧(
    自我类& 自我对象,
    需求节点* 根需求,
    const 结构_抽象根特征定义_线程侧& 根定义,
    const 时间戳 now) noexcept
{
    if (!根需求
        || 根定义.根特征类型 != 枚举_自我根特征类型_线程侧::服务) {
        return 0;
    }

    std::size_t 遗留条件数 = 0;
    std::size_t 树上遗留子需求数 = 0;
    std::size_t 删除子需求数 = 0;
    std::vector<需求节点*> 删除候选{};
    const auto 加入删除候选 = [&](需求节点* 候选) noexcept {
        if (!候选 || 候选->主信息.需求有效截止 != 0) {
            return;
        }
        if (std::find(删除候选.begin(), 删除候选.end(), 候选) == 删除候选.end()) {
            删除候选.push_back(候选);
        }
    };
    const auto 遗留条件集 = 私有_读取根特征必要条件定义集_线程侧(
        根定义,
        true);
    for (const auto& 条件 : 遗留条件集) {
        if (!私有_根必要条件是服务上下文字段_线程侧(条件)) {
            continue;
        }
        ++遗留条件数;
        auto* 目标宿主 = 私有_解析根特征必要条件宿主_线程侧(
            自我对象,
            条件.检查宿主语义,
            false);
        auto* 旧子需求 = 目标宿主
            ? 私有_查找根特征必要条件子需求_线程侧(
                根需求,
                目标宿主,
                条件.缺口目标特征类型)
            : nullptr;
        加入删除候选(旧子需求);
    }

    if (根需求->子) {
        auto* 首子 = reinterpret_cast<需求节点*>(根需求->子);
        auto* 当前 = 首子;
        std::size_t 保护计数 = 0;
        do {
            if (当前 && 当前->主信息.需求有效截止 == 0) {
                const auto* 目标特征 =
                    私有_需求目标特征类型_线程侧(当前);
                if (私有_目标特征是服务上下文字段_线程侧(目标特征)
                    || 私有_目标特征是根层遗留学习字段_线程侧(目标特征)) {
                    ++树上遗留子需求数;
                    加入删除候选(当前);
                }
            }
            当前 = 当前 ? reinterpret_cast<需求节点*>(当前->下) : nullptr;
            ++保护计数;
        } while (当前 && 当前 != 首子 && 保护计数 < 2048);
    }

    for (auto* 候选 : 删除候选) {
        if (私有_删除遗留根子需求_线程侧(
            根需求,
            候选,
            "旧固定服务上下文或根层学习缺口",
            now)) {
            ++删除子需求数;
        }
    }

    std::ostringstream 日志;
    日志 << "自我线程/遗留固定服务需求清理"
        << " | 根=" << 根需求->获取主键()
        << " | 遗留固定服务条件=" << 遗留条件数
        << " | 树上遗留子需求=" << 树上遗留子需求数
        << " | 删除子需求=" << 删除子需求数
        << " | 旧固定必要条件入树=0"
        << " | 重新根据因果链生成=1";
    static std::mutex 记录锁;
    static std::unordered_set<std::string> 已记录;
    const auto 文本 = 日志.str();
    {
        std::lock_guard<std::mutex> lk{ 记录锁 };
        if (!已记录.insert(文本).second) {
            return 删除子需求数;
        }
    }
    项目运行日志(文本);
    return 删除子需求数;
}

// 功能：清理缓存、临时状态或运行资源。
std::size_t 私有_清理遗留固定安全子需求_线程侧(
    自我类& 自我对象,
    需求节点* 根需求,
    const 结构_抽象根特征定义_线程侧& 根定义,
    const 时间戳 now) noexcept
{
    if (!根需求
        || 根定义.根特征类型 != 枚举_自我根特征类型_线程侧::安全) {
        return 0;
    }

    std::size_t 遗留条件数 = 0;
    std::size_t 树上遗留子需求数 = 0;
    std::size_t 删除子需求数 = 0;
    std::vector<需求节点*> 删除候选{};
    const auto 加入删除候选 = [&](需求节点* 候选) noexcept {
        if (!候选 || 候选->主信息.需求有效截止 != 0) {
            return;
        }
        if (std::find(删除候选.begin(), 删除候选.end(), 候选) == 删除候选.end()) {
            删除候选.push_back(候选);
        }
    };
    const auto 遗留条件集 = 私有_读取根特征必要条件定义集_线程侧(
        根定义,
        false,
        true);
    for (const auto& 条件 : 遗留条件集) {
        if (!私有_根必要条件是固定安全字段_线程侧(条件)) {
            continue;
        }
        ++遗留条件数;
        auto* 目标宿主 = 私有_解析根特征必要条件宿主_线程侧(
            自我对象,
            条件.检查宿主语义,
            false);
        auto* 旧子需求 = 目标宿主
            ? 私有_查找根特征必要条件子需求_线程侧(
                根需求,
                目标宿主,
                条件.缺口目标特征类型)
            : nullptr;
        加入删除候选(旧子需求);
    }

    if (根需求->子) {
        auto* 首子 = reinterpret_cast<需求节点*>(根需求->子);
        auto* 当前 = 首子;
        std::size_t 保护计数 = 0;
        do {
            if (当前 && 当前->主信息.需求有效截止 == 0) {
                const auto* 目标特征 =
                    私有_需求目标特征类型_线程侧(当前);
                if (私有_目标特征是固定安全字段_线程侧(目标特征)
                    || 私有_目标特征是根层遗留学习字段_线程侧(目标特征)) {
                    ++树上遗留子需求数;
                    加入删除候选(当前);
                }
            }
            当前 = 当前 ? reinterpret_cast<需求节点*>(当前->下) : nullptr;
            ++保护计数;
        } while (当前 && 当前 != 首子 && 保护计数 < 2048);
    }

    for (auto* 候选 : 删除候选) {
        if (私有_删除遗留根子需求_线程侧(
            根需求,
            候选,
            "旧固定安全字段或根层学习缺口",
            now)) {
            ++删除子需求数;
        }
    }

    std::ostringstream 日志;
    日志 << "自我线程/遗留固定安全需求清理"
        << " | 根=" << 根需求->获取主键()
        << " | 遗留固定安全条件=" << 遗留条件数
        << " | 树上遗留子需求=" << 树上遗留子需求数
        << " | 删除子需求=" << 删除子需求数
        << " | 旧固定必要条件入树=0"
        << " | 重新根据安全因果链生成=1"
        << " | 生成来源=安全因果风险树";
    static std::mutex 记录锁;
    static std::unordered_set<std::string> 已记录;
    const auto 文本 = 日志.str();
    {
        std::lock_guard<std::mutex> lk{ 记录锁 };
        if (!已记录.insert(文本).second) {
            return 删除子需求数;
        }
    }
    项目运行日志(文本);
    return 删除子需求数;
}

// 功能：根据当前输入生成目标数据、场景、动态或回执。
需求节点* 私有_生成根特征必要条件子需求_线程侧(
    自我类& 自我对象,
    需求节点* 根需求,
    存在节点类* 目标宿主,
    const 结构_根特征必要条件定义_线程侧& 条件,
    const I64 当前值,
    const 时间戳 now) noexcept
{
    if (!根需求 || !目标宿主 || !条件.有效()) {
        return nullptr;
    }

    auto* 需求主体 = 自我对象.获取自我存在();
    if (!需求主体) {
        需求主体 = 自我对象.确保自我存在();
    }
    auto* 状态场景 = 自我对象.确保自我内部世界();
    auto* 目标特征 = 私有_确保自我根需求特征节点_线程侧(
        目标宿主,
        条件.缺口目标特征类型);
    if (!需求主体 || !状态场景 || !目标特征) {
        项目运行错误日志(
            "自我线程/根特征必要条件子需求入树失败 | 基础结构缺失"
            " | 根=" + 根需求->获取主键()
            + " | 条件=" + 条件.条件键);
        return nullptr;
    }

    可解析引用<状态节点类> 当前状态{};
    可解析引用<状态节点类> 目标状态{};
    (void)私有_刷新根需求状态引用_线程侧(
        当前状态,
        状态场景,
        目标宿主,
        目标特征,
        当前值,
        false,
        now);
    (void)私有_刷新根需求状态引用_线程侧(
        目标状态,
        状态场景,
        目标宿主,
        目标特征,
        条件.目标值,
        true,
        now);
    if (!当前状态.有效() || !目标状态.有效()) {
        项目运行错误日志(
            "自我线程/根特征必要条件子需求入树失败 | 状态镜像缺失"
            " | 根=" + 根需求->获取主键()
            + " | 条件=" + 条件.条件键);
        return nullptr;
    }

    auto* 需求树根 = 根需求;
    while (需求树根 && 需求树根->父) {
        需求树根 = reinterpret_cast<需求节点*>(需求树根->父);
    }

    结构_需求树更新指令 指令{};
    指令.指令类型 = 枚举_需求树更新指令类型::新增需求;
    指令.父需求指针 = reinterpret_cast<std::uintptr_t>(根需求);
    指令.父需求主键 = 根需求->获取主键();
    指令.需求名称 = 条件.缺口需求名称
        ? 条件.缺口需求名称
        : 条件.缺口目标特征类型;
    指令.需求主体指针 = reinterpret_cast<std::uintptr_t>(需求主体);
    指令.需求主体主键 = 需求主体->获取主键();
    指令.需求场景指针 = reinterpret_cast<std::uintptr_t>(状态场景);
    指令.需求场景主键 = 状态场景->获取主键();
    指令.被需求存在指针 = reinterpret_cast<std::uintptr_t>(目标宿主);
    指令.被需求存在主键 = 目标宿主->获取主键();
    指令.当前状态指针 = reinterpret_cast<std::uintptr_t>(当前状态.指针);
    指令.当前状态主键 = 当前状态.主键;
    指令.需求状态指针 = reinterpret_cast<std::uintptr_t>(目标状态.指针);
    指令.需求状态主键 = 目标状态.主键;
    指令.满足关系 = 关系_等于;
    指令.使用新安全权重 = true;
    指令.使用新服务权重 = true;
    指令.新安全权重 =
        条件.根特征类型 == 枚举_自我根特征类型_线程侧::安全 ? 1 : 0;
    指令.新服务权重 =
        条件.根特征类型 == 枚举_自我根特征类型_线程侧::服务 ? 1 : 0;
    指令.目标特征类型缓存 = 条件.缺口目标特征类型;
    指令.使用阻塞父任务执行 = true;
    指令.阻塞父任务执行 = true;
    指令.记录观测统计 = true;
    指令.统计观测时间 = now;

    需求类 需求服务{};
    auto* 新需求 = 需求服务.执行更新指令(需求树根, 指令);
    if (!新需求) {
        项目运行错误日志(
            "自我线程/根特征必要条件子需求入树失败 | 需求服务拒绝"
            " | 根=" + 根需求->获取主键()
            + " | 条件=" + 条件.条件键
            + " | 目标宿主=" + 目标宿主->获取主键()
            + " | 目标特征=" + 私有_需求类型标题(条件.缺口目标特征类型));
        return nullptr;
    }

    需求类::刷新需求及祖先结构角色(新需求);

    std::ostringstream 日志;
    日志 << "自我线程/根特征必要条件子需求入树"
        << " | 根=" << 根需求->获取主键()
        << " | 子=" << 新需求->获取主键()
        << " | 根特征=" << 私有_根特征类型文本_线程侧(条件.根特征类型)
        << " | 条件=" << 条件.条件键
        << " | 宿主=" << 目标宿主->获取主键()
        << " | 检查特征=" << 私有_需求类型标题(条件.检查特征类型)
        << " | 目标特征=" << 私有_需求类型标题(条件.缺口目标特征类型)
        << " | 当前值=" << 当前值
        << " | 目标值=" << 条件.目标值
        << " | 满足关系=等于"
        << " | 缺口需求=" << (条件.缺口需求名称文本.empty()
            ? 私有_需求类型标题(条件.缺口需求名称)
            : 条件.缺口需求名称文本);
    项目运行日志(日志.str());
    return 新需求;
}

// 功能：服务所在模块的内部辅助流程。
std::size_t 私有_刷新根特征必要条件子需求_线程侧(
    自我类& 自我对象,
    需求节点* 根需求,
    const 结构_抽象根特征定义_线程侧& 根定义,
    const bool 根特征有缺口,
    const 时间戳 now)
{
    if (!根需求 || 根需求->主信息.需求有效截止 != 0) {
        return 0;
    }

    std::size_t 已变更 = 0;
    const bool 是安全根 =
        根定义.根特征类型 == 枚举_自我根特征类型_线程侧::安全;
    const bool 是服务根 =
        根定义.根特征类型 == 枚举_自我根特征类型_线程侧::服务;
    if (是安全根) {
        已变更 += 私有_清理遗留固定安全子需求_线程侧(
            自我对象,
            根需求,
            根定义,
            now);
    }
    if (是服务根) {
        已变更 += 私有_清理遗留固定服务子需求_线程侧(
            自我对象,
            根需求,
            根定义,
            now);
    }
    const bool 服务触发事实存在 =
        !是服务根 || 私有_服务根闭环触发事实存在_线程侧(自我对象, 根需求);
    if (是服务根 && !服务触发事实存在) {
        std::ostringstream 日志;
        日志 << "自我线程/服务需求因果链等待直接服务触发事实"
            << " | 根=" << 根需求->获取主键()
            << " | 旧固定服务需求已清理=1"
            << " | 根据因果链生成=1"
            << " | 直接服务需求生成=0"
            << " | 间接服务维护需求允许=1"
            << " | 创建占位方法头=0";
        static std::mutex 记录锁;
        static std::unordered_set<std::string> 已记录;
        const auto 文本 = 日志.str();
        {
            std::lock_guard<std::mutex> lk{ 记录锁 };
            if (已记录.insert(文本).second) {
                项目运行日志(文本);
            }
        }
    }
    if (是安全根) {
        std::ostringstream 日志;
        日志 << "自我线程/安全需求因果链交由风险树生成"
            << " | 根=" << 根需求->获取主键()
            << " | 旧固定安全需求已清理=1"
            << " | 根据安全因果风险树生成=1"
            << " | 固定安全需求生成=0"
            << " | 创建占位方法头=0";
        static std::mutex 记录锁;
        static std::unordered_set<std::string> 已记录;
        const auto 文本 = 日志.str();
        {
            std::lock_guard<std::mutex> lk{ 记录锁 };
            if (已记录.insert(文本).second) {
                项目运行日志(文本);
            }
        }
    }

    const auto 条件集 = 私有_根闭环可刷新条件集_线程侧(
        根定义,
        服务触发事实存在);
    if (条件集.empty()) {
        return 已变更;
    }
    const auto 根闭环信息位集 = 私有_生成根闭环信息位_线程侧(
        自我对象,
        根需求,
        根定义,
        根特征有缺口);

    for (const auto& 条件 : 条件集) {
        I64 当前值 = 0;
        const bool 条件满足 = 根特征有缺口
            ? 私有_根特征必要条件已满足_线程侧(自我对象, 条件, &当前值)
            : true;
        const auto* 闭环信息位 = 私有_查找根闭环信息位_线程侧(
            根闭环信息位集,
            条件);
        const bool 是服务上下文字段 =
            私有_根必要条件是服务上下文字段_线程侧(条件);
        const bool 服务闭环已触发 =
            !是服务上下文字段
            || 服务触发事实存在;
        if (根特征有缺口 && 是服务上下文字段 && !服务闭环已触发) {
            auto* 旧目标宿主 = 私有_解析根特征必要条件宿主_线程侧(
                自我对象,
                条件.检查宿主语义,
                false);
            auto* 旧子需求 = 旧目标宿主
                ? 私有_查找根特征必要条件子需求_线程侧(
                    根需求,
                    旧目标宿主,
                    条件.缺口目标特征类型)
                : nullptr;
            if (旧子需求
                && 私有_收束根特征必要条件子需求_线程侧(
                    根需求,
                    旧子需求,
                    条件,
                    now)) {
                ++已变更;
            }

            static std::mutex 记录锁;
            static std::unordered_set<std::string> 已记录等待条件;
            const auto 记录键 = 根需求->获取主键() + "|" + 条件.条件键;
            bool 需要记录 = false;
            {
                std::lock_guard<std::mutex> lk{ 记录锁 };
                需要记录 = 已记录等待条件.insert(记录键).second;
            }
            if (需要记录) {
                std::ostringstream 日志;
                日志 << "自我线程/遗留服务上下文条件等待触发事实"
                    << " | 根=" << 根需求->获取主键()
                    << " | 条件=" << 条件.条件键
                    << " | 目标特征=" << 私有_需求类型标题(条件.缺口目标特征类型)
                    << " | 服务触发事实=0"
                    << " | 遗留固定必要条件=1"
                    << " | 保留为根必要条件=0"
                    << " | 生成主动需求=0"
                    << " | 重激活旧需求=0";
                项目运行日志(日志.str());
            }
            continue;
        }

        if (根特征有缺口
            && !条件满足
            && (!闭环信息位 || !闭环信息位->可转需求)) {
            auto* 旧目标宿主 = 私有_解析根特征必要条件宿主_线程侧(
                自我对象,
                条件.检查宿主语义,
                false);
            auto* 旧子需求 = 旧目标宿主
                ? 私有_查找根特征必要条件子需求_线程侧(
                    根需求,
                    旧目标宿主,
                    条件.缺口目标特征类型)
                : nullptr;
            if (旧子需求
                && 私有_收束根特征必要条件子需求_线程侧(
                    根需求,
                    旧子需求,
                    条件,
                    now)) {
                ++已变更;
            }
            私有_记录根闭环缺口准入_线程侧(
                根需求,
                条件,
                闭环信息位,
                false,
                "拒绝刷新根必要条件子需求");
            continue;
        }
        auto* 目标宿主 = 私有_解析根特征必要条件宿主_线程侧(
            自我对象,
            条件.检查宿主语义,
            false);
        if (根特征有缺口 && !条件满足 && !目标宿主) {
            目标宿主 = 私有_解析根特征必要条件宿主_线程侧(
                自我对象,
                条件.检查宿主语义,
                true);
        }
        if (!目标宿主) {
            continue;
        }

        auto* 已有子需求 = 私有_查找根特征必要条件子需求_线程侧(
            根需求,
            目标宿主,
            条件.缺口目标特征类型);
        if (!根特征有缺口 || 条件满足) {
            if (已有子需求
                && 私有_收束根特征必要条件子需求_线程侧(
                    根需求,
                    已有子需求,
                    条件,
                    now)) {
                ++已变更;
            }
            continue;
        }

        if (!已有子需求) {
            私有_记录根闭环缺口准入_线程侧(
                根需求,
                条件,
                闭环信息位,
                true,
                "新增根必要条件子需求");
            auto* 新子需求 = 私有_生成根特征必要条件子需求_线程侧(
                    自我对象,
                    根需求,
                    目标宿主,
                    条件,
                    当前值,
                    now);
            if (新子需求) {
                ++已变更;
            }
            continue;
        }

        私有_记录根闭环缺口准入_线程侧(
            根需求,
            条件,
            闭环信息位,
            true,
            "重激活或更新根必要条件子需求");
        结构_需求树更新指令 指令{};
        指令.指令类型 = 枚举_需求树更新指令类型::更新需求;
        指令.目标需求指针 = reinterpret_cast<std::uintptr_t>(已有子需求);
        指令.目标需求主键 = 已有子需求->获取主键();
        指令.父需求指针 = reinterpret_cast<std::uintptr_t>(根需求);
        指令.父需求主键 = 根需求->获取主键();
        指令.目标特征类型缓存 = 条件.缺口目标特征类型;
        指令.使用新安全权重 = true;
        指令.新安全权重 =
            条件.根特征类型 == 枚举_自我根特征类型_线程侧::安全 ? 1 : 0;
        指令.使用新服务权重 = true;
        指令.新服务权重 =
            条件.根特征类型 == 枚举_自我根特征类型_线程侧::服务 ? 1 : 0;
        指令.使用阻塞父任务执行 = true;
        指令.阻塞父任务执行 = true;
        指令.记录观测统计 = true;
        指令.统计观测时间 = now;
        需求类 需求服务{};
        auto* 需求树根 = 根需求;
        while (需求树根 && 需求树根->父) {
            需求树根 = reinterpret_cast<需求节点*>(需求树根->父);
        }
        if (!需求服务.执行更新指令(需求树根, 指令)) {
            项目运行错误日志(
                "自我线程/根特征必要条件子需求重激活失败"
                " | 根=" + 根需求->获取主键()
                + " | 子=" + 已有子需求->获取主键()
                + " | 条件=" + 条件.条件键);
            continue;
        }
        ++已变更;
    }

    if (已变更 > 0) {
        需求类 需求服务{};
        (void)需求服务.刷新子需求权重(根需求);
        需求类::刷新需求及祖先结构角色(根需求);
    }
    return 已变更;
}

// 判定需求目标是否落在指定特征类型上。用于停用历史根差距子需求时只处理
// 原先自动派生出的同目标子需求，避免误截止其他筹办或学习缺口。

// 功能：判定需求目标是否落在指定特征类型上。用于停用历史根差距子需求时只处理 原先自动派生出的同目标子需求，避免误截止其他筹办或学...
bool 私有_需求目标特征匹配_线程侧(
    const 需求节点* 需求,
    const 语素入口节点类* 目标特征类型) noexcept
{
    if (!需求 || !目标特征类型) {
        return false;
    }
    if (需求->主信息.目标特征类型缓存 == 目标特征类型) {
        return true;
    }

    auto* 目标状态 = 私有_从状态引用解析状态节点(需求->主信息.需求状态);
    const auto* 目标状态特征类型 = 私有_状态节点特征类型_线程侧(目标状态);
    if (目标状态特征类型 == 目标特征类型) {
        return true;
    }

    auto* 当前状态 = 私有_从状态引用解析状态节点(需求->主信息.被需求当前状态);
    const auto* 当前状态特征类型 = 私有_状态节点特征类型_线程侧(当前状态);
    return 当前状态特征类型 == 目标特征类型;
}

// 根需求差距不再生成同目标子需求；历史上已生成的差距子需求只保留复盘痕迹，
// 进入本轮需求整理时统一退出活动集，避免复制根目标并继续任务化。

// 功能：根需求差距不再生成同目标子需求；历史上已生成的差距子需求只保留复盘痕迹， 进入本轮需求整理时统一退出活动集，避免复制根目标...
std::size_t 私有_停用根需求差距执行子需求_线程侧(
    自我类& 自我对象,
    需求节点* 根需求,
    const 语素入口节点类* 目标特征类型,
    const 时间戳 now) noexcept
{
    if (!根需求
        || !目标特征类型
        || 根需求->主信息.需求有效截止 != 0) {
        return 0;
    }

    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 需求根节点 = 自我存在
        ? reinterpret_cast<需求节点*>(世界树.存在().获取需求根节点(自我存在))
        : nullptr;
    if (!需求根节点 || !根需求->子) {
        return 0;
    }

    std::vector<需求节点*> 待收束{};
    auto* 首子 = reinterpret_cast<需求节点*>(根需求->子);
    auto* 当前 = 首子;
    std::size_t 保护计数 = 0;
    do {
        if (当前
            && 当前->主信息.需求有效截止 == 0
            && 当前->主信息.派生来源方法主键 == "根需求差距刷新"
            && 私有_需求目标特征匹配_线程侧(当前, 目标特征类型)) {
            待收束.push_back(当前);
        }
        当前 = 当前 ? reinterpret_cast<需求节点*>(当前->下) : nullptr;
        ++保护计数;
    } while (当前 && 当前 != 首子 && 保护计数 < 2048);

    if (待收束.empty()) {
        return 0;
    }

    需求类 需求服务{};
    std::size_t 已收束 = 0;
    for (auto* 子需求 : 待收束) {
        if (!子需求 || 子需求->主信息.需求有效截止 != 0) {
            continue;
        }

        // 同目标差距只属于根需求状态镜像，不再作为正式子需求驱动主链。
        // 通过需求类的“满足需求”入口截止历史节点，保证权重和角色刷新仍走统一机制。
        结构_需求树更新指令 指令{};
        指令.指令类型 = 枚举_需求树更新指令类型::满足需求;
        指令.目标需求指针 = reinterpret_cast<std::uintptr_t>(子需求);
        指令.目标需求主键 = 子需求->获取主键();
        指令.父需求指针 = reinterpret_cast<std::uintptr_t>(根需求);
        指令.父需求主键 = 根需求->获取主键();
        指令.当前状态指针 =
            reinterpret_cast<std::uintptr_t>(根需求->主信息.被需求当前状态.指针);
        指令.当前状态主键 = 根需求->主信息.被需求当前状态.主键;
        指令.需求状态指针 =
            reinterpret_cast<std::uintptr_t>(根需求->主信息.需求状态.指针);
        指令.需求状态主键 = 根需求->主信息.需求状态.主键;
        指令.满足关系 = 根需求->主信息.满足关系 != 0
            ? 根需求->主信息.满足关系
            : 关系_等于;
        指令.使用新安全权重 = true;
        指令.新安全权重 = 0;
        指令.使用新服务权重 = true;
        指令.新服务权重 = 0;
        指令.标记已满足 = true;
        指令.使用阻塞父任务执行 = true;
        指令.阻塞父任务执行 = false;
        指令.记录观测统计 = true;
        指令.统计观测时间 = now;

        auto* 结果 = 需求服务.执行更新指令(需求根节点, 指令);
        if (!结果) {
            项目运行错误日志(
                "自我线程/根需求差距子需求退出活动集失败"
                " | 根=" + 根需求->获取主键()
                + " | 子=" + 子需求->获取主键());
            continue;
        }

        ++已收束;

        std::ostringstream 输出;
        输出 << "自我线程/根需求差距子需求退回根需求状态"
            << " | 根=" << 根需求->获取主键()
            << " | 子=" << 子需求->获取主键()
            << " | 特征=" << (目标特征类型 ? 目标特征类型->获取主键() : std::string("空"))
            << " | 截止=" << 子需求->主信息.需求有效截止
            << " | 阻塞父任务=否"
            << " | 安全权重=0"
            << " | 服务权重=0";
        项目运行日志(输出.str());
    }

    if (已收束 > 0) {
        (void)需求服务.刷新子需求权重(根需求);
        需求类::刷新需求及祖先结构角色(根需求);
    }
    return 已收束;
}

// 功能：构建运行所需的数据结构或中间结果。
std::vector<自我线程类::结构_需求列表项> 私有_从需求树构建需求列表(
    const 自我类& 自我对象,
    const 枚举_需求列表排序主轴 排序主轴)
{
    私有_记录抽象根特征定义读取快照_线程侧();
    const auto 根压力评估 = 自我对象.评估根需求压力();
    auto* 安全根需求 = 自我对象.获取安全根需求();
    auto* 服务根需求 = 自我对象.获取服务根需求();
    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 需求根节点 = 自我存在 ? 世界树.存在().获取需求根节点(自我存在) : nullptr;
    if (!需求根节点) {
        return {};
    }
    需求类 需求服务{};
    {
        std::lock_guard<std::recursive_mutex> 需求树锁{
            需求类::借用需求树全局互斥()
        };
        auto& 可变自我 = const_cast<自我类&>(自我对象);
        const auto now = 结构体_时间戳::当前_微秒();
        const I64 当前安全值 = 自我对象.获取安全值();
        const I64 当前服务值 = 自我对象.获取服务值();
        const auto 安全根定义 = 私有_读取抽象根特征定义_线程侧(
            枚举_自我根特征类型_线程侧::安全);
        const auto 服务根定义 = 私有_读取抽象根特征定义_线程侧(
            枚举_自我根特征类型_线程侧::服务);
        const I64 安全目标值 = 安全根定义.成功()
            ? 安全根定义.目标区间.低值
            : 当前安全值;
        const I64 服务目标值 = 服务根定义.成功()
            ? 服务根定义.目标区间.低值
            : 当前服务值;
        const bool 安全根特征有缺口 = 安全根定义.成功()
            ? 当前安全值 < 安全目标值
            : 根压力评估.安全压力 > 0;
        const bool 服务根特征有缺口 = 服务根定义.成功()
            ? 当前服务值 < 服务目标值
            : 根压力评估.服务压力 > 0;
        私有_刷新根需求状态镜像_线程侧(
            可变自我,
            安全根需求,
            自我特征定义类::类型_自我_安全值(),
            当前安全值,
            安全目标值,
            now);
        私有_刷新根需求状态镜像_线程侧(
            可变自我,
            服务根需求,
            自我特征定义类::类型_自我_服务值(),
            当前服务值,
            服务目标值,
            now);
        const auto 提交根需求权重 = [&需求服务, 需求根节点](需求节点* 根需求, I64 安全权重, I64 服务权重) noexcept {
            if (!根需求 || !需求根节点) {
                return;
            }
            结构_需求树更新指令 指令{};
            指令.指令类型 = 枚举_需求树更新指令类型::更新需求;
            指令.目标需求指针 = reinterpret_cast<std::uintptr_t>(根需求);
            指令.目标需求主键 = 根需求->获取主键();
            指令.使用新安全权重 = true;
            指令.新安全权重 = 安全权重;
            指令.使用新服务权重 = true;
            指令.新服务权重 = 服务权重;
            if (!需求服务.执行更新指令(需求根节点, 指令)) {
                项目运行错误日志(
                    "自我线程/根需求权重更新失败 | 需求="
                    + 根需求->获取主键()
                    + " | 说明=根需求权重必须经需求树更新指令提交");
            }
        };
        if (安全根需求) {
            提交根需求权重(安全根需求, 安全根特征有缺口 ? 1 : 0, 0);
        }
        if (服务根需求) {
            提交根需求权重(服务根需求, 0, 服务根特征有缺口 ? 1 : 0);
        }
        if (安全根需求) {
            const auto 根闭环信息位 = 私有_生成根闭环信息位_线程侧(
                可变自我,
                安全根需求,
                安全根定义,
                安全根特征有缺口);
            私有_记录根闭环信息位挂载_线程侧(
                安全根需求,
                根闭环信息位);
        }
        if (服务根需求) {
            const auto 根闭环信息位 = 私有_生成根闭环信息位_线程侧(
                可变自我,
                服务根需求,
                服务根定义,
                服务根特征有缺口);
            私有_记录根闭环信息位挂载_线程侧(
                服务根需求,
                根闭环信息位);
        }
        if (安全根需求) {
            (void)私有_停用根需求差距执行子需求_线程侧(
                可变自我,
                安全根需求,
                自我特征定义类::类型_自我_安全值(),
                now);
        }
        if (服务根需求) {
            (void)私有_停用根需求差距执行子需求_线程侧(
                可变自我,
                服务根需求,
                自我特征定义类::类型_自我_服务值(),
                now);
        }
        if (安全根需求) {
            (void)私有_刷新根特征必要条件子需求_线程侧(
                可变自我,
                安全根需求,
                安全根定义,
                安全根特征有缺口,
                now);
        }
        if (服务根需求) {
            (void)私有_刷新根特征必要条件子需求_线程侧(
                可变自我,
                服务根需求,
                服务根定义,
                服务根特征有缺口,
                now);
        }
        if (安全根需求) {
            (void)需求服务.刷新子需求权重(安全根需求);
        }
        if (服务根需求) {
            (void)需求服务.刷新子需求权重(服务根需求);
        }
    }

    std::vector<const 需求节点*> 节点列表{};
    (void)私有_收束已完成叶需求_线程侧(
        const_cast<自我类&>(自我对象),
        需求根节点,
        结构体_时间戳::当前_微秒());

    for (auto* 当前节点 = 需求根节点->链下;
         当前节点 && 当前节点 != 需求根节点;
         当前节点 = 当前节点->链下) {
        节点列表.push_back(当前节点);
    }

    std::unordered_map<const 语素入口节点类*, I64> 目标特征安全权重汇总{};
    std::unordered_map<const 语素入口节点类*, I64> 目标特征服务权重汇总{};
    std::unordered_map<const 语素入口节点类*, std::string> 目标特征标题{};
    for (const auto* 节点 : 节点列表) {
        const auto* 目标特征类型 = 需求类::读取需求目标特征类型(节点);
        目标特征安全权重汇总[目标特征类型] += 节点->主信息.安全权重;
        目标特征服务权重汇总[目标特征类型] += 节点->主信息.服务权重;
        auto& 标题 = 目标特征标题[目标特征类型];
        if (标题.empty()) {
            标题 = 私有_需求类型标题(目标特征类型);
        }
    }

    std::stable_sort(
        节点列表.begin(),
        节点列表.end(),
        [&](const 需求节点* 左, const 需求节点* 右) {
            const auto* 左目标特征 = 左 ? 需求类::读取需求目标特征类型(左) : nullptr;
            const auto* 右目标特征 = 右 ? 需求类::读取需求目标特征类型(右) : nullptr;
            自我线程类::结构_需求列表项 左列表项{};
            左列表项.目标特征名称 = 目标特征标题[左目标特征];
            左列表项.需求节点主键 = 左 ? 左->获取主键() : std::string{};
            左列表项.节点安全权重 = 左 ? 左->主信息.安全权重 : 0;
            左列表项.节点服务权重 = 左 ? 左->主信息.服务权重 : 0;
            左列表项.目标特征安全权重汇总 = 目标特征安全权重汇总[左目标特征];
            左列表项.目标特征服务权重汇总 = 目标特征服务权重汇总[左目标特征];

            自我线程类::结构_需求列表项 右列表项{};
            右列表项.目标特征名称 = 目标特征标题[右目标特征];
            右列表项.需求节点主键 = 右 ? 右->获取主键() : std::string{};
            右列表项.节点安全权重 = 右 ? 右->主信息.安全权重 : 0;
            右列表项.节点服务权重 = 右 ? 右->主信息.服务权重 : 0;
            右列表项.目标特征安全权重汇总 = 目标特征安全权重汇总[右目标特征];
            右列表项.目标特征服务权重汇总 = 目标特征服务权重汇总[右目标特征];

            return 私有_需求列表项排序在前(左列表项, 右列表项, 排序主轴);
        });

    std::vector<自我线程类::结构_需求列表项> 需求列表{};
    需求列表.reserve(节点列表.size());
    for (const auto* 节点 : 节点列表) {
        if (!节点) {
            continue;
        }

        自我线程类::结构_需求列表项 列表项{};
        const auto* 目标特征类型 = 需求类::读取需求目标特征类型(节点);
        列表项.目标特征类型 = 目标特征类型;
        列表项.目标特征名称 = 私有_需求类型标题(目标特征类型);
        列表项.需求节点指针 = reinterpret_cast<std::uintptr_t>(节点);
        列表项.需求节点主键 = 节点->获取主键();
        列表项.节点安全权重 = 节点->主信息.安全权重;
        列表项.节点服务权重 = 节点->主信息.服务权重;
        列表项.目标特征安全权重汇总 = 目标特征安全权重汇总[目标特征类型];
        列表项.目标特征服务权重汇总 = 目标特征服务权重汇总[目标特征类型];
        需求列表.push_back(std::move(列表项));
    }

    return 需求列表;
}

// 功能：从候选集中选择当前使用对象或方法。
需求类::节点类* 私有_选择当前主需求候选_按根权重(
    const 自我类& 自我对象) noexcept
{
    const auto 根压力 = 自我对象.评估根需求压力();
    if (根压力.安全压力 <= 0 && 根压力.服务压力 <= 0) {
        return nullptr;
    }
    return 根压力.选中需求;
}

// 功能：从候选集中选择当前使用对象或方法。
任务类::节点类* 私有_选择当前主任务候选_按任务优先级(
    const 自我类& 自我对象) noexcept
{
    auto* 自我存在 = 自我对象.获取自我存在();
    auto* 任务根节点 = 自我存在
        ? reinterpret_cast<任务节点*>(世界树.存在().获取任务根节点(自我存在))
        : nullptr;
    if (!任务根节点) {
        return nullptr;
    }

    auto 服务列表 = 私有_从需求树构建需求列表(自我对象, 枚举_需求列表排序主轴::服务优先);
    auto 安全列表 = 私有_从需求树构建需求列表(自我对象, 枚举_需求列表排序主轴::安全优先);

    任务节点* 最佳任务 = nullptr;
    需求节点* 最佳需求 = nullptr;
    std::int64_t 最佳分数 = (std::numeric_limits<std::int64_t>::min)();
    std::string 最佳任务主键{};
    std::unordered_set<任务节点*> 已检查任务{};

    const auto 任务可参与调度 = [任务根节点](任务节点* 任务) noexcept {
        if (!任务
            || 任务类::读取任务节点种类(任务) != 枚举_任务节点种类::头结点
            || !私有_节点属于独立树(任务根节点, 任务)
            || 私有_任务状态已终结_任务管理新链(任务类::读取任务状态(任务))
            || 任务类::读取任务状态(任务) == 枚举_任务状态::等待中
            || 任务类::读取任务状态(任务) == 枚举_任务状态::挂起) {
            return false;
        }
        return true;
    };
    const auto 计算任务分数 = [](const 任务节点* 任务, const 需求节点* 需求) noexcept {
        if (!任务) {
            return (std::numeric_limits<std::int64_t>::min)();
        }
        const auto 调度优先级 = 任务类::读取任务调度优先级(任务);
        auto 分数 = 调度优先级 != 0
            ? 调度优先级
            : (任务类::读取任务基准优先级(任务) + 任务类::读取任务局部优先级偏移(任务));
        if (分数 == 0 && 需求) {
            分数 = 需求->主信息.安全权重 + 需求->主信息.服务权重;
        }
        return 分数;
    };
    const auto 是祖先需求 = [](const 需求节点* 祖先, const 需求节点* 后代) noexcept {
        if (!祖先 || !后代 || 祖先 == 后代) {
            return false;
        }
        for (auto* 当前 = reinterpret_cast<const 需求节点*>(后代->父);
             当前;
             当前 = reinterpret_cast<const 需求节点*>(当前->父)) {
            if (当前 == 祖先) {
                return true;
            }
        }
        return false;
    };
    const auto 考虑需求任务 = [&](任务节点* 任务, 需求节点* 需求节点) {
        if (!任务可参与调度(任务) || !已检查任务.insert(任务).second) {
            return;
        }

        auto* 任务来源需求 = 私有_任务来源需求_线程侧(任务);
        const bool 来源一致 =
            任务来源需求
            && 需求节点
            && (任务来源需求 == 需求节点
                || (!任务来源需求->获取主键().empty()
                    && 任务来源需求->获取主键() == 需求节点->获取主键()));
        if (!来源一致) {
            项目运行错误日志(
                "自我线程/主任务选择拒绝无结构化对应需求任务"
                " | 任务=" + 任务->获取主键()
                + " | 列表需求=" + (需求节点 ? 需求节点->获取主键() : std::string("空"))
                + " | 任务来源需求=" + (任务来源需求 ? 任务来源需求->获取主键() : std::string("空"))
                + " | 说明=不再在选择阶段隐式补写任务对应需求");
            return;
        }
        const auto 分数 = 计算任务分数(任务, 需求节点);
        const auto 任务主键 = 任务->获取主键();
        const bool 当前是最佳子需求 = 是祖先需求(最佳需求, 需求节点);
        const bool 当前是最佳父需求 = 是祖先需求(需求节点, 最佳需求);
        if (!最佳任务
            || 当前是最佳子需求
            || (!当前是最佳父需求
                && (分数 > 最佳分数
                    || (分数 == 最佳分数 && 任务主键 < 最佳任务主键)))) {
            最佳任务 = 任务;
            最佳需求 = 需求节点;
            最佳分数 = 分数;
            最佳任务主键 = 任务主键;
        }
    };
    const auto 扫描需求列表 = [&](const std::vector<自我线程类::结构_需求列表项>& 需求列表) {
        for (const auto& 列表项 : 需求列表) {
            auto* 需求节点 = 私有_从需求列表项解析需求节点(列表项);
            if (!需求节点 || 需求节点->主信息.需求有效截止 != 0) {
                continue;
            }

            // 对应任务是需求当前权威承接壳，任务列表只保存候选、历史和重建记录。
            // 主任务选择必须优先看对应任务，否则新链创建的根任务会被漏选。
            考虑需求任务(
                私有_从任务引用解析任务节点(需求节点->主信息.对应任务),
                需求节点);
            for (auto& 引用 : 需求节点->主信息.任务列表) {
                考虑需求任务(
                    私有_从任务引用解析任务节点(引用),
                    需求节点);
            }
        }
    };

    扫描需求列表(服务列表);
    扫描需求列表(安全列表);
    return 最佳任务;
}

// 功能：服务所在模块的内部辅助流程。
std::string 私有_需求节点角色文本(
    const 自我类& 自我对象,
    const 需求类::节点类* 需求节点)
{
    if (!需求节点) {
        return "未定义";
    }
    if (!私有_校验需求节点属于当前需求树(
            自我对象,
            const_cast<需求类::节点类*>(需求节点))) {
        return "无效需求指针";
    }
    if (需求节点 == 自我对象.获取安全根需求()) {
        return "安全根需求";
    }
    if (需求节点 == 自我对象.获取服务根需求()) {
        return "服务根需求";
    }
    const auto 主键 = 需求节点->获取主键();
    return 主键.empty() ? "未定义" : 主键;
}

// 功能：服务所在模块的内部辅助流程。
const char* 私有_线程生命周期文本(枚举_线程生命周期状态 状态) noexcept
{
    switch (状态) {
    case 枚举_线程生命周期状态::未启动: return "未启动";
    case 枚举_线程生命周期状态::启动中: return "启动中";
    case 枚举_线程生命周期状态::运行中: return "运行中";
    case 枚举_线程生命周期状态::停止请求中: return "停止请求中";
    case 枚举_线程生命周期状态::收尾中: return "收尾中";
    case 枚举_线程生命周期状态::已停止: return "已停止";
    case 枚举_线程生命周期状态::故障: return "故障";
    default: return "未定义";
    }
}

// 功能：服务所在模块的内部辅助流程。
枚举_线程生命周期消息事件 私有_映射自我线程生命周期消息事件(
    const 枚举_线程生命周期状态 旧状态,
    const 枚举_线程生命周期状态 新状态) noexcept
{
    if (新状态 == 枚举_线程生命周期状态::故障) {
        return 枚举_线程生命周期消息事件::故障;
    }
    if (新状态 == 枚举_线程生命周期状态::已停止) {
        return 枚举_线程生命周期消息事件::已退出;
    }
    if (新状态 == 枚举_线程生命周期状态::收尾中) {
        return 枚举_线程生命周期消息事件::退出前;
    }
    if (旧状态 == 枚举_线程生命周期状态::未启动
        && 新状态 == 枚举_线程生命周期状态::启动中) {
        return 枚举_线程生命周期消息事件::创建;
    }
    return 枚举_线程生命周期消息事件::状态变化;
}

// 功能：服务所在模块的内部辅助流程。
void 私有_发送自我线程生命周期控制面板消息(
    const 枚举_线程生命周期状态 旧状态,
    const 枚举_线程生命周期状态 新状态,
    const 时间戳 now,
    const std::string& 原因键,
    const std::string& 摘要,
    const bool 是否故障触发) noexcept
{
    结构_线程生命周期消息 消息{};
    消息.事件类型 = 私有_映射自我线程生命周期消息事件(旧状态, 新状态);
    消息.发生时间 = now;
    消息.线程逻辑ID = "self-main";
    消息.自动填充当前系统线程ID =
        消息.事件类型 != 枚举_线程生命周期消息事件::创建;
    消息.线程名称 = "自我线程";
    消息.线程用途 = "自我主循环、需求树治理和任务发起意图";
    消息.线程类别 = "逻辑线程";
    消息.所属模块 = "自我线程模块";
    消息.创建者逻辑ID = "process-main";
    消息.创建者名称 = "鱼巢主线程";
    消息.旧生命周期状态 = 私有_线程生命周期文本(旧状态);
    消息.新生命周期状态 = 私有_线程生命周期文本(新状态);
    消息.旧运行状态 = 私有_线程生命周期文本(旧状态);
    消息.新运行状态 = 私有_线程生命周期文本(新状态);
    消息.是否健康 = !是否故障触发 && 新状态 != 枚举_线程生命周期状态::故障;
    消息.是否正常退出 = 新状态 == 枚举_线程生命周期状态::已停止;
    消息.原因键 = 原因键;
    消息.显示摘要 = 摘要;
    (void)发送线程生命周期消息(std::move(消息));
}

