std::string 私有_推断线程标签(const 结构_线程存在初始化参数& 参数)
{
    if (!参数.线程标签.empty()) {
        return 参数.线程标签;
    }
    if (参数.是自我线程) {
        return "自我线程";
    }
    if (参数.是工作线程) {
        return "工作线程";
    }
    return "线程";
}

