// 功能：确保目标结构、状态或前置条件存在并可用。
需求节点* 私有_确保目标I64子需求_线程侧(
    自我类& 自我对象,
    需求节点* 父需求,
    存在节点类* 目标存在,
    const 语素入口节点类* 目标特征,
    I64 当前值,
    I64 目标值,
    时间戳 now) noexcept
{
    if (!父需求 || !目标存在 || !目标特征) {
        return nullptr;
    }
    if (auto* 已有需求 = 私有_查找根特征必要条件子需求_线程侧(
            父需求,
            目标存在,
            目标特征)) {
        return 已有需求;
    }

    auto* 需求主体 = 父需求->主信息.需求主体.指针;
    if (!需求主体) {
        需求主体 = 自我对象.获取自我存在();
    }
    if (!需求主体) {
        需求主体 = 自我对象.确保自我存在();
    }
    auto* 需求场景 = 父需求->主信息.需求场景.指针;
    if (!需求场景) {
        需求场景 = 自我对象.确保自我内部世界();
    }
    if (!需求场景) {
        需求场景 = 自我对象.获取自我现实场景();
    }
    auto* 当前状态 = 私有_创建安全风险树I64状态节点_线程侧(
        自我对象,
        reinterpret_cast<基础信息节点类*>(目标存在),
        目标特征,
        当前值,
        now);
    auto* 目标状态 = 私有_创建安全风险树I64状态节点_线程侧(
        自我对象,
        reinterpret_cast<基础信息节点类*>(目标存在),
        目标特征,
        目标值,
        now);
    if (!需求主体 || !需求场景 || !当前状态 || !目标状态) {
        return nullptr;
    }

    auto* 需求树根 = 私有_需求树根_线程侧(父需求);
    if (!需求树根) {
        return nullptr;
    }

    结构_需求树更新指令 指令{};
    指令.指令类型 = 枚举_需求树更新指令类型::新增需求;
    指令.父需求指针 = reinterpret_cast<std::uintptr_t>(父需求);
    指令.父需求主键 = 父需求->获取主键();
    指令.需求名称 = 目标特征;
    指令.需求主体指针 = reinterpret_cast<std::uintptr_t>(需求主体);
    指令.需求主体主键 = 需求主体->获取主键();
    指令.需求场景指针 = reinterpret_cast<std::uintptr_t>(需求场景);
    指令.需求场景主键 = 需求场景->获取主键();
    指令.被需求存在指针 = reinterpret_cast<std::uintptr_t>(目标存在);
    指令.被需求存在主键 = 目标存在->获取主键();
    指令.当前状态指针 = reinterpret_cast<std::uintptr_t>(当前状态);
    指令.当前状态主键 = 当前状态->获取主键();
    指令.需求状态指针 = reinterpret_cast<std::uintptr_t>(目标状态);
    指令.需求状态主键 = 目标状态->获取主键();
    指令.满足关系 = 关系_等于;
    指令.目标特征类型缓存 = 目标特征;
    指令.使用新安全权重 = true;
    指令.使用新服务权重 = true;
    指令.新安全权重 = 父需求->主信息.安全权重 > 0 ? 1 : 0;
    指令.新服务权重 = 父需求->主信息.服务权重 > 0 ? 1 : 0;
    if (指令.新安全权重 == 0 && 指令.新服务权重 == 0) {
        指令.新服务权重 = 1;
    }
    指令.使用阻塞父任务执行 = true;
    指令.阻塞父任务执行 = false;
    指令.记录观测统计 = true;
    指令.统计观测时间 = now;

    需求类 需求服务{};
    auto* 新需求 = 需求服务.执行更新指令(需求树根, 指令);
    if (新需求) {
        需求类::刷新需求及祖先结构角色(新需求);
    }
    return 新需求;
}

