// 功能：确保目标结构、状态或前置条件存在并可用。
bool 私有_扫描材料承接后确保6146任务主体_线程侧(
    const 结构_任务管理观察事实承接请求& 请求,
    const 结构_外设观察报告队列项* 报告,
    bool 承接成功,
    bool 报告可回查,
    时间戳 now) noexcept
{
    const auto 报告ID = 请求.报告ID != 0
        ? 请求.报告ID
        : (报告 ? 报告->报告ID : 0);
    const auto 记录结果 = [&](const char* 结果, const std::string& 原因) noexcept {
        项目运行日志(
            std::string("自我线程/扫描材料承接确保6146任务主体")
            + " | 结果=" + (结果 ? 结果 : "未定义")
            + " | 原因=" + 原因
            + " | 报告ID=" + std::to_string(报告ID)
            + " | 等待项ID=" + std::to_string(请求.等待项ID)
            + " | 来源需求=" + (请求.来源需求ID.empty() ? std::string("空") : 请求.来源需求ID)
            + " | 目标存在=" + (请求.目标存在ID.empty() ? std::string("空") : 请求.目标存在ID)
            + " | 目标特征=" + (请求.目标特征类型ID.empty() ? std::string("空") : 请求.目标特征类型ID)
            + " | 承接成功=" + std::to_string(承接成功 ? 1 : 0)
            + " | 报告可回查=" + std::to_string(报告可回查 ? 1 : 0));
    };
    if (!承接成功 || !报告可回查 || !报告) {
        记录结果("跳过", !承接成功
            ? "扫描材料未承接成功"
            : (!报告可回查 ? "扫描报告不可回查" : "缺扫描报告对象"));
        return false;
    }
    if (报告->报告类型 != 枚举_外设观察报告类型::扫描变化报告) {
        记录结果("跳过", "报告类型不是扫描变化报告");
        return false;
    }
    const auto* 目标特征 = 私有_已识别区域扫描入账状态特征_线程侧();
    const auto 目标特征主键 = 目标特征 ? 目标特征->获取主键() : std::string{};
    if (!目标特征
        || (!请求.目标特征类型ID.empty()
            && 请求.目标特征类型ID != 目标特征主键)) {
        记录结果("跳过", !目标特征
            ? "缺已识别区域扫描入账状态特征"
            : "请求目标特征不是已识别区域扫描入账状态");
        return false;
    }
    auto* 来源需求 = 私有_按主键解析需求节点(请求.来源需求ID);
    if (!来源需求) {
        记录结果("跳过", "来源需求不在当前需求树");
        return false;
    }
    auto* 目标存在 = 私有_按主键解析正式目标存在_线程侧(请求.目标存在ID);
    if (!目标存在) {
        记录结果("跳过", "目标存在无法解析为正式存在");
        return false;
    }

    auto* 扫描需求 = 私有_确保扫描入账子需求_线程侧(
        自我,
        来源需求,
        目标存在,
        目标特征,
        请求.目标特征当前值,
        now);
    if (!扫描需求) {
        记录结果("失败", "扫描入账子需求创建或复用失败");
        return false;
    }

    if (私有_需求已有非终结任务_线程侧(扫描需求)) {
        记录结果("已有任务", "扫描入账子需求已有非终结任务");
        return true;
    }

    auto* 新任务 = 私有_提交任务发起请求到任务管理界面线程_线程侧(
        自我,
        扫描需求,
        now,
        true);
    记录结果(新任务 ? "创建任务" : "失败", 新任务 ? "扫描入账子需求已提交任务发起" : "任务管理未返回新任务");
    return 新任务 != nullptr;
}

// 功能：确保目标结构、状态或前置条件存在并可用。
bool 私有_扫描材料承接后确保6147任务主体_线程侧(
    const 结构_任务管理观察事实承接请求& 请求,
    const 结构_外设观察报告队列项* 报告,
    bool 承接成功,
    bool 报告可回查,
    时间戳 now) noexcept
{
    if (!承接成功 || !报告可回查 || !报告) {
        return false;
    }
    if (报告->报告类型 != 枚举_外设观察报告类型::扫描变化报告) {
        return false;
    }
    const auto* 扫描目标特征 = 私有_已识别区域扫描入账状态特征_线程侧();
    const auto 扫描目标特征主键 = 扫描目标特征 ? 扫描目标特征->获取主键() : std::string{};
    if (!请求.目标特征类型ID.empty()
        && !扫描目标特征主键.empty()
        && 请求.目标特征类型ID != 扫描目标特征主键) {
        return false;
    }
    const auto* 目标特征 = 私有_目标存在跟踪状态特征_线程侧();
    if (!目标特征) {
        return false;
    }
    auto* 来源需求 = 私有_按主键解析需求节点(请求.来源需求ID);
    if (!来源需求) {
        return false;
    }
    auto* 目标存在 = 私有_按主键解析正式目标存在_线程侧(请求.目标存在ID);
    if (!目标存在) {
        return false;
    }

    auto* 跟踪需求 = 私有_确保跟踪状态子需求_线程侧(
        自我,
        来源需求,
        目标存在,
        目标特征,
        I64{0},
        now);
    if (!跟踪需求) {
        return false;
    }

    if (私有_需求已有非终结任务_线程侧(跟踪需求)) {
        return true;
    }

    auto* 新任务 = 私有_提交任务发起请求到任务管理界面线程_线程侧(
        自我,
        跟踪需求,
        now,
        true);
    return 新任务 != nullptr;
}

// 功能：执行任务、方法或动作的主体逻辑。
bool 私有_审批任务执行前许可请求_线程侧(
    const 自我线程消息协议::结构_治理消息& 消息) noexcept
{
    if (!消息.附加载荷.任务管理执行前许可请求.has_value()) {
        return false;
    }

    const auto& 请求 = *消息.附加载荷.任务管理执行前许可请求;
    任务管理线程协议::结构_任务执行前许可结果 结果{};
    结果.任务信息节点 =
        reinterpret_cast<任务节点类*>(请求.任务信息节点指针);
    结果.来源需求 =
        reinterpret_cast<需求节点类*>(请求.来源需求指针);
    结果.当前方法 =
        reinterpret_cast<方法类::节点类*>(请求.当前方法指针);
    结果.工作项ID = 请求.工作项ID;
    结果.已审批 = true;
    结果.允许执行 = true;
    结果.需要等待 = false;
    结果.需要收束 = false;
    结果.禁止项接口已预留 = true;
    结果.禁止项命中 = false;
    结果.方向证据已提供 = 请求.方向证据已提供;
    结果.方向不一致 = false;
    结果.原因 = "现阶段固定允许执行前许可";

    const bool 已提交 = 任务管理界面线程::提交任务执行前许可结果(结果);
    项目运行日志(
        "自我线程/执行前许可审批"
        " | 工作项=" + std::to_string(请求.工作项ID)
        + " | 任务=" + (请求.任务主键.empty() ? std::string("空") : 请求.任务主键)
        + " | 来源需求=" + (请求.来源需求主键.empty() ? std::string("空") : 请求.来源需求主键)
        + " | 当前方法=" + (请求.当前方法主键.empty() ? std::string("空") : 请求.当前方法主键)
        + " | 允许执行=1"
        + " | 禁止项接口预留=1"
        + " | 禁止项命中=0"
        + " | 方向不一致=0"
        + " | 提交结果=" + std::to_string(已提交 ? 1 : 0));
    return 已提交;
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_落任务管理观察事实承接请求到自我内部世界(
    const 自我线程消息协议::结构_治理消息& 消息) noexcept
{
    if (!消息.附加载荷.任务管理观察事实承接请求.has_value()) {
        return false;
    }

    const auto& 请求 = *消息.附加载荷.任务管理观察事实承接请求;
    项目运行日志(
        "自我线程/外设观察事实承接开始 | "
        + 构造任务管理观察事实承接请求文本(请求));

    auto* 自我内部世界 = 自我.确保自我内部世界();
    if (!自我内部世界) {
        项目运行日志(
            "自我线程/外设观察事实承接失败 | 原因=缺少自我内部世界 | "
            + 构造任务管理观察事实承接请求文本(请求));
        return false;
    }

    const auto 报告 = 读取外设观察报告_按ID(请求.报告ID);
    const bool 报告可回查 = 报告.has_value();
    项目运行日志(
        "自我线程/外设观察事实承接回查完成"
        " | 报告ID=" + std::to_string(请求.报告ID)
        + " | 报告可回查=" + (报告可回查 ? std::string("是") : std::string("否")));
    if (!报告可回查) {
        项目运行日志(
            "自我线程/外设观察事实承接证据不足 | 原因=报告缓存不可回查 | "
            + 构造任务管理观察事实承接请求文本(请求));
    } else {
        const bool 目标约束ID不一致 =
            请求.目标观察约束ID != 0
            && 报告->目标观察约束ID != 0
            && 请求.目标观察约束ID != 报告->目标观察约束ID;
        const bool 约束generation不一致 =
            !请求.约束generation.empty()
            && !报告->约束generation.empty()
            && 请求.约束generation != 报告->约束generation;
        const bool 目标特征generation不一致 =
            !请求.目标特征generation.empty()
            && !报告->目标特征generation.empty()
            && 请求.目标特征generation != 报告->目标特征generation;
        if (目标约束ID不一致
            || 约束generation不一致
            || 目标特征generation不一致) {
            项目运行日志(
                "自我线程/外设观察事实承接证据不足"
                " | 原因=报告目标约束与承接请求不一致"
                " | 请求目标观察约束ID=" + std::to_string(请求.目标观察约束ID)
                + " | 报告目标观察约束ID=" + std::to_string(报告->目标观察约束ID)
                + " | 请求约束generation=" + (请求.约束generation.empty() ? std::string("空") : 请求.约束generation)
                + " | 报告约束generation=" + (报告->约束generation.empty() ? std::string("空") : 报告->约束generation)
                + " | 请求目标特征generation=" + (请求.目标特征generation.empty() ? std::string("空") : 请求.目标特征generation)
                + " | 报告目标特征generation=" + (报告->目标特征generation.empty() ? std::string("空") : 报告->目标特征generation)
                + " | "
                + 构造任务管理观察事实承接请求文本(请求));
            return false;
        }
        项目运行日志(
            "自我线程/外设观察事实承接回查成功 | "
            + 构造外设观察报告摘要(*报告));
    }

    const auto now = 消息.头.产生时间 == 0
        ? 结构体_时间戳::当前_微秒()
        : 消息.头.产生时间;
    const std::uint64_t 主体主键 =
        请求.报告ID != 0
            ? 请求.报告ID
            : (消息.头.作用对象主键 != 0 ? 消息.头.作用对象主键 : 消息.头.动作主体主键);
    if (主体主键 == 0) {
        项目运行日志(
            "自我线程/外设观察事实承接失败 | 原因=缺少报告ID和治理主体 | "
            + 构造任务管理观察事实承接请求文本(请求));
        return false;
    }

    std::ostringstream 主体主键文本;
    主体主键文本 << "外设观察报告#" << 主体主键;

    bool 任一成功 = false;
    任一成功 =
        私有_落单个治理变化到自我内部世界(
            自我内部世界,
            自我线程消息协议::枚举_存在类型::外部系统,
            主体主键,
            主体主键文本.str(),
            "外设观察报告承接记录",
            自我线程消息协议::枚举_特征类型::未定义,
            "外设观察报告承接状态",
            "外设观察报告承接状态",
            特征值{},
            特征值{ static_cast<I64>(报告可回查 ? 1 : 0) },
            "外设观察事实承接请求",
            报告可回查 ? "报告缓存可回查，仅承接观察材料" : "报告缓存不可回查，证据不足",
            报告可回查,
            报告可回查,
            now)
        || 任一成功;

    if (报告可回查) {
        const auto 簇数量 = static_cast<I64>(
            报告->观察像素簇集合.size());
        任一成功 =
            私有_落单个治理变化到自我内部世界(
                自我内部世界,
                自我线程消息协议::枚举_存在类型::外部系统,
                主体主键,
                主体主键文本.str(),
                "外设观察报告承接记录",
                自我线程消息协议::枚举_特征类型::未定义,
                "外设观察像素簇数量",
                "外设观察像素簇数量",
                特征值{},
                特征值{ 簇数量 },
                "外设观察事实承接请求",
                "记录报告材料摘要，不生成世界存在真值",
                true,
                true,
                now)
            || 任一成功;

        if (请求.请求承接观察像素簇集合) {
            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部系统,
                    主体主键,
                    主体主键文本.str(),
                    "外设观察报告承接记录",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "观察像素簇集合承接状态",
                    "观察像素簇集合承接状态",
                    特征值{},
                    特征值{ static_cast<I64>(1) },
                    "自我承接观察像素簇集合",
                    "只承接观察材料，不确认世界存在",
                    true,
                    true,
                    now)
                || 任一成功;
        }

        if (请求.请求生成存在候选) {
            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部系统,
                    主体主键,
                    主体主键文本.str(),
                    "外设观察报告承接记录",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "存在候选集合状态",
                    "存在候选集合状态",
                    特征值{},
                    特征值{ static_cast<I64>(1) },
                    "自我由观察像素簇生成存在候选",
                    "生成候选记录，不确认观察存在",
                    true,
                    true,
                    now)
                || 任一成功;
            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部系统,
                    主体主键,
                    主体主键文本.str(),
                    "外设观察报告承接记录",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "存在候选数量",
                    "存在候选数量",
                    特征值{},
                    特征值{ 簇数量 },
                    "自我由观察像素簇生成存在候选",
                    "候选数量来自观察像素簇数量，不代表已确认存在",
                    true,
                    true,
                    now)
                || 任一成功;
        }

        if (请求.请求统计当前帧识别情况) {
            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部系统,
                    主体主键,
                    主体主键文本.str(),
                    "外设观察报告承接记录",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "存在识别摘要状态",
                    "存在识别摘要状态",
                    特征值{},
                    特征值{ static_cast<I64>(1) },
                    "自我统计当前帧存在识别情况",
                    "统计观察材料解释摘要，不确认世界对象全部成立",
                    true,
                    true,
                    now)
                || 任一成功;
            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部系统,
                    主体主键,
                    主体主键文本.str(),
                    "外设观察报告承接记录",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "未解释区域比例",
                    "未解释区域比例",
                    特征值{},
                    特征值{ static_cast<I64>(报告->未解释区域比例) },
                    "自我统计当前帧存在识别情况",
                    "报告字段转入识别摘要候选，不代表基础风险已明确",
                    true,
                    true,
                    now)
                || 任一成功;
        }

        constexpr std::size_t 外设观察事实承接同步簇入账上限 = 8;
        std::size_t 簇索引 = 0;
        for (const auto& 簇 : 报告->观察像素簇集合) {
            ++簇索引;
            std::ostringstream 簇键文本;
            簇键文本 << "外设观察像素簇#报告"
                << 报告->报告ID
                << "#簇"
                << 簇.外设内部簇ID;
            const auto 簇主键 = static_cast<std::uint64_t>(
                std::hash<std::string>{}(簇键文本.str()));

            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部对象,
                    簇主键,
                    簇键文本.str(),
                    "观察像素簇候选",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "观察像素簇像素数量",
                    "观察像素簇像素数量",
                    特征值{},
                    特征值{ static_cast<I64>(簇.像素数量) },
                    "自我承接观察像素簇集合",
                    "簇级观察材料承接，不确认稳定世界对象",
                    true,
                    true,
                    now)
                || 任一成功;
            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部对象,
                    簇主键,
                    簇键文本.str(),
                    "观察像素簇候选",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "观察像素簇深度有效率",
                    "观察像素簇深度有效率",
                    特征值{},
                    特征值{ static_cast<I64>(簇.深度有效率) },
                    "自我承接观察像素簇集合",
                    "簇级观察材料承接，不确认稳定世界对象",
                    true,
                    true,
                    now)
                || 任一成功;
            任一成功 =
                私有_落单个治理变化到自我内部世界(
                    自我内部世界,
                    自我线程消息协议::枚举_存在类型::外部对象,
                    簇主键,
                    簇键文本.str(),
                    "观察像素簇候选",
                    自我线程消息协议::枚举_特征类型::未定义,
                    "观察像素簇空间坐标有效率",
                    "观察像素簇空间坐标有效率",
                    特征值{},
                    特征值{ static_cast<I64>(簇.空间坐标有效率) },
                    "自我承接观察像素簇集合",
                    "簇级观察材料承接，不确认稳定世界对象",
                    true,
                    true,
                    now)
                || 任一成功;

            if (请求.请求生成存在候选) {
                任一成功 =
                    私有_落单个治理变化到自我内部世界(
                        自我内部世界,
                        自我线程消息协议::枚举_存在类型::外部对象,
                        簇主键,
                        簇键文本.str(),
                        "观察像素簇候选",
                        自我线程消息协议::枚举_特征类型::未定义,
                        "存在候选生成状态",
                        "存在候选生成状态",
                        特征值{},
                        特征值{ static_cast<I64>(1) },
                        "自我由观察像素簇生成存在候选",
                        "候选由簇材料生成，不等于已确认观察存在",
                        true,
                        true,
                        now)
                    || 任一成功;
            }

            if (簇索引 >= 外设观察事实承接同步簇入账上限) {
                项目运行日志(
                    "自我线程/外设观察事实承接截断簇入账"
                    " | 原因=同步条件包只入账前8个簇，完整簇集合保留在外设报告缓存"
                    " | 已入账簇=" + std::to_string(簇索引)
                    + " | 报告簇=" + std::to_string(报告->观察像素簇集合.size())
                    + " | " + 构造外设观察报告摘要(*报告));
                break;
            }
        }
    }

    项目运行日志(
        std::string("自我线程/外设观察事实承接完成 | 成功=")
        + (任一成功 ? "是" : "否")
        + " | 报告可回查="
        + (报告可回查 ? "是" : "否")
        + " | 禁止直接写世界真值=是 | "
        + 构造任务管理观察事实承接请求文本(请求));
    (void)私有_扫描材料承接后确保6146任务主体_线程侧(
        请求,
        报告 ? &*报告 : nullptr,
        任一成功,
        报告可回查,
        now);
    (void)私有_扫描材料承接后确保6147任务主体_线程侧(
        请求,
        报告 ? &*报告 : nullptr,
        任一成功,
        报告可回查,
        now);
    (void)私有_观察事实更新后刷新来源需求材料子需求_线程侧(
        请求,
        报告 ? &*报告 : nullptr,
        任一成功,
        报告可回查,
        now);
    (void)私有_观察事实更新后触发来源需求重筹办_线程侧(
        请求,
        报告 ? &*报告 : nullptr,
        任一成功,
        报告可回查,
        now);
    (void)私有_观察事实更新后触发安全根需求重筹办_线程侧(
        请求,
        报告 ? &*报告 : nullptr,
        任一成功,
        报告可回查,
        now);
    return 任一成功;
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_落自检报告到自我内部世界(
    const 自我线程消息协议::结构_治理消息& 消息) noexcept
{
    if (!消息.附加载荷.自检报告.has_value()) {
        return false;
    }

    const auto& 报告 = *消息.附加载荷.自检报告;
    const auto now = 消息.头.产生时间 == 0
        ? (报告.生成时间 == 0 ? 结构体_时间戳::当前_微秒() : 报告.生成时间)
        : 消息.头.产生时间;
    bool 任一成功 = false;
    for (const auto& 候选 : 报告.缺口候选集) {
        const auto 候选类型 = 私有_归一自检候选类型(候选);
        if (候选.建议生成需求
            || 候选类型 == 自我线程消息协议::枚举_自检候选类型::需求型) {
            任一成功 =
                私有_按自检候选生成正式需求节点(
                    自我,
                    候选,
                    now) != nullptr
                || 任一成功;
            continue;
        }
        if (!候选.建议生成需求
            || 候选类型 == 自我线程消息协议::枚举_自检候选类型::报告型) {
            项目运行日志(
                "自我线程/自检报告型候选已记录不入树 | "
                + 私有_构造自检候选门控文本(候选));
            任一成功 = true;
            continue;
        }
    }

    return 任一成功;
}

bool 私有_落任务管理结果到自我内部世界(
    const 自我线程消息协议::结构_治理消息& 消息,
    const std::vector<结构_任务管理状态变化项>* 服务对象状态变化覆盖 = nullptr,
    const std::vector<结构_任务管理关键中间状态变化项>* 关键中间状态变化覆盖 = nullptr) noexcept
{
    if (!消息.附加载荷.任务管理结果状态.has_value()) {
        return false;
    }

    const auto& 结果消息 = *消息.附加载荷.任务管理结果状态;
    const auto& 服务对象状态变化集 =
        服务对象状态变化覆盖 ? *服务对象状态变化覆盖 : 结果消息.服务对象状态变化集;
    const auto& 关键中间状态变化集 =
        关键中间状态变化覆盖 ? *关键中间状态变化覆盖 : 结果消息.关键中间状态变化集;
    bool 任一成功 =
        私有_落治理变化项集到自我内部世界(
            消息);
    if (!服务对象状态变化集.empty()) {
        任一成功 =
            私有_落任务管理状态变化集到自我内部世界(
                服务对象状态变化集,
                消息,
                消息.语义.动作语义键)
            || 任一成功;
    }
    if (!关键中间状态变化集.empty()) {
        任一成功 =
            私有_落任务管理关键中间状态变化集到自我内部世界(
                关键中间状态变化集,
                消息)
            || 任一成功;
    }
    私有_按成功结果满足来源需求并唤醒父任务_任务管理新链(
        自我,
        结果消息,
        消息.头.产生时间 == 0 ? 结构体_时间戳::当前_微秒() : 消息.头.产生时间);
    return 任一成功;
}

bool 私有_确保线程状态主体存在(
    const 结构_线程存在初始化参数& 线程存在初始化,
    存在节点类** 输出线程存在 = nullptr) noexcept
{
    auto* 线程存在 = 自我.确保线程子存在(线程存在初始化);
    if (输出线程存在) {
        *输出线程存在 = 线程存在;
    }
    return 线程存在 != nullptr;
}

// 功能：服务所在模块的内部辅助流程。
bool 私有_切换线程状态并上报_(
    const 结构_线程状态切换上报参数& 参数) noexcept
{
    const auto now = 参数.发生时间 == 0 ? 结构体_时间戳::当前_微秒() : 参数.发生时间;
    const auto 目标线程存在类型 =
        参数.线程存在类型 == 自我线程消息协议::枚举_存在类型::未定义
        ? 私有_推断线程存在类型(参数.线程存在初始化)
        : 参数.线程存在类型;
    const auto 决策者类型 =
        参数.决策者类型 == 自我线程消息协议::枚举_存在类型::未定义
        ? 私有_推断线程存在类型(参数.线程存在初始化)
        : 参数.决策者类型;

    if (决策者类型 == 自我线程消息协议::枚举_存在类型::自我线程
        && 目标线程存在类型 != 自我线程消息协议::枚举_存在类型::自我线程) {
        return false;
    }

    存在节点类* 线程存在 = nullptr;
    if (!私有_确保线程状态主体存在(
        参数.线程存在初始化,
        &线程存在)) {
        return false;
    }

    if (参数.旧状态 == 参数.新状态 && 参数.无变化时仅同步特征) {
        return true;
    }

    自我线程消息协议::结构_线程状态变化消息段 消息段{};
    消息段.发生时间 = now;
    消息段.决策者类型 = 决策者类型;
    消息段.决策者主键 = 参数.决策者主键;
    消息段.决策者标签 = 参数.决策者标签;
    消息段.触发动作 = 参数.触发动作;
    消息段.原因键 = 参数.原因键;
    消息段.原因摘要 = 参数.原因摘要;
    消息段.线程存在主键 = 私有_存在主键(线程存在);
    消息段.线程标签 = 私有_推断线程标签(参数.线程存在初始化);
    消息段.线程存在类型 = 目标线程存在类型;
    消息段.线程种类 = 私有_推断线程种类(参数.线程存在初始化);
    消息段.直属拥有者类型 = 参数.直属拥有者类型;
    消息段.直属拥有者主键 = 参数.直属拥有者主键;
    消息段.状态特征类型 = 参数.状态特征类型;
    消息段.旧状态 = 参数.旧状态;
    消息段.新状态 = 参数.新状态;
    消息段.是否故障触发 = 参数.是否故障触发;
    消息段.是否stop链触发 = 参数.是否stop链触发;
    消息段.关联任务主键 = 参数.关联任务主键;
    消息段.关联线程主键 =
        参数.关联线程主键 == 0
        ? 私有_存在主键(线程存在)
        : 参数.关联线程主键;

    if (消息段.直属拥有者主键 == 0) {
        消息段.直属拥有者主键 = 私有_确保线程直属拥有者主键(
            参数.线程存在初始化,
            &消息段.直属拥有者类型);
    }

    if (消息段.决策者主键 == 0
        && (消息段.决策者类型 == 消息段.线程存在类型
            || 消息段.决策者类型 == 自我线程消息协议::枚举_存在类型::自我线程)) {
        消息段.决策者主键 = 消息段.线程存在主键;
    }
    if (消息段.决策者标签.empty()
        && (消息段.决策者主键 == 消息段.线程存在主键)) {
        消息段.决策者标签 = 消息段.线程标签;
    }

    return 上报线程状态变化(
        消息段,
        &参数.线程存在初始化);
}

