// 功能：服务所在模块的内部辅助流程。
bool 私有_是任务管理成功结果消息(
    const 自我线程消息协议::结构_治理消息& 消息) noexcept
{
    if (!消息.附加载荷.任务管理结果状态.has_value()) {
        return false;
    }
    const auto& 结果状态 = *消息.附加载荷.任务管理结果状态;
    return 结果状态.是否成功
        || 结果状态.结果状态 == 枚举_任务管理结果状态::成功
        || 结果状态.结果状态 == 枚举_任务管理结果状态::收束完成;
}

std::deque<自我线程消息协议::结构_治理消息> 私有_抽取观察事实承接消息(
    std::deque<自我线程消息协议::结构_治理消息>* 活邮箱,
    std::size_t 最大数量 = 0)
{
    std::deque<自我线程消息协议::结构_治理消息> 抽取结果{};
    if (!活邮箱) {
        return 抽取结果;
    }

    for (auto it = 活邮箱->begin(); it != 活邮箱->end();) {
        if (!it->附加载荷.任务管理观察事实承接请求.has_value()) {
            ++it;
            continue;
        }
        if (最大数量 != 0 && 抽取结果.size() >= 最大数量) {
            break;
        }
        抽取结果.push_back(std::move(*it));
        it = 活邮箱->erase(it);
    }
    return 抽取结果;
}

