// 功能：服务所在模块的内部辅助流程。
bool 私有_冻结消息批次_限制观察承接(
    std::deque<自我线程消息协议::结构_治理消息>* 活邮箱,
    std::deque<自我线程消息协议::结构_治理消息>* 冻结批次,
    std::size_t 最大观察承接数量)
{
    if (!活邮箱 || !冻结批次) {
        return false;
    }
    if (!冻结批次->empty() || 活邮箱->empty()) {
        return !冻结批次->empty();
    }

    std::deque<自我线程消息协议::结构_治理消息> 剩余消息{};
    std::size_t 已冻结观察承接 = 0;
    while (!活邮箱->empty()) {
        auto 消息 = std::move(活邮箱->front());
        活邮箱->pop_front();
        const bool 是观察承接 =
            消息.附加载荷.任务管理观察事实承接请求.has_value();
        if (是观察承接
            && 最大观察承接数量 != 0
            && 已冻结观察承接 >= 最大观察承接数量) {
            剩余消息.push_back(std::move(消息));
            continue;
        }
        if (是观察承接) {
            ++已冻结观察承接;
        }
        冻结批次->push_back(std::move(消息));
    }
    *活邮箱 = std::move(剩余消息);
    return !冻结批次->empty();
}

