struct 结构_动态V1摘要 {
    bool 有变化量 = false;
    I64 变化量 = 0;
    bool 有变化方向 = false;
    I64 变化方向 = 0;
    std::string 变化方向语义{};
    bool 有持续时间 = false;
    I64 持续时间 = 0;
    bool 有变化率 = false;
    I64 变化率 = 0;
};



// 功能：从指定来源读取数据或状态。
结构_动态V1摘要 私有_读取场景最新动态V1摘要(
    场景节点类* 场景,
    const 基础信息节点类* 主体) noexcept
{
    结构_动态V1摘要 摘要{};
    if (!场景 || !主体) {
        return 摘要;
    }

    if (const auto* 主信息 = 世界树.二次特征生成().查找场景二次特征主信息(
            场景,
            "变化量",
            主体,
            枚举_二次特征域::动态,
            true)) {
        摘要.有变化量 = true;
        摘要.变化量 = 主信息->标量值;
    }
    if (const auto* 主信息 = 世界树.二次特征生成().查找场景二次特征主信息(
            场景,
            "变化方向",
            主体,
            枚举_二次特征域::动态,
            true)) {
        摘要.有变化方向 = true;
        摘要.变化方向 = 主信息->离散编码;
        摘要.变化方向语义 = 主信息->离散语义键;
    }
    if (const auto* 主信息 = 世界树.二次特征生成().查找场景二次特征主信息(
            场景,
            "持续时间",
            主体,
            枚举_二次特征域::动态,
            true)) {
        摘要.有持续时间 = true;
        摘要.持续时间 = 主信息->标量值;
    }
    if (const auto* 主信息 = 世界树.二次特征生成().查找场景二次特征主信息(
            场景,
            "变化率",
            主体,
            枚举_二次特征域::动态,
            true)) {
        摘要.有变化率 = true;
        摘要.变化率 = 主信息->标量值;
    }

    return 摘要;
}

