// 功能：服务所在模块的内部辅助流程。
结构_治理对象组 私有_构造治理对象组(
    场景节点类* 自我内部世界,
    const 结构_任务管理消息头& 消息头,
    const std::string& 当前方法主键) noexcept
{
    结构_治理对象组 输出{};
    输出.任务管理任务节点 = 私有_确保治理存在节点(
        自我内部世界,
        自我线程消息协议::枚举_存在类型::任务管理任务,
        消息头.任务管理任务主键,
        "任务管理任务");
    输出.当前任务节点 = 私有_确保治理存在节点(
        自我内部世界,
        自我线程消息协议::枚举_存在类型::任务,
        消息头.任务主键,
        "任务");
    输出.父任务节点 = 私有_确保治理存在节点(
        自我内部世界,
        自我线程消息协议::枚举_存在类型::任务,
        消息头.父任务主键,
        "父任务");
    if (!当前方法主键.empty()) {
        输出.方法节点 = 私有_确保治理存在节点(
            自我内部世界,
            自我线程消息协议::枚举_存在类型::方法,
            当前方法主键,
            "方法");
    }
    return 输出;
}

bool 私有_写治理二次特征候选(
    场景节点类* 自我内部世界,
    const 结构_治理二次特征候选& 候选,
    二次特征节点类** 输出节点 = nullptr) noexcept
{
    if (!自我内部世界 || 候选.概念名称.empty() || !候选.主体) {
        return false;
    }

    auto* 概念锚点 = 私有_确保二次特征概念锚点(
        自我内部世界,
        候选.概念名称);

    结构_场景二次特征写入请求 请求{};
    请求.概念名称 = 候选.概念名称;
    请求.概念词性 = "名词";
    请求.同步名称和类型 = true;
    请求.种类 = 候选.种类;
    请求.域 = 候选.域;
    请求.粒度 = 候选.粒度;
    请求.基准类型 = 候选.基准类型;
    请求.时间归一方式 = 候选.时间归一方式;
    请求.值形态 = 候选.值形态;
    请求.主体 = 候选.主体;
    请求.客体 = 候选.客体;
    请求.左对象 = 候选.左对象;
    请求.右对象 = 候选.右对象 ? 候选.右对象 : 概念锚点;
    请求.离散编码 = 候选.是否满足 ? 1 : 0;
    请求.标量值 = 候选.标量值;
    请求.是否满足 = 候选.是否满足;
    请求.置信度 = 候选.置信度;

    return 世界树.二次特征生成().写入场景二次特征(
        自我内部世界,
        请求,
        输出节点);
}

