// 功能：从指定来源读取数据或状态。
自我线程类::结构_自我线程最小状态快照 自我线程类::读取自我线程最小状态快照() const
{
    结构_自我线程最小状态快照 快照{};
    const auto* 生命周期特征 = 自我特征定义类::类型_线程_生命周期状态();
    const auto* 阶段特征 = 自我特征定义类::类型_线程_实际运行状态();
    const auto* 去向特征 = 自我特征定义类::类型_线程_控制意图();
    const auto* 当前需求特征 = 自我特征定义类::类型_自我_当前主需求();
    const auto* 当前任务特征 = 自我特征定义类::类型_自我_当前主任务();
    const auto* mailbox特征 = 自我特征定义类::类型_线程_邮箱深度();
    const auto* 健康特征 = 自我特征定义类::类型_线程_健康状态();
    const auto* Tick计数特征 = 自我特征定义类::类型_线程_Tick计数();
    const auto* 最近Tick时间特征 = 自我特征定义类::类型_线程_最近Tick时间();
    {
        std::scoped_lock 锁(状态锁_);
        快照.Tick计数抽象特征指针 = reinterpret_cast<std::uintptr_t>(Tick计数特征);
        快照.最近Tick时间抽象特征指针 = reinterpret_cast<std::uintptr_t>(最近Tick时间特征);
        快照.生命周期抽象特征指针 = reinterpret_cast<std::uintptr_t>(生命周期特征);
        快照.最近阶段抽象特征指针 = reinterpret_cast<std::uintptr_t>(阶段特征);
        快照.最近去向抽象特征指针 = reinterpret_cast<std::uintptr_t>(去向特征);
        快照.当前需求引用抽象特征指针 = reinterpret_cast<std::uintptr_t>(当前需求特征);
        快照.当前任务引用抽象特征指针 = reinterpret_cast<std::uintptr_t>(当前任务特征);
        快照.mailbox待消费数抽象特征指针 = reinterpret_cast<std::uintptr_t>(mailbox特征);
        快照.健康状态抽象特征指针 = reinterpret_cast<std::uintptr_t>(健康特征);
        快照.Tick计数值 = 私有_计数转I64(Tick计数_);
        快照.最近Tick时间值 = 最近Tick时间_;
        快照.生命周期值 = static_cast<I64>(生命周期_);
        if (最近循环结果_.当前运行阶段 != 枚举_自我线程运行阶段::未定义) {
            快照.最近阶段值 = static_cast<I64>(最近循环结果_.当前运行阶段);
        } else {
            快照.最近阶段值 = static_cast<I64>(枚举_自我线程运行阶段::未定义);
        }
        快照.最近去向值 = static_cast<I64>(最近循环结果_.当前最终去向);
        快照.mailbox待消费数值 = 私有_计数转I64(static_cast<std::uint64_t>(治理mailbox_.size()));
        快照.健康状态值 = 健康运行_ ? 1 : 0;
    }

    快照.当前需求指针 = reinterpret_cast<std::uintptr_t>(自我.获取当前主需求());
    快照.当前任务指针 = reinterpret_cast<std::uintptr_t>(自我.获取当前主任务());
    if (auto* 当前任务 = reinterpret_cast<任务节点*>(自我.获取当前主任务())) {
        if (auto* 任务虚拟存在 = 私有_取任务虚拟存在_任务管理新链(当前任务)) {
            快照.当前任务虚拟存在指针 =
                reinterpret_cast<std::uintptr_t>(任务虚拟存在);
            快照.当前任务虚拟存在主键 = 任务虚拟存在->获取主键();
            const auto 概念集 = 世界树.存在().获取概念集(任务虚拟存在);
            std::ostringstream 概念摘要;
            for (std::size_t i = 0; i < 概念集.size() && i < 4; ++i) {
                if (i > 0) {
                    概念摘要 << "/";
                }
                auto 名称 = 世界树.获取名称(reinterpret_cast<基础信息节点类*>(概念集[i]));
                if (名称.empty() && 概念集[i]) {
                    名称 = 概念集[i]->获取主键();
                }
                概念摘要 << 名称;
            }
            快照.当前任务虚拟存在概念摘要 = 概念摘要.str();
        } else {
            快照.当前任务虚拟存在主键 = 当前任务->主信息.任务虚拟存在.主键;
        }
    }
    return 快照;
}

