// 功能：按函数名执行对应处理。
自我线程类::结构_结算治理输出快照 自我线程类::处理任务满足反馈(
    任务类::节点类* 任务节点指针,
    I64 本次安全满足量,
    I64 本次服务满足量,
    I64 安全累计比例_百万分比,
    I64 服务累计比例_百万分比,
    时间戳 now,
    const std::string& 反馈事件主键)
{
    (void)本次安全满足量;
    (void)本次服务满足量;
    (void)安全累计比例_百万分比;
    (void)服务累计比例_百万分比;
    (void)now;
    自我线程类::结构_结算治理输出快照 快照{};
    快照.摘要 =
        "自我线程/公开任务满足反馈入口拒绝"
        " | 原因=缺结算域分类和VX0报告"
        " | 任务=" + (任务节点指针
            ? reinterpret_cast<任务节点*>(任务节点指针)->获取主键()
            : std::string("空"))
        + " | 反馈事件=" + (反馈事件主键.empty() ? std::string("空") : 反馈事件主键)
        + " | 不作为结算控制流入口=1";
    项目运行错误日志(快照.摘要);
    {
        std::scoped_lock 锁(状态锁_);
        最近结算治理输出快照_ = 快照;
    }
    return 快照;
}

// 功能：按函数名执行对应处理。
自我线程类::结构_结算治理输出快照 自我线程类::处理任务满足反馈(
    const std::string& 任务主键,
    I64 本次安全满足量,
    I64 本次服务满足量,
    I64 安全累计比例_百万分比,
    I64 服务累计比例_百万分比,
    时间戳 now,
    const std::string& 反馈事件主键)
{
    auto* 任务节点 = 私有_按主键解析任务节点(任务主键);
    return 处理任务满足反馈(
        reinterpret_cast<任务类::节点类*>(任务节点),
        本次安全满足量,
        本次服务满足量,
        安全累计比例_百万分比,
        服务累计比例_百万分比,
        now,
        反馈事件主键);
}

