// 功能：按函数名执行对应处理。
bool 自我线程类::投递治理消息(const 自我线程消息协议::结构_治理消息& 消息)
{
    std::scoped_lock 锁(状态锁_);
    if (停止请求_.load(std::memory_order_acquire)) {
        项目运行日志(
            "自我线程/治理消息入队跳过"
            " | 原因=停止请求中"
            " | 处理类型=" + std::to_string(static_cast<I64>(消息.头.处理类型))
            + " | 摘要=" + 消息.摘要);
        return false;
    }
    auto 副本 = 消息;
    if (副本.头.产生时间 == 0) {
        副本.头.产生时间 = 结构体_时间戳::当前_微秒();
    }
    if (副本.头.来源链 == 自我线程消息协议::枚举_消息来源链::未定义) {
        副本.头.来源链 = 自我线程消息协议::枚举_消息来源链::线程直达消息;
    }
    if (副本.头.优先级 == 自我线程消息协议::枚举_治理消息优先级::未定义) {
        副本.头.优先级 = 自我线程消息协议::默认消息优先级(副本.头.处理类型);
    }
    if (!副本.头.可抢占) {
        副本.头.可抢占 = 自我线程消息协议::默认可抢占(副本.头.处理类型);
    }
    if (副本.头.消息主键 == 0) {
        副本.头.消息主键 = ++治理事件序号_;
    }
    if (副本.载荷键.empty()) {
        副本.载荷键 = 自我线程消息批次执行器::生成消息幂等键(副本);
    }
    if (副本.摘要.empty()) {
        std::ostringstream 输出;
        输出 << 私有_治理消息处理类型文本(副本.头.处理类型) << "入队";
        副本.摘要 = 输出.str();
    }

    for (auto& 已有事件 : 治理mailbox_) {
        if (已有事件.载荷键 != 副本.载荷键 || 已有事件.轨迹.重放代数 != 副本.轨迹.重放代数) {
            continue;
        }
        if (私有_治理消息优先级值(副本.头.优先级) > 私有_治理消息优先级值(已有事件.头.优先级)) {
            已有事件.头.优先级 = 副本.头.优先级;
        }
        if (!副本.摘要.empty()) {
            已有事件.摘要 = 副本.摘要;
        }
        if (!副本.来源.来源主观察特征.empty()) {
            已有事件.来源.来源主观察特征 = 副本.来源.来源主观察特征;
        }
        if (副本.来源.允许正式资产提交) {
            已有事件.来源.允许正式资产提交 = true;
        }
        if (!副本.变化项集.empty()) {
            已有事件.变化项集 = 副本.变化项集;
        }
        if (副本.附加载荷.线程状态变化.has_value()) {
            已有事件.附加载荷.线程状态变化 = 副本.附加载荷.线程状态变化;
        }
        if (副本.附加载荷.任务管理线程状态.has_value()) {
            已有事件.附加载荷.任务管理线程状态 = 副本.附加载荷.任务管理线程状态;
        }
        if (副本.附加载荷.任务管理派生需求.has_value()) {
            已有事件.附加载荷.任务管理派生需求 = 副本.附加载荷.任务管理派生需求;
        }
        if (副本.附加载荷.任务管理观察事实承接请求.has_value()) {
            已有事件.附加载荷.任务管理观察事实承接请求 =
                副本.附加载荷.任务管理观察事实承接请求;
        }
        if (副本.附加载荷.任务管理执行前许可请求.has_value()) {
            已有事件.附加载荷.任务管理执行前许可请求 =
                副本.附加载荷.任务管理执行前许可请求;
        }
        if (副本.附加载荷.任务管理结果状态.has_value()) {
            已有事件.附加载荷.任务管理结果状态 = 副本.附加载荷.任务管理结果状态;
        }
        if (副本.附加载荷.执行尝试汇总.has_value()) {
            已有事件.附加载荷.执行尝试汇总 = 副本.附加载荷.执行尝试汇总;
        }
        if (副本.附加载荷.执行对账结果.has_value()) {
            已有事件.附加载荷.执行对账结果 = 副本.附加载荷.执行对账结果;
        }
        if (副本.附加载荷.自检报告.has_value()) {
            已有事件.附加载荷.自检报告 = 副本.附加载荷.自检报告;
        }
        if (副本.附加载荷.控制面板刷新请求.has_value()) {
            已有事件.附加载荷.控制面板刷新请求 = 副本.附加载荷.控制面板刷新请求;
        }
        std::stable_sort(治理mailbox_.begin(), 治理mailbox_.end(), 私有_消息排在前面);
        刷新治理恢复事件镜像_已加锁();
        唤醒条件_.notify_one();
        return true;
    }

    治理mailbox_.push_back(std::move(副本));
    std::stable_sort(治理mailbox_.begin(), 治理mailbox_.end(), 私有_消息排在前面);
    刷新治理恢复事件镜像_已加锁();
    唤醒条件_.notify_one();
    return true;
}

