// 功能：记录日志、动态、证据或运行痕迹。
void 自我线程类::记录自检报告待处理_(
    const 自我线程消息协议::结构_治理消息& 消息)
{
    if (!消息.附加载荷.自检报告.has_value()) {
        return;
    }

    const auto& 报告 = *消息.附加载荷.自检报告;
    const auto now = 消息.头.产生时间 != 0
        ? 消息.头.产生时间
        : (报告.生成时间 != 0 ? 报告.生成时间 : 结构体_时间戳::当前_微秒());

    std::scoped_lock 锁(状态锁_);
    auto& 快照 = 最近自检报告修复治理快照_;
    快照.已生成 = true;
    快照.最近报告时间 = now;

    std::uint64_t 新增报告数 = 0;
    std::uint64_t 正式需求候选数 = 0;
    std::uint64_t 新增待映射数 = 0;
    std::uint64_t 新增仅报告数 = 0;
    std::uint64_t 新增休眠评估数 = 0;
    std::uint64_t 候选序号 = 0;
    std::string 最近摘要{};
    std::string 最近处置{};

    for (const auto& 候选 : 报告.缺口候选集) {
        ++候选序号;
        const auto 候选类型 = 私有_归一自检候选类型(候选);
        最近摘要 = 私有_构造自检候选门控文本(候选);
        const auto 处置映射 = 私有_映射自检报告休眠处置(候选.缺口类型值);
        最近处置 =
            std::string(处置映射.处置类型)
            + " | 候选动作=" + 处置映射.休眠期候选动作
            + " | 需确认=" + (处置映射.需要映射确认 ? "是" : "否");
        if (候选.建议生成需求
            || 候选类型 == 自我线程消息协议::枚举_自检候选类型::需求型) {
            ++正式需求候选数;
            最近处置 = "正式需求候选转交自我线程入树裁决";
            continue;
        }

        const bool 已存在 = !候选.幂等键.empty()
            && std::ranges::any_of(
                待处理自检报告队列_,
                [&候选](const 结构_待处理自检报告项& 已有) noexcept {
                    return 已有.幂等键 == 候选.幂等键;
                });
        if (已存在) {
            continue;
        }

        结构_待处理自检报告项 项{};
        项.报告ID = 报告.报告ID;
        项.候选序号 = 候选序号;
        项.生成时间 = now;
        项.缺口类型值 = 候选.缺口类型值;
        项.严重程度值 = 候选.严重程度值;
        项.仅休眠期修复 = 处置映射.仅休眠期评估;
        项.需要映射确认 = 处置映射.需要映射确认;
        项.处置类型 = 处置映射.处置类型;
        项.休眠期候选动作 = 处置映射.休眠期候选动作;
        项.幂等键 = 候选.幂等键;
        项.摘要 = 最近摘要 + " | 处置=" + 最近处置;
        待处理自检报告队列_.push_back(std::move(项));
        ++新增报告数;
        if (处置映射.需要映射确认) {
            ++新增待映射数;
        }
        if (处置映射.仅休眠期评估) {
            ++新增休眠评估数;
        } else {
            ++新增仅报告数;
        }
        ++快照.累计接收报告候选数;
    }

    constexpr std::size_t 自检报告待处理上限 = 128;
    while (待处理自检报告队列_.size() > 自检报告待处理上限) {
        待处理自检报告队列_.pop_front();
    }

    const auto 待休眠数 = std::count_if(
        待处理自检报告队列_.begin(),
        待处理自检报告队列_.end(),
        [](const 结构_待处理自检报告项& 项) noexcept {
            return 项.仅休眠期修复;
        });
    const auto 待映射数 = std::count_if(
        待处理自检报告队列_.begin(),
        待处理自检报告队列_.end(),
        [](const 结构_待处理自检报告项& 项) noexcept {
            return 项.需要映射确认;
        });
    const auto 仅报告数 = std::count_if(
        待处理自检报告队列_.begin(),
        待处理自检报告队列_.end(),
        [](const 结构_待处理自检报告项& 项) noexcept {
            return !项.仅休眠期修复;
        });
    快照.待处理报告数 = static_cast<std::uint64_t>(待处理自检报告队列_.size());
    快照.待休眠修复报告数 = static_cast<std::uint64_t>(待休眠数);
    快照.待映射确认报告数 = static_cast<std::uint64_t>(待映射数);
    快照.仅报告保留数 = static_cast<std::uint64_t>(仅报告数);
    快照.休眠期评估报告数 = static_cast<std::uint64_t>(待休眠数);
    快照.最近报告摘要 = 最近摘要;
    快照.最近报告处置 = 最近处置;

    std::ostringstream 摘要;
    摘要 << "自检报告承接"
        << " | 新增报告=" << 新增报告数
        << " | 新增仅报告=" << 新增仅报告数
        << " | 新增休眠评估=" << 新增休眠评估数
        << " | 新增待映射=" << 新增待映射数
        << " | 正式需求候选=" << 正式需求候选数
        << " | 待处理=" << 快照.待处理报告数
        << " | 待休眠评估=" << 快照.休眠期评估报告数
        << " | 待映射确认=" << 快照.待映射确认报告数;
    快照.摘要 = 摘要.str();
}

// 功能：执行任务、方法或动作的主体逻辑。
void 自我线程类::执行休眠期自检报告修复门控_(
    时间戳 now,
    bool 当前允许休眠期修复)
{
    std::scoped_lock 锁(状态锁_);
    auto& 快照 = 最近自检报告修复治理快照_;
    快照.已生成 = true;
    快照.最近门控时间 = now;

    const auto 待休眠数 = std::count_if(
        待处理自检报告队列_.begin(),
        待处理自检报告队列_.end(),
        [](const 结构_待处理自检报告项& 项) noexcept {
            return 项.仅休眠期修复;
        });
    const auto 待映射数 = std::count_if(
        待处理自检报告队列_.begin(),
        待处理自检报告队列_.end(),
        [](const 结构_待处理自检报告项& 项) noexcept {
            return 项.需要映射确认;
        });
    const auto 仅报告数 = std::count_if(
        待处理自检报告队列_.begin(),
        待处理自检报告队列_.end(),
        [](const 结构_待处理自检报告项& 项) noexcept {
            return !项.仅休眠期修复;
        });
    快照.待处理报告数 = static_cast<std::uint64_t>(待处理自检报告队列_.size());
    快照.待休眠修复报告数 = static_cast<std::uint64_t>(待休眠数);
    快照.待映射确认报告数 = static_cast<std::uint64_t>(待映射数);
    快照.仅报告保留数 = static_cast<std::uint64_t>(仅报告数);
    快照.休眠期评估报告数 = static_cast<std::uint64_t>(待休眠数);
    快照.最近休眠期门控报告数 =
        当前允许休眠期修复 ? static_cast<std::uint64_t>(待休眠数) : 0;

    std::ostringstream 门控;
    if (当前允许休眠期修复) {
        门控 << "休眠期评估门控已打开"
            << " | 可评估=" << 待休眠数
            << " | 待映射确认=" << 待映射数
            << " | 自动动作=未授权";
    } else {
        门控 << "运行期仅记录自检报告"
            << " | 待休眠评估=" << 待休眠数
            << " | 仅报告保留=" << 仅报告数;
    }
    快照.最近门控摘要 = 门控.str();

    std::ostringstream 摘要;
    摘要 << "自检报告修复治理"
        << " | 待处理=" << 快照.待处理报告数
        << " | 待休眠评估=" << 快照.休眠期评估报告数
        << " | 待映射确认=" << 快照.待映射确认报告数
        << " | 门控=" << 快照.最近门控摘要;
    快照.摘要 = 摘要.str();
}

// 功能：按函数名执行对应处理。
void 自我线程类::主循环_()
{
    项目运行日志("自我线程/主循环 | 进入线程函数");
    const auto 运行态建立时间 = 结构体_时间戳::当前_微秒();
    枚举_线程生命周期状态 旧生命周期 = 枚举_线程生命周期状态::未启动;
    {
        std::scoped_lock 锁(状态锁_);
        旧生命周期 = 生命周期_;
        生命周期_ = 枚举_线程生命周期状态::运行中;
        健康运行_ = true;
        运行中_.store(true, std::memory_order_release);
    }
    (void)私有_切换自我线程生命周期并上报(
        旧生命周期,
        枚举_线程生命周期状态::运行中,
        运行态建立时间,
        "进入运行态",
        "自我线程/进入运行态",
        "自我线程已进入运行态",
        false,
        false);
    项目运行日志("自我线程/主循环 | 运行态已建立");

    while (!停止请求_.load(std::memory_order_acquire)) {
        const auto now = 结构体_时间戳::当前_微秒();
        try {
            const auto 结果 = 执行主循环一轮_(now);
            const auto 摘要 = 私有_运行摘要(结果);
            {
                std::scoped_lock 锁(状态锁_);
                ++Tick计数_;
                最近Tick时间_ = now;
                首轮运行已完成_ = true;
                健康运行_ = true;
                最近循环结果_ = 结果;
            }
        }
        catch (const std::exception& 异常) {
            枚举_线程生命周期状态 捕获前生命周期 = 枚举_线程生命周期状态::未启动;
            {
                std::scoped_lock 锁(状态锁_);
                停止请求_.store(true, std::memory_order_release);
                捕获前生命周期 = 生命周期_;
                故障收口_已加锁(now, 异常.what());
            }
            (void)私有_切换自我线程生命周期并上报(
                捕获前生命周期,
                枚举_线程生命周期状态::故障,
                now,
                "故障收口",
                "自我线程/运行时故障",
                异常.what(),
                true,
                false);
        }
        catch (...) {
            const std::string 摘要 = "unknown";
            枚举_线程生命周期状态 捕获前生命周期 = 枚举_线程生命周期状态::未启动;
            {
                std::scoped_lock 锁(状态锁_);
                停止请求_.store(true, std::memory_order_release);
                捕获前生命周期 = 生命周期_;
                故障收口_已加锁(now, 摘要);
            }
            (void)私有_切换自我线程生命周期并上报(
                捕获前生命周期,
                枚举_线程生命周期状态::故障,
                now,
                "故障收口",
                "自我线程/运行时故障",
                摘要,
                true,
                false);
        }

        std::unique_lock 锁(状态锁_);
        if (停止请求_.load(std::memory_order_acquire)) {
            break;
        }
        唤醒条件_.wait_for(锁, 配置_.Tick间隔, [this]() {
            return 停止请求_.load(std::memory_order_acquire)
                || !治理mailbox_.empty()
                || !本轮冻结治理批次_.empty();
        });
    }

    {
        const auto now = 结构体_时间戳::当前_微秒();
        bool 已切换状态 = false;
        枚举_线程生命周期状态 退出前生命周期 = 枚举_线程生命周期状态::未启动;
        {
            std::scoped_lock 锁(状态锁_);
            运行中_.store(false, std::memory_order_release);
            if (生命周期_ != 枚举_线程生命周期状态::故障) {
                退出前生命周期 = 生命周期_;
                生命周期_ = 枚举_线程生命周期状态::已停止;
                已切换状态 = true;
            }
        }
        if (已切换状态) {
            (void)私有_切换自我线程生命周期并上报(
                退出前生命周期,
                枚举_线程生命周期状态::已停止,
                now,
                "线程停止",
                "自我线程/已停止",
                "自我线程已停止",
                false,
                true);
        }
    }
    项目运行日志("自我线程/主循环 | 退出线程函数");
}

// 功能：执行任务、方法或动作的主体逻辑。
自我线程类::结构_循环结果 自我线程类::执行主循环一轮_(const 时间戳 now)
{
    结构_主循环骨架上下文 上下文{};
    上下文.当前时间 = now;
    上下文.结果.当前运行阶段 = 枚举_自我线程运行阶段::主循环消息归并;
    上下文.结果.当前最终去向 = 枚举_自我线程最终去向::继续提交;

    auto 收到停止请求 = [this, &上下文](const char* 阶段) {
        if (!停止请求_.load(std::memory_order_acquire)) {
            return false;
        }
        上下文.结果.当前运行阶段 = 枚举_自我线程运行阶段::停止请求中;
        上下文.结果.当前最终去向 = 枚举_自我线程最终去向::停止;
        上下文.结果.任务管理当前去向 = "停止请求";
        项目运行日志(
            std::string("自我线程/主循环停止检查 | 阶段=")
            + (阶段 ? 阶段 : "")
            + " | 跳过剩余步骤=1");
        return true;
    };
    auto 读取待落账派生需求消息数 = [this]() {
        std::size_t 数量 = 0;
        std::scoped_lock 锁(状态锁_);
        for (const auto& 消息 : 治理mailbox_) {
            if (消息.附加载荷.任务管理派生需求.has_value()) {
                ++数量;
            }
        }
        return 数量;
    };
    步骤_冻结本轮消息批次_(&上下文);
    if (收到停止请求("冻结消息批次后")) {
        return 上下文.结果;
    }
    步骤_规范化消息并落一次特征账_(&上下文);
    (void)抢占落账任务管理成功结果_(&上下文, "规范化消息后", now);
    (void)抢占落账任务管理派生需求_(&上下文, "规范化消息后", now);
    (void)抢占落账观察事实承接_(&上下文, "规范化消息后", now);
    (void)抢占审批执行前许可_(&上下文, "规范化消息后", now);
    if (收到停止请求("规范化消息后")) {
        return 上下文.结果;
    }
    if (const auto 待落账派生需求消息数 = 读取待落账派生需求消息数();
        待落账派生需求消息数 > 0) {
        上下文.结果.有派生需求待实例化 = true;
        上下文.结果.当前运行阶段 = 枚举_自我线程运行阶段::主循环消息归并;
        上下文.结果.当前最终去向 = 枚举_自我线程最终去向::转入缺口承接;
        上下文.结果.任务管理当前去向 = "等待派生需求入树";
        上下文.结果.治理mailbox待消费数 = 待落账派生需求消息数;
        项目运行日志(
            "自我线程/派生需求邮箱待落账，暂停本轮任务派发"
            " | 待落账派生需求消息=" + std::to_string(待落账派生需求消息数)
            + " | 下一轮优先冻结治理邮箱=1");
        return 上下文.结果;
    }
    步骤_重算受影响二次特征_(&上下文);
    (void)抢占落账任务管理成功结果_(&上下文, "二次特征重算后", now);
    (void)抢占落账任务管理派生需求_(&上下文, "二次特征重算后", now);
    (void)抢占审批执行前许可_(&上下文, "二次特征重算后", now);
    if (收到停止请求("二次特征重算后")) {
        return 上下文.结果;
    }
    步骤_刷新线程上下文并生成治理帧_(&上下文);
    (void)抢占落账任务管理成功结果_(&上下文, "治理帧刷新后", now);
    (void)抢占落账任务管理派生需求_(&上下文, "治理帧刷新后", now);
    (void)抢占审批执行前许可_(&上下文, "治理帧刷新后", now);
    if (收到停止请求("治理帧刷新后")) {
        return 上下文.结果;
    }
    步骤_整理需求并做根层重判_(&上下文);
    (void)抢占落账任务管理成功结果_(&上下文, "需求整理后", now);
    (void)抢占落账任务管理派生需求_(&上下文, "需求整理后", now);
    (void)抢占审批执行前许可_(&上下文, "需求整理后", now);
    if (收到停止请求("需求整理后")) {
        return 上下文.结果;
    }
    步骤_生成并执行主派发决议_(&上下文);
    if (收到停止请求("主派发后")) {
        return 上下文.结果;
    }
    (void)抢占落账任务管理成功结果_(&上下文, "主派发后", now);
    (void)抢占落账任务管理派生需求_(&上下文, "主派发后", now);
    (void)抢占审批执行前许可_(&上下文, "主派发后", now);
    (void)抢占落账观察事实承接_(&上下文, "主派发后", now);
    if (const auto 待落账派生需求消息数 = 读取待落账派生需求消息数();
        待落账派生需求消息数 > 0) {
        上下文.结果.有派生需求待实例化 = true;
        上下文.结果.当前运行阶段 = 枚举_自我线程运行阶段::主循环消息归并;
        上下文.结果.当前最终去向 = 枚举_自我线程最终去向::转入缺口承接;
        上下文.结果.任务管理当前去向 = "等待派生需求入树";
        上下文.结果.治理mailbox待消费数 = 待落账派生需求消息数;
        项目运行日志(
            "自我线程/主派发后派生需求邮箱待落账，暂停任务巡检"
            " | 待落账派生需求消息=" + std::to_string(待落账派生需求消息数)
            + " | 下一轮优先冻结治理邮箱=1");
        return 上下文.结果;
    }
    (void)抢占落账任务管理成功结果_(&上下文, "任务巡检前", now);
    (void)抢占落账任务管理派生需求_(&上下文, "任务巡检前", now);
    (void)抢占审批执行前许可_(&上下文, "任务巡检前", now);
    (void)抢占落账观察事实承接_(&上下文, "任务巡检前", now);
    {
        const auto 上行数 = 私有_提取并上报任务管理上行消息_线程侧("任务管理后台巡检后");
        if (上行数 > 0) {
            上下文.结果.任务管理治理触发 = true;
            上下文.结果.治理mailbox待消费数 += 上行数;
            (void)抢占落账任务管理成功结果_(&上下文, "任务管理后台上行后", now);
            (void)抢占落账任务管理派生需求_(&上下文, "任务管理后台上行后", now);
            (void)抢占审批执行前许可_(&上下文, "任务管理后台上行后", now);
            (void)抢占落账观察事实承接_(&上下文, "任务管理后台上行后", now);
        }
    }
    if (收到停止请求("任务管理后台上行后")) {
        return 上下文.结果;
    }

    const auto 服务治理维护 =
        私有_执行服务治理周期维护_线程侧(自我, now, Tick计数_);
    if (!服务治理维护.摘要.empty()) {
        上下文.结果.最近结算摘要 = 服务治理维护.摘要;
    }

    执行休眠期自检报告修复门控_(
        now,
        自我.是否待机状态()
            || 上下文.结果.当前最终去向 == 枚举_自我线程最终去向::待机);

    return 上下文.结果;
}

// 功能：按函数名执行对应处理。
void 自我线程类::步骤_冻结本轮消息批次_(结构_主循环骨架上下文* 上下文)
{
    if (!上下文) {
        return;
    }

    {
        std::scoped_lock 锁(状态锁_);
        上下文->命中治理邮箱事件 =
            私有_冻结消息批次_限制观察承接(
                &治理mailbox_,
                &本轮冻结治理批次_,
                自我线程观察事实承接冻结批量上限);
        上下文->本轮冻结消息 = 本轮冻结治理批次_;
        上下文->本轮治理消息批次 =
            自我线程消息批次执行器::拆分冻结治理邮箱批次(本轮冻结治理批次_);
        上下文->结果.治理mailbox待消费数 = 治理mailbox_.size();
        刷新治理恢复事件镜像_已加锁();
    }

    上下文->结果.当前运行阶段 = 枚举_自我线程运行阶段::主循环消息归并;
}

// 功能：按函数名执行对应处理。
void 自我线程类::步骤_规范化消息并落一次特征账_(结构_主循环骨架上下文* 上下文)
{
    if (!上下文) {
        return;
    }

    上下文->结果.当前运行阶段 = 枚举_自我线程运行阶段::主循环初始化补齐;
    if (上下文->本轮冻结消息.empty()) {
        return;
    }

    const auto 批次摘要 =
        自我线程消息处理器::处理治理消息批次(上下文->本轮治理消息批次.全部消息);
    上下文->结果.任务管理治理触发 =
        批次摘要.触发根层重判 || 批次摘要.触发主派发决议;
    上下文->结果.任务管理上位输入已刷新 = 批次摘要.触发需求队列刷新;
    上下文->结果.有派生需求待实例化 = 批次摘要.有派生需求待实例化;
    上下文->结果.有子结果待路由 = 批次摘要.有子结果待路由;

    auto 收到停止请求 = [this, 上下文](const char* 阶段) {
        if (!停止请求_.load(std::memory_order_acquire)) {
            return false;
        }
        上下文->结果.当前运行阶段 = 枚举_自我线程运行阶段::停止请求中;
        上下文->结果.当前最终去向 = 枚举_自我线程最终去向::停止;
        上下文->结果.任务管理当前去向 = "停止请求";
        项目运行日志(
            std::string("自我线程/规范化消息停止检查 | 阶段=")
            + (阶段 ? 阶段 : "")
            + " | 跳过剩余冻结消息=1");
        return true;
    };

    for (auto& 消息 : 上下文->本轮冻结消息) {
        if (收到停止请求("逐条落账前")) {
            break;
        }

        const auto 归并结果 = 私有_归并治理消息并对账(&执行尝试汇总表_, &消息);
        if (归并结果.命中执行尝试闭环) {
            上下文->结果.任务管理证据触发 = true;
        }

        bool 已落账 = false;
        if (归并结果.允许继续落账
            && 自我线程消息协议::是否线程状态变化治理消息(消息)) {
            项目运行日志(
                "线程状态治理消息跳过落账 | 原因=纯线程状态只进入控制面板线程信息表");
        } else if (归并结果.允许继续落账
            && 消息.附加载荷.任务管理派生需求.has_value()) {
            已落账 = 私有_落任务管理派生需求到自我内部世界(
                消息);
        } else if (归并结果.允许继续落账
            && 消息.附加载荷.任务管理执行前许可请求.has_value()) {
            已落账 = 私有_审批任务执行前许可请求_线程侧(
                消息);
        } else if (归并结果.允许继续落账
            && 消息.附加载荷.任务管理观察事实承接请求.has_value()) {
            已落账 = 私有_落任务管理观察事实承接请求到自我内部世界(
                消息);
        } else if (归并结果.允许继续落账
            && 消息.附加载荷.自检报告.has_value()) {
            记录自检报告待处理_(消息);
            已落账 = 私有_落自检报告到自我内部世界(消息);
        } else if (归并结果.允许继续落账
            && 消息.附加载荷.任务管理结果状态.has_value()) {
            已落账 = 私有_落任务管理结果到自我内部世界(
                消息,
                &归并结果.新增服务对象状态变化集,
                &归并结果.新增关键中间状态变化集);
        } else if (归并结果.允许继续落账 && !消息.变化项集.empty()) {
            已落账 = 私有_落治理变化项集到自我内部世界(
                消息);
        }

        if (已落账) {
            上下文->结果.任务管理证据触发 = true;
        }
        上下文->已消费消息 = 消息;

        if (收到停止请求("逐条落账后")) {
            break;
        }

        (void)抢占落账任务管理成功结果_(
            上下文,
            "规范化消息逐条落账后",
            结构体_时间戳::当前_微秒());
        if (收到停止请求("逐条成功结果抢占后")) {
            break;
        }

        (void)抢占落账任务管理派生需求_(
            上下文,
            "规范化消息逐条落账后",
            结构体_时间戳::当前_微秒());
        if (收到停止请求("逐条派生需求抢占后")) {
            break;
        }

        (void)抢占审批执行前许可_(
            上下文,
            "规范化消息逐条落账后",
            结构体_时间戳::当前_微秒(),
            16);
        if (收到停止请求("逐条许可抢占后")) {
            break;
        }

        (void)抢占落账观察事实承接_(
            上下文,
            "规范化消息逐条落账后",
            结构体_时间戳::当前_微秒());
        if (收到停止请求("逐条观察承接抢占后")) {
            break;
        }
    }

    {
        std::scoped_lock 锁(状态锁_);
        if (上下文->规范化后清空全局冻结批次) {
            本轮冻结治理批次_.clear();
        }
        上下文->结果.治理mailbox待消费数 = 治理mailbox_.size();
        刷新治理恢复事件镜像_已加锁();
    }
}

// 功能：按函数名执行对应处理。
bool 自我线程类::尝试抢占落账观察事实承接(
    const char* 来源,
    时间戳 now,
    std::size_t 最大承接数量)
{
    结构_主循环骨架上下文 上下文{};
    上下文.当前时间 = now == 0 ? 结构体_时间戳::当前_微秒() : now;
    上下文.结果.当前运行阶段 =
        枚举_自我线程运行阶段::主循环消息归并;
    上下文.结果.当前最终去向 =
        枚举_自我线程最终去向::继续提交;
    return 抢占落账观察事实承接_(
        &上下文,
        来源 ? 来源 : "任务管理调度让步",
        上下文.当前时间,
        最大承接数量 == 0
            ? 自我线程观察事实承接抢占批量上限
            : 最大承接数量);
}

// 功能：唤醒等待中的任务、线程或治理链。
bool 自我线程类::请求观察事实承接轻量唤醒(const char* 来源) noexcept
{
    bool 有待处理 = false;
    {
        std::scoped_lock 锁(状态锁_);
        有待处理 =
            私有_计数观察事实承接消息(治理mailbox_) > 0
            || 私有_计数观察事实承接消息(本轮冻结治理批次_) > 0
            || 私有_计数执行前许可请求消息(治理mailbox_) > 0
            || 私有_计数执行前许可请求消息(本轮冻结治理批次_) > 0;
    }
    if (有待处理) {
        唤醒条件_.notify_one();
    }
    (void)来源;
    return 有待处理;
}

// 功能：执行任务、方法或动作的主体逻辑。
bool 自我线程类::抢占审批执行前许可_(
    结构_主循环骨架上下文* 上下文,
    const char* 来源,
    const 时间戳 now,
    std::size_t 最大许可数量)
{
    if (!上下文) {
        return false;
    }
    if (停止请求_.load(std::memory_order_acquire)) {
        上下文->结果.当前运行阶段 = 枚举_自我线程运行阶段::停止请求中;
        上下文->结果.当前最终去向 = 枚举_自我线程最终去向::停止;
        上下文->结果.任务管理当前去向 = "停止请求";
        项目运行日志(
            std::string("自我线程/执行前许可抢占跳过")
            + " | 来源=" + (来源 ? 来源 : "空")
            + " | 原因=停止请求中");
        return false;
    }

    static thread_local bool 正在抢占执行前许可审批 = false;
    if (正在抢占执行前许可审批) {
        return false;
    }
    正在抢占执行前许可审批 = true;
    struct 结构_抢占执行前许可审批守卫 {
        bool& 标记;

        // 功能：释放或收束对象资源。
        ~结构_抢占执行前许可审批守卫() noexcept
        {
            标记 = false;
        }
    } 抢占守卫{正在抢占执行前许可审批};

    std::deque<自我线程消息协议::结构_治理消息> 抢占许可消息{};
    std::size_t 待审批许可数 = 0;
    std::size_t 抽取后剩余mailbox消息数 = 0;
    const auto 抢占上限 = 最大许可数量 == 0
        ? 自我线程执行前许可抢占批量上限
        : 最大许可数量;
    {
        std::scoped_lock 锁(状态锁_);
        抢占许可消息 = 私有_抽取执行前许可请求消息(
            &治理mailbox_,
            抢占上限);
        待审批许可数 = 抢占许可消息.size();
        抽取后剩余mailbox消息数 = 治理mailbox_.size();
        if (待审批许可数 > 0) {
            刷新治理恢复事件镜像_已加锁();
        }
    }
    if (待审批许可数 == 0) {
        return false;
    }

    结构_主循环骨架上下文 抢占上下文{};
    抢占上下文.当前时间 = now == 0 ? 结构体_时间戳::当前_微秒() : now;
    抢占上下文.结果.当前运行阶段 =
        枚举_自我线程运行阶段::主循环消息归并;
    抢占上下文.结果.当前最终去向 = 上下文->结果.当前最终去向;
    抢占上下文.本轮冻结消息 = std::move(抢占许可消息);
    抢占上下文.本轮治理消息批次 =
        自我线程消息批次执行器::拆分冻结治理邮箱批次(
            抢占上下文.本轮冻结消息);
    抢占上下文.结果.治理mailbox待消费数 = 抽取后剩余mailbox消息数;
    抢占上下文.规范化后清空全局冻结批次 = false;

    步骤_规范化消息并落一次特征账_(&抢占上下文);

    上下文->结果.任务管理治理触发 =
        上下文->结果.任务管理治理触发
        || 抢占上下文.结果.任务管理治理触发;
    上下文->结果.任务管理证据触发 =
        上下文->结果.任务管理证据触发
        || 抢占上下文.结果.任务管理证据触发;
    上下文->结果.任务管理上位输入已刷新 =
        上下文->结果.任务管理上位输入已刷新
        || 抢占上下文.结果.任务管理上位输入已刷新;
    上下文->结果.有派生需求待实例化 =
        上下文->结果.有派生需求待实例化
        || 抢占上下文.结果.有派生需求待实例化;
    上下文->结果.有子结果待路由 =
        上下文->结果.有子结果待路由
        || 抢占上下文.结果.有子结果待路由;
    上下文->结果.治理mailbox待消费数 =
        抢占上下文.结果.治理mailbox待消费数;

    (void)来源;
    return true;
}

